evaluate <- function(scores) {
  if (!is.numeric(scores) || length(scores) == 0) {
    stop("scores must be a non-empty numeric vector")
  }
  clean <- scores[!is.na(scores)]
  n <- length(clean)
  if (n == 0) {
    stop("scores contains no usable values")
  }
  total <- sum(clean)
  mean_value <- total / n
  deviations <- clean - mean_value
  if (n > 1) {
    variance <- sum(deviations^2) / (n - 1)
  } else {
    variance <- 0
  }
  sd_value <- sqrt(variance)
  ordered <- sort(clean)
  middle <- (n + 1) / 2
  if (n %% 2 == 1) {
    median_value <- ordered[middle]
  } else {
    median_value <- (ordered[n / 2] + ordered[n / 2 + 1]) / 2
  }
  max_value <- ordered[n]
  min_value <- ordered[1]
  passing <- sum(clean >= 50)
  span <- max_value - min_value
  list(
    mean = mean_value,
    sd = sd_value,
    median = median_value,
    max = max_value,
    min = min_value,
    passing = passing,
    range = span
  )
}

format_report <- function(label, metrics) {
  header <- sprintf("=== %s ===", label)
  lines <- c(
    header,
    sprintf("mean    : %.2f", metrics$mean),
    sprintf("sd      : %.2f", metrics$sd),
    sprintf("median  : %.2f", metrics$median),
    sprintf("max     : %.2f", metrics$max),
    sprintf("min     : %.2f", metrics$min),
    sprintf("passing : %d", as.integer(metrics$passing)),
    sprintf("range   : %.2f", metrics$range)
  )
  paste(lines, collapse = "\n")
}

pass_rate <- function(metrics, scores) {
  usable <- scores[!is.na(scores)]
  rate <- metrics$passing / length(usable)
  round(100 * rate, 1)
}

main <- function() {
  demo <- c(10, 20, 30)
  exam <- c(45, 72, 88, 50, 39, 91, 66, 58)
  for (item in list(list("Demo", demo), list("Midterm exam", exam))) {
    label <- item[[1]]
    values <- item[[2]]
    metrics <- evaluate(values)
    cat(format_report(label, metrics), "\n")
    cat(sprintf("pass %%  : %.1f\n\n", pass_rate(metrics, values)))
  }
}

main()

