walk <- function(steps) {
  if (!is.numeric(steps)) {
    stop("steps must be a numeric vector")
  }
  if (anyNA(steps)) {
    stop("steps must not contain missing values")
  }
  position <- 0
  max_position <- 0
  min_position <- 0
  zero_visits <- 0
  total_distance <- 0
  for (increment in steps) {
    position <- position + increment
    total_distance <- total_distance + abs(increment)
    if (position > max_position) {
      max_position <- position
    }
    if (position < min_position) {
      min_position <- position
    }
    if (position == 0) {
      zero_visits <- zero_visits + 1
    }
  }
  list(final_position = position,
       max_position = max_position,
       min_position = min_position,
       zero_visits = zero_visits,
       total_distance = total_distance)
}

walk_trace <- function(steps) {
  cumulative <- cumsum(c(0, steps))
  data.frame(step_index = seq_along(cumulative) - 1,
             increment = c(NA, steps),
             position = cumulative)
}

format_walk <- function(result) {
  field_names <- c("Final position", "Maximum position", "Minimum position",
                   "Zero visits", "Total distance")
  values <- c(result$final_position, result$max_position, result$min_position,
              result$zero_visits, result$total_distance)
  paste0(format(field_names, width = max(nchar(field_names))), " : ", values)
}

report_walk <- function(name, steps) {
  result <- walk(steps)
  header <- paste0(name, " -> steps: ", paste(steps, collapse = ", "))
  cat(header, "\n", sep = "")
  cat(format_walk(result), sep = "\n")
  history <- walk_trace(steps)
  peaks <- history$step_index[history$position == result$max_position]
  cat("Maximum first reached at step ", min(peaks), "\n\n", sep = "")
  invisible(result)
}

main <- function() {
  simple <- c(1, -1, 2)
  oscillating <- c(3, -3, 3, -3, 5, -5)
  drifting <- c(-2, -4, 1, 1, -1, 6, 2)
  report_walk("simple", simple)
  report_walk("oscillating", oscillating)
  deep <- report_walk("drifting", drifting)
  span <- deep$max_position - deep$min_position
  cat("Drifting walk spanned ", span, " units of ground\n", sep = "")
  efficiency <- deep$final_position / deep$total_distance
  cat("Net displacement per unit travelled: ", round(efficiency, 3), "\n", sep = "")
}

main()

