split_lines <- function(text) {
  raw <- strsplit(text, "\n", fixed = TRUE)[[1]]
  trimmed <- trimws(raw, which = "right")
  trimmed[nzchar(trimmed)]
}

split_fields <- function(line) {
  parts <- strsplit(line, ",", fixed = TRUE)[[1]]
  trimws(parts)
}

to_number <- function(value) {
  number <- suppressWarnings(as.numeric(value))
  if (is.na(number)) {
    stop(sprintf("cannot convert '%s' to a numeric value", value))
  }
  number
}

parse <- function(text) {
  lines <- split_lines(text)
  if (length(lines) == 0) {
    stop("input contains no lines")
  }
  header <- split_fields(lines[1])
  body <- lines[-1]
  rows <- vector("list", length(body))
  over_hundred <- 0
  for (i in seq_along(body)) {
    fields <- split_fields(body[i])
    if (length(fields) < 2) {
      stop(sprintf("row %d has fewer than two fields", i))
    }
    amount <- to_number(fields[2])
    fields[2] <- amount
    rows[[i]] <- fields
    if (amount > 100) {
      over_hundred <- over_hundred + 1
    }
  }
  list(header = header, row_count = length(rows),
       over_hundred = over_hundred, rows = rows)
}

format_row <- function(row) {
  paste(row, collapse = " | ")
}

report <- function(parsed) {
  head_line <- format_row(parsed$header)
  bar <- strrep("-", nchar(head_line))
  body_lines <- vapply(parsed$rows, format_row, character(1))
  summary_line <- sprintf("%d data rows, %d with value over 100",
                          parsed$row_count, parsed$over_hundred)
  paste(c(head_line, bar, body_lines, "", summary_line), collapse = "\n")
}

main <- function() {
  sample <- paste("name, amount, region",
                  "Alice, 250.5, North",
                  " Bob , 99 , South",
                  "Carol, 100, East",
                  "Dan, 1000, West",
                  sep = "\n")
  parsed <- parse(sample)
  cat(report(parsed), "\n", sep = "")

  single <- "id, score\nX1, 42"
  small <- parse(single)
  cat(sprintf("single-row input: %d row(s), %d over 100\n",
              small$row_count, small$over_hundred))
}

main()

