moving_avg_at <- function(prices, day, window) {
  start <- day - window + 1
  mean(prices[start:day])
}

crossover <- function(prices) {
  if (!is.numeric(prices)) {
    stop("prices must be a numeric vector")
  }
  n <- length(prices)
  ma3 <- numeric(0)
  ma5 <- numeric(0)
  for (day in seq_len(n)) {
    if (day >= 3) {
      ma3[day] <- moving_avg_at(prices, day, 3)
    } else {
      ma3[day] <- NA_real_
    }
    if (day >= 5) {
      ma5[day] <- moving_avg_at(prices, day, 5)
    } else {
      ma5[day] <- NA_real_
    }
  }
  days_above <- 0
  crossovers <- 0
  max_diff <- -Inf
  for (day in seq_len(n)) {
    if (is.na(ma3[day]) || is.na(ma5[day])) {
      next
    }
    diff_today <- ma3[day] - ma5[day]
    if (diff_today > 0) {
      days_above <- days_above + 1
      prev <- day - 1
      if (prev >= 1 && !is.na(ma3[prev]) && !is.na(ma5[prev]) && ma3[prev] <= ma5[prev]) {
        crossovers <- crossovers + 1
      }
    }
    if (diff_today > max_diff) {
      max_diff <- diff_today
    }
  }
  if (is.infinite(max_diff)) {
    max_diff <- NA_real_
  }
  list(days_above = days_above, crossovers = crossovers, max_diff = max_diff)
}

format_report <- function(result, label) {
  diff_text <- if (is.na(result$max_diff)) "n/a" else sprintf("%.4f", result$max_diff)
  lines <- c(
    sprintf("Series: %s", label),
    sprintf("  Days 3MA above 5MA : %d", result$days_above),
    sprintf("  Bullish crossovers : %d", result$crossovers),
    sprintf("  Max 3MA-5MA spread : %s", diff_text)
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  trending <- c(10, 10.5, 11, 10.8, 11.4, 12, 12.6, 13.1, 12.9, 13.8)
  choppy <- c(50, 49, 51, 48, 52, 47, 53, 46, 54, 45, 55)
  flat <- c(20, 20, 20, 20)
  series <- list(trending = trending, choppy = choppy, flat = flat)
  for (label in names(series)) {
    result <- crossover(series[[label]])
    cat(format_report(result, label), "\n\n", sep = "")
  }
}

main()

