validate_transactions <- function(transactions) {
  if (!is.numeric(transactions)) {
    stop("transactions must be a numeric vector of unit counts")
  }
  if (any(!is.finite(transactions))) {
    stop("transactions must not contain NA, NaN or infinite values")
  }
  if (any(transactions != trunc(transactions))) {
    stop("transactions must contain whole numbers of units")
  }
  counts <- as.integer(transactions)
  stock <- cumsum(counts)
  if (any(stock < 0L)) {
    first_bad <- which(stock < 0L)[1]
    stop(sprintf("transaction %d sells more units than are in stock", first_bad))
  }
  counts
}

value <- function(transactions) {
  counts <- validate_transactions(transactions)
  queue <- numeric(0)
  front <- 1L
  price <- 10
  purchase_total <- 0
  cogs <- 0
  for (units in counts) {
    if (units > 0L) {
      queue <- c(queue, rep(price, units))
      purchase_total <- purchase_total + price * units
      price <- price + 1
    } else if (units < 0L) {
      sold <- -units
      taken <- queue[seq.int(front, length.out = sold)]
      cogs <- cogs + sum(taken)
      front <- front + sold
    }
  }
  remaining <- if (front > length(queue)) numeric(0) else queue[front:length(queue)]
  list(total_purchased = purchase_total,
       cost_of_goods_sold = cogs,
       inventory_value = sum(remaining))
}

format_dollars <- function(amount) {
  sprintf("$%s", formatC(amount, format = "f", digits = 2, big.mark = ","))
}

report <- function(transactions) {
  metrics <- value(transactions)
  units_left <- sum(transactions)
  lines <- c(
    sprintf("Transactions:        %s", paste(transactions, collapse = " ")),
    sprintf("Total purchased:     %s", format_dollars(metrics$total_purchased)),
    sprintf("Cost of goods sold:  %s", format_dollars(metrics$cost_of_goods_sold)),
    sprintf("Inventory value:     %s (%d units)",
            format_dollars(metrics$inventory_value), units_left)
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  simple <- c(1L, -1L)
  mixed <- c(5L, -3L, 4L, -2L, 6L, -7L)
  bulk <- c(10L, 10L, -15L, 20L, -8L)
  for (case in list(simple, mixed, bulk)) {
    cat(report(case), "\n\n", sep = "")
  }
}

main()

