normalize <- function(series) {
  if (!is.numeric(series)) {
    stop("normalize() requires a numeric vector")
  }
  if (anyNA(series)) {
    stop("normalize() cannot handle missing values")
  }
  scaled <- numeric(0)
  n <- length(series)
  for (i in seq_len(n)) {
    start <- max(1L, i - 2L)
    window <- series[start:i]
    lo <- min(window)
    hi <- max(window)
    if (lo == hi) {
      value <- 0
    } else {
      value <- (series[i] - lo) / (hi - lo)
    }
    scaled <- c(scaled, value)
  }
  ones <- sum(scaled == 1)
  average <- if (n > 0L) mean(scaled) else 0
  list(scaled = scaled, ones = ones, average = average)
}

parse_series <- function(text) {
  pieces <- strsplit(text, "[,[:space:]]+")[[1]]
  pieces <- pieces[nzchar(pieces)]
  numbers <- suppressWarnings(as.numeric(pieces))
  bad <- pieces[is.na(numbers)]
  if (length(bad) > 0L) {
    stop(paste("not numeric:", paste(bad, collapse = ", ")))
  }
  numbers
}

format_report <- function(label, result) {
  rounded <- round(result$scaled, 4)
  lines <- character(0)
  lines <- c(lines, paste0(label, ":"))
  lines <- c(lines, paste("  scaled :", paste(rounded, collapse = " ")))
  lines <- c(lines, paste("  ones   :", result$ones))
  lines <- c(lines, paste("  average:", round(result$average, 4)))
  paste(lines, collapse = "\n")
}

main <- function() {
  inputs <- c(
    "1, 2, 3, 4, 5",
    "7 7 7 7",
    "10, 3, 8, 1, 9, 2, 2, 6"
  )
  for (text in inputs) {
    series <- parse_series(text)
    result <- normalize(series)
    cat(format_report(text, result), "\n\n", sep = "")
  }
  combined <- parse_series(paste(inputs, collapse = " "))
  summary <- normalize(combined)
  peak <- which(summary$scaled == 1)
  cat("combined length:", length(combined), "\n")
  cat("window peaks at positions:", paste(peak, collapse = " "), "\n")
  cat("mean normalized value:", round(summary$average, 4), "\n")
}

main()

