normalize_sequence <- function(dna) {
  if (!is.character(dna) || length(dna) != 1 || is.na(dna)) {
    stop("dna must be a single non-missing character string")
  }
  upper <- toupper(dna)
  chars <- strsplit(upper, "", fixed = TRUE)[[1]]
  valid <- chars %in% c("A", "C", "G", "T")
  if (!all(valid)) {
    bad <- unique(chars[!valid])
    stop(paste("invalid bases:", paste(bad, collapse = ", ")))
  }
  chars
}

gc_percentage <- function(chars) {
  total <- length(chars)
  if (total == 0) return(0)
  g_count <- sum(chars == "G")
  c_count <- sum(chars == "C")
  100 * (g_count + c_count) / total
}

longest_gc_run <- function(chars) {
  best <- 0
  current <- 0
  for (base in chars) {
    if (base == "G" || base == "C") {
      current <- current + 1
      if (current > best) {
        best <- current
      }
    } else {
      current <- 0
    }
  }
  best
}

gc_group_count <- function(chars) {
  n <- length(chars)
  starts <- seq_len(n %/% 3) * 3 - 2
  count <- 0
  for (start in starts) {
    group <- chars[start:(start + 2)]
    if (all(group %in% c("G", "C"))) {
      count <- count + 1
    }
  }
  count
}

process <- function(dna) {
  chars <- normalize_sequence(dna)
  list(
    length = length(chars),
    gc_percent = gc_percentage(chars),
    longest_run = longest_gc_run(chars),
    gc_groups = gc_group_count(chars)
  )
}

format_report <- function(dna, stats) {
  header <- paste0("Sequence: ", toupper(dna))
  body <- c(
    paste("  total bases :", stats$length),
    paste("  GC percent  :", sprintf("%.2f%%", stats$gc_percent)),
    paste("  longest run :", stats$longest_run),
    paste("  GC codons   :", stats$gc_groups)
  )
  paste(c(header, body), collapse = "\n")
}

main <- function() {
  samples <- c("GGCCATGCGCGTAAGGCCCTG", "attgcaggcc", "GCGCGCGC")
  for (sample in samples) {
    stats <- process(sample)
    cat(format_report(sample, stats), "\n\n", sep = "")
  }
}

main()

