points <- function(purchases) {
  total <- 0
  bonuses <- 0
  best <- 0
  for (amount in purchases) {
    base <- min(amount, 50)
    extra <- max(amount - 50, 0)
    earned <- base + 2 * extra
    if (total > 500) {
      earned <- earned * 1.1
      bonuses <- bonuses + 1
    }
    if (earned > best) {
      best <- earned
    }
    total <- total + earned
  }
  list(total = total, bonuses = bonuses, best = best)
}

clean_purchases <- function(purchases) {
  if (!is.numeric(purchases)) {
    stop("purchases must be a numeric vector")
  }
  finite <- purchases[is.finite(purchases)]
  negatives <- finite[finite < 0]
  if (length(negatives) > 0) {
    warning(sprintf("dropping %d negative purchase amount(s)", length(negatives)))
  }
  finite[finite >= 0]
}

format_reward <- function(result) {
  lines <- c(
    sprintf("Total points earned : %.1f", result$total),
    sprintf("Bonus purchases     : %d", result$bonuses),
    sprintf("Highest single reward: %.1f", result$best)
  )
  paste(lines, collapse = "\n")
}

reward_report <- function(purchases) {
  amounts <- clean_purchases(purchases)
  result <- points(amounts)
  spend <- sum(amounts)
  rate <- if (spend > 0) result$total / spend else 0
  header <- sprintf("%d purchase(s) totalling $%.2f", length(amounts), spend)
  footer <- sprintf("Average points per dollar: %.2f", rate)
  paste(header, format_reward(result), footer, sep = "\n")
}

main <- function() {
  small_basket <- c(20, 35, 12.5)
  loyal_basket <- c(120, 80, 200, 60, 45, 310)
  messy_basket <- c(75, -10, 500, Inf, 25)
  baskets <- list(small = small_basket, loyal = loyal_basket, messy = messy_basket)
  for (name in names(baskets)) {
    cat("Customer:", name, "\n")
    cat(reward_report(baskets[[name]]), "\n\n")
  }
  top <- points(loyal_basket)
  cat(sprintf("Loyal customer best single reward was %.1f points\n", top$best))
}

main()

