compress <- function(data) {
  if (length(data) == 0) {
    return(list(values = character(0), counts = numeric(0),
                max_run = 0, singles = 0))
  }
  values <- character(0)
  counts <- numeric(0)
  run <- 1
  for (i in seq(2, length.out = length(data) - 1)) {
    if (identical(data[i], data[i - 1])) {
      run <- run + 1
    } else {
      values <- c(values, data[i - 1])
      counts <- c(counts, run)
      run <- 1
    }
  }
  values <- c(values, data[length(data)])
  counts <- c(counts, run)
  max_run <- max(counts)
  singles <- sum(counts == 1)
  list(values = values, counts = counts, max_run = max_run, singles = singles)
}

decompress <- function(encoded) {
  rep(encoded$values, times = encoded$counts)
}

format_runs <- function(encoded) {
  pieces <- paste0(encoded$counts, "x", encoded$values)
  paste(pieces, collapse = " ")
}

report <- function(label, data) {
  encoded <- compress(data)
  restored <- decompress(encoded)
  status <- if (identical(restored, data)) "ok" else "MISMATCH"
  cat(label, "\n")
  cat("  input   :", paste(data, collapse = " "), "\n")
  cat("  runs    :", format_runs(encoded), "\n")
  cat("  longest :", encoded$max_run, "\n")
  cat("  singles :", encoded$singles, "\n")
  cat("  restore :", status, "\n")
  encoded
}

main <- function() {
  weather <- c("sun", "sun", "sun", "rain", "rain", "fog", "sun", "sun")
  letters_in <- strsplit("aaabbbbccdaaa", "")[[1]]
  singleton <- c("only")
  summaries <- list()
  summaries$weather <- report("weather observations", weather)
  summaries$letters <- report("letter stream", letters_in)
  summaries$singleton <- report("single reading", singleton)
  total_runs <- sum(sapply(summaries, function(e) length(e$counts)))
  busiest <- max(sapply(summaries, function(e) e$max_run))
  cat("total runs across datasets:", total_runs, "\n")
  cat("longest run across datasets:", busiest, "\n")
}

main()

