evaluate_quadratic <- function(coefficients, x) {
  a_coef <- coefficients[1]
  b_coef <- coefficients[2]
  c_coef <- coefficients[3]
  a_coef * x^2 + b_coef * x + c_coef
}

validate_coefficients <- function(coefficients) {
  if (!is.numeric(coefficients) || length(coefficients) != 3) {
    stop("coefficients must be a numeric vector of length 3")
  }
  if (any(!is.finite(coefficients))) {
    stop("coefficients must all be finite")
  }
  if (coefficients[1] == 0) {
    stop("the leading coefficient 'a' must be non-zero")
  }
  invisible(TRUE)
}

solve <- function(coefficients) {
  validate_coefficients(coefficients)
  a_coef <- coefficients[1]
  b_coef <- coefficients[2]
  c_coef <- coefficients[3]

  discriminant <- b_coef^2 - 4 * a_coef * c_coef
  roots <- numeric(0)

  if (discriminant > 0) {
    root_span <- sqrt(discriminant)
    roots <- c((-b_coef + root_span) / (2 * a_coef),
               (-b_coef - root_span) / (2 * a_coef))
  } else if (discriminant == 0) {
    roots <- -b_coef / (2 * a_coef)
  }

  vertex_x <- -b_coef / (2 * a_coef)
  vertex_y <- evaluate_quadratic(coefficients, vertex_x)

  list(discriminant = discriminant,
       roots = roots,
       vertex_x = vertex_x,
       vertex_y = vertex_y)
}

format_equation <- function(coefficients) {
  b_sign <- if (coefficients[2] < 0) "-" else "+"
  c_sign <- if (coefficients[3] < 0) "-" else "+"
  sprintf("%gx^2 %s %gx %s %g", coefficients[1],
          b_sign, abs(coefficients[2]), c_sign, abs(coefficients[3]))
}

report <- function(coefficients) {
  result <- solve(coefficients)
  root_text <- if (length(result$roots) == 0) {
    "none (complex roots)"
  } else {
    paste(formatC(result$roots, digits = 6, format = "g"), collapse = ", ")
  }
  vertex_text <- sprintf("(%g, %g)", result$vertex_x, result$vertex_y)

  cat(format_equation(coefficients), "\n")
  cat("  discriminant:", result$discriminant, "\n")
  cat("  real roots:", root_text, "\n")
  cat("  vertex:", vertex_text, "\n\n")
  invisible(result)
}

main <- function() {
  examples <- list(c(1, -3, 2), c(1, 2, 1), c(2, 1, 3), c(-1, 4, -1))
  for (coefficients in examples) {
    report(coefficients)
  }
}

main()

