  c_sign = if (coefficients[3] < 0) "-" else "+"
  sprintf("%gx^2 %s %gx %s %g", coefficients[1],
          b_sign, abs(coefficients[2]), c_sign, abs(coefficients[3]))
}

report = function(coefficients) {
  result = solve(coefficients)
  root_text = if (length(result$roots) == 0) {
    "none (complex roots)"
  } else {
    paste(formatC(result$roots, digits = 6, format = "g"), collapse = ", ")
  }
  vertex_text = sprintf("(%g, %g)", result$vertex_x, result$vertex_y)

  cat(format_equation(coefficients), "\n")
  cat("  discriminant:", result$discriminant, "\n")
  cat("  real roots:", root_text, "\n")
  cat("  vertex:", vertex_text, "\n\n")
  invisible(result)
}

main = function() {
  examples = list(c(1, -3, 2), c(1, 2, 1), c(2, 1, 3), c(-1, 4, -1))
  for (coefficients in examples) {
    report(coefficients)
  }
}

main()

