simulate <- function(inflows) {
  capacity <- 1000
  daily_release <- 50
  volume <- 0
  spilled <- 0
  dry_days <- 0

  for (inflow in inflows) {
    volume <- volume + inflow
    if (volume > capacity) {
      excess <- volume - capacity
      spilled <- spilled + excess
      volume <- capacity
    }
    volume <- volume - daily_release
    if (volume < 0) {
      volume <- 0
    }
    if (volume == 0) {
      dry_days <- dry_days + 1
    }
  }

  list(final_volume = volume, spilled = spilled, dry_days = dry_days)
}

validate_inflows <- function(inflows) {
  if (!is.numeric(inflows)) {
    stop("inflows must be a numeric vector")
  }
  if (anyNA(inflows)) {
    stop("inflows must not contain missing values")
  }
  negatives <- which(inflows < 0)
  if (length(negatives) > 0) {
    first_bad <- negatives[1]
    stop(sprintf("inflow on day %d is negative (%g)", first_bad, inflows[first_bad]))
  }
  invisible(inflows)
}

format_report <- function(label, result, n_days) {
  header <- sprintf("=== %s (%d days) ===", label, n_days)
  lines <- c(
    header,
    sprintf("Final volume   : %8.1f units", result$final_volume),
    sprintf("Total spilled  : %8.1f units", result$spilled),
    sprintf("Dry days       : %8d", result$dry_days)
  )
  paste(lines, collapse = "\n")
}

run_scenario <- function(label, inflows) {
  validate_inflows(inflows)
  result <- simulate(inflows)
  cat(format_report(label, result, length(inflows)), "\n\n", sep = "")
  invisible(result)
}

main <- function() {
  steady <- rep(50, 30)
  run_scenario("Steady inflow matching release", steady)

  flood <- c(rep(20, 5), rep(600, 10), rep(0, 15))
  run_scenario("Flood pulse then drought", flood)

  set.seed(42)
  random_inflows <- round(runif(60, min = 0, max = 200), 1)
  random_result <- run_scenario("Random inflow year sample", random_inflows)

  spill_share <- random_result$spilled / sum(random_inflows)
  cat(sprintf("Fraction of random inflow spilled: %.3f\n", spill_share))
}

main()

