peaks <- function(series) {
  if (!is.numeric(series)) {
    stop("peaks() requires a numeric vector")
  }
  n <- length(series)
  indices <- numeric(0)
  if (n >= 3) {
    for (i in 2:(n - 1)) {
      current <- series[i]
      if (current > series[i - 1] && current > series[i + 1]) {
        indices <- c(indices, i)
      }
    }
  }
  count <- length(indices)
  average <- if (count > 0) mean(series[indices]) else NA_real_
  max_gap <- if (count > 1) max(diff(indices)) else NA_real_
  list(indices = indices, count = count, average = average, max_gap = max_gap)
}

format_peak_report <- function(series, result, label) {
  header <- paste0(label, " (n = ", length(series), ")")
  lines <- c(header, paste("  peaks found:", result$count))
  if (result$count > 0) {
    positions <- paste(result$indices, collapse = ", ")
    values <- paste(format(series[result$indices], trim = TRUE), collapse = ", ")
    lines <- c(lines, paste("  indices:", positions))
    lines <- c(lines, paste("  values:", values))
    lines <- c(lines, paste("  average peak value:", format(result$average, digits = 5)))
  }
  if (is.na(result$max_gap)) {
    lines <- c(lines, "  longest gap between peaks: undefined")
  } else {
    lines <- c(lines, paste("  longest gap between peaks:", result$max_gap))
  }
  paste(lines, collapse = "\n")
}

describe_series <- function(series, label) {
  result <- peaks(series)
  cat(format_peak_report(series, result, label), "\n\n", sep = "")
  result
}

main <- function() {
  wave <- c(1, 3, 2, 5, 4, 4, 6, 1, 7, 0)
  plateau <- c(2, 2, 2, 2, 2)
  spikes <- c(0, 9, 0, 0, 0, 0, 8, 0, 3, 0, 5, 0)

  wave_result <- describe_series(wave, "Wave sample")
  describe_series(plateau, "Flat plateau")
  spike_result <- describe_series(spikes, "Widely spaced spikes")

  busiest <- if (spike_result$count > wave_result$count) "spikes" else "wave"
  cat("Series with more peaks:", busiest, "\n")

  gaps <- c(wave_result$max_gap, spike_result$max_gap)
  widest <- max(gaps, na.rm = TRUE)
  cat("Widest peak separation across samples:", widest, "\n")
}

main()

