reading <- function(pages) {
  if (!is.numeric(pages)) {
    stop("pages must be a numeric vector")
  }
  if (any(is.na(pages)) || any(pages < 0)) {
    stop("pages must contain non-negative values only")
  }
  total_pages <- 0
  current_streak <- 0
  max_streak <- 0
  active_days <- 0
  big_days <- 0
  for (day_pages in pages) {
    total_pages <- total_pages + day_pages
    if (day_pages > 0) {
      current_streak <- current_streak + 1
      active_days <- active_days + 1
      if (current_streak > max_streak) {
        max_streak <- current_streak
      }
    }
    if (day_pages == 0) {
      current_streak <- 0
    }
    if (day_pages > 50) {
      big_days <- big_days + 1
    }
  }
  average_active <- if (active_days > 0) total_pages / active_days else 0
  list(total_pages = total_pages,
       max_streak = max_streak,
       average_active = average_active,
       fifty_page_days = big_days)
}

format_report <- function(label, stats) {
  header <- paste0("Reading log: ", label)
  report_rows <- c(header,
                   paste("  Total pages read      :", stats$total_pages),
                   paste("  Longest reading streak:", stats$max_streak, "days"),
                   paste("  Average per active day:", sprintf("%.2f", stats$average_active)),
                   paste("  Days above 50 pages   :", stats$fifty_page_days))
  paste(report_rows, collapse = "\n")
}

parse_log <- function(text) {
  fields <- strsplit(text, ",", fixed = TRUE)[[1]]
  trimmed <- trimws(fields)
  as.numeric(trimmed)
}

main <- function() {
  logs <- list(
    "first fortnight" = "12, 30, 0, 45, 60, 55, 0, 0, 20, 75, 80, 10, 0, 5",
    "holiday week" = "0, 0, 120, 100, 95, 0, 40",
    "rest week" = "0, 0, 0, 0"
  )
  best_label <- names(logs)[1]
  best_total <- -1
  for (label in names(logs)) {
    daily <- parse_log(logs[[label]])
    stats <- reading(daily)
    cat(format_report(label, stats), "\n\n", sep = "")
    if (stats$total_pages > best_total) {
      best_total <- stats$total_pages
      best_label <- label
    }
  }
  cat("Most productive period:", best_label, "with", best_total, "pages\n")
}

main()

