encrypt <- function(message) {
  alphabet <- letters
  vowels <- c("a", "e", "i", "o", "u")
  encrypted <- character(0)
  vowel_count <- 0
  target_count <- 0
  for (ch in message) {
    if (ch %in% vowels) {
      vowel_count <- vowel_count + 1
    }
    index <- match(ch, alphabet)
    new_index <- index + 3
    if (new_index > 26) {
      new_index <- new_index - 26
    }
    new_char <- alphabet[new_index]
    encrypted <- c(encrypted, new_char)
    if (new_char == "d") {
      target_count <- target_count + 1
    }
  }
  list(encrypted = encrypted, vowels = vowel_count, target = target_count)
}

decrypt <- function(encrypted) {
  alphabet <- letters
  plain <- character(0)
  for (ch in encrypted) {
    index <- match(ch, alphabet) - 3
    if (index < 1) {
      index <- index + 26
    }
    plain <- c(plain, alphabet[index])
  }
  plain
}

prepare <- function(text) {
  lowered <- tolower(text)
  chars <- strsplit(lowered, "")[[1]]
  keep <- chars %in% letters
  chars[keep]
}

report <- function(text) {
  message_chars <- prepare(text)
  result <- encrypt(message_chars)
  cipher_text <- paste(result$encrypted, collapse = "")
  restored <- paste(decrypt(result$encrypted), collapse = "")
  cat("plain    :", paste(message_chars, collapse = ""), "\n")
  cat("encrypted:", cipher_text, "\n")
  cat("vowels   :", result$vowels, "\n")
  cat("letter d :", result$target, "\n")
  cat("decrypted:", restored, "\n")
  if (restored != paste(message_chars, collapse = "")) {
    cat("warning: round trip mismatch\n")
  }
  cat("\n")
  invisible(result)
}

main <- function() {
  samples <- c("Attack at dawn", "the quick brown fox", "zebras and apples")
  for (sample in samples) {
    report(sample)
  }
  totals <- vapply(samples, function(s) encrypt(prepare(s))$target, numeric(1))
  grand_total <- sum(totals)
  cat("total occurrences of d across samples:", grand_total, "\n")
}

main()

