process <- function(steps) {
  if (!is.numeric(steps)) {
    stop("steps must be a numeric vector")
  }
  if (any(is.na(steps)) || any(steps < 0)) {
    stop("steps must contain non-negative values only")
  }
  active <- steps[steps > 0]
  active_count <- length(active)
  if (active_count == 0) {
    return(list(total = 0, active_count = 0, maximum = 0, minimum = 0,
                difference = 0, average = 0, goal_count = 0, goal_pct = 0))
  }
  total <- sum(active)
  maximum <- max(active)
  minimum <- min(active)
  difference <- maximum - minimum
  average <- total / active_count
  goal_count <- sum(active >= 10000)
  goal_pct <- 100 * goal_count / active_count
  list(total = total, active_count = active_count, maximum = maximum,
       minimum = minimum, difference = difference, average = average,
       goal_count = goal_count, goal_pct = goal_pct)
}

format_report <- function(label, summary) {
  header <- sprintf("=== %s ===", label)
  lines <- c(
    header,
    sprintf("Total steps on active days : %d", as.integer(summary$total)),
    sprintf("Active days                : %d", as.integer(summary$active_count)),
    sprintf("Best day                   : %d", as.integer(summary$maximum)),
    sprintf("Quietest active day        : %d", as.integer(summary$minimum)),
    sprintf("Spread (max - min)         : %d", as.integer(summary$difference)),
    sprintf("Average per active day     : %.1f", summary$average),
    sprintf("Days reaching 10,000       : %d", as.integer(summary$goal_count)),
    sprintf("Goal rate of active days   : %.1f%%", summary$goal_pct)
  )
  paste(lines, collapse = "\n")
}

parse_steps <- function(text) {
  pieces <- strsplit(text, "[,[:space:]]+")[[1]]
  pieces <- pieces[nzchar(pieces)]
  values <- suppressWarnings(as.numeric(pieces))
  if (any(is.na(values))) {
    bad <- pieces[is.na(values)]
    stop(sprintf("unparseable step values: %s", paste(bad, collapse = ", ")))
  }
  values
}

compare_weeks <- function(weeks) {
  summaries <- lapply(weeks, process)
  best_index <- which.max(vapply(summaries, function(s) s$total, numeric(1)))
  best_label <- names(weeks)[best_index]
  reports <- mapply(format_report, names(weeks), summaries, USE.NAMES = FALSE)
  verdict <- sprintf("Highest active-day total: %s", best_label)
  paste(c(reports, verdict), collapse = "\n\n")
}

main <- function() {
  week_one <- parse_steps("8213 0 10450 12007 0 9870 11342")
  week_two <- parse_steps("10001, 10500, 0, 7600, 15320, 0, 0")
  weeks <- list("Week 1" = week_one, "Week 2" = week_two)
  cat(compare_weeks(weeks), "\n")
}

main()

