book_fee <- function(d) {
  if (is.na(d) || d <= 0) {
    return(0)
  }
  first <- min(d, 5)
  extra <- max(d - 5, 0)
  fee <- 0.5 * first + 1 * extra
  min(fee, 10)
}

assess <- function(days) {
  if (!is.numeric(days)) {
    stop("days must be a numeric vector")
  }
  fees <- vapply(days, book_fee, numeric(1))
  owing <- fees[fees > 0]
  total <- sum(fees)
  highest <- if (length(fees) > 0) max(fees) else 0
  lowest <- if (length(owing) > 0) min(owing) else 0
  maxed <- sum(fees >= 10)
  average <- if (length(owing) > 0) mean(owing) else 0
  list(
    total_owed = total,
    highest_fee = highest,
    lowest_positive_fee = lowest,
    maxed_count = maxed,
    average_positive_fee = average,
    total_books = length(fees)
  )
}

money <- function(x) {
  sprintf("$%.2f", x)
}

format_report <- function(result) {
  lines <- c(
    paste("Books processed:", result$total_books),
    paste("Total owed:", money(result$total_owed)),
    paste("Highest fee:", money(result$highest_fee)),
    paste("Lowest fee owed:", money(result$lowest_positive_fee)),
    paste("Books at maximum:", result$maxed_count),
    paste("Average fee owed:", money(result$average_positive_fee))
  )
  paste(lines, collapse = "\n")
}

fee_table <- function(days) {
  fees <- vapply(days, book_fee, numeric(1))
  labels <- paste0("Book ", seq_along(days))
  rows <- paste0(labels, ": ", days, " day(s) -> ", vapply(fees, money, character(1)))
  paste(rows, collapse = "\n")
}

main <- function() {
  overdue <- c(0, 1, 3, 5, 6, 9, 12, 20, 40)
  summary_result <- assess(overdue)
  cat(fee_table(overdue), "\n", sep = "")
  cat("\n")
  cat(format_report(summary_result), "\n", sep = "")

  clean_shelf <- c(0, 0, 0)
  clean_result <- assess(clean_shelf)
  cat("\n")
  cat(format_report(clean_result), "\n", sep = "")
}

main()

