BASE_PAY <- 500
TIER_ONE_START <- 1000
TIER_TWO_START <- 5000

commission_for <- function(amount) {
  if (amount < TIER_ONE_START) {
    return(0)
  }
  lower_portion <- min(amount, TIER_TWO_START) - TIER_ONE_START
  upper_portion <- max(0, amount - TIER_TWO_START)
  0.05 * lower_portion + 0.10 * upper_portion
}

validate_sales <- function(sales) {
  if (!is.numeric(sales)) {
    stop("sales must be a numeric vector")
  }
  cleaned <- sales[!is.na(sales)]
  if (any(cleaned < 0)) {
    stop("sales amounts cannot be negative")
  }
  cleaned
}

calculate <- function(sales) {
  amounts <- validate_sales(sales)
  commissions <- vapply(amounts, commission_for, numeric(1))
  total_pay <- BASE_PAY + commissions
  earners <- commissions > 0
  earner_count <- sum(earners)
  average_commission <- if (earner_count > 0) mean(commissions[earners]) else 0
  highest <- if (length(commissions) > 0) max(commissions) else 0
  percentage <- if (length(commissions) > 0) 100 * earner_count / length(commissions) else 0
  list(
    total_payout = sum(total_pay),
    highest_commission = highest,
    earner_count = earner_count,
    average_commission = average_commission,
    percentage_with_commission = percentage,
    total_pay = as.list(total_pay)
  )
}

format_money <- function(value) {
  paste0("$", formatC(value, format = "f", digits = 2, big.mark = ","))
}

report <- function(result) {
  lines <- c(
    paste("Total payout:", format_money(result$total_payout)),
    paste("Highest commission:", format_money(result$highest_commission)),
    paste("Salespeople with a commission:", result$earner_count),
    paste("Average commission of earners:", format_money(result$average_commission)),
    paste0("Sales earning a commission: ",
           formatC(result$percentage_with_commission, format = "f", digits = 1), "%")
  )
  pay_lines <- vapply(seq_along(result$total_pay), function(i) {
    pay <- result$total_pay[[i]]
    paste0("  Sale ", i, ": total pay ", format_money(pay))
  }, character(1))
  c(lines, "Total pay per sale:", pay_lines)
}

main <- function() {
  sales <- c(450, 1000, 2500, 5000, 7200, 12000, 980)
  summary_result <- calculate(sales)
  cat(report(summary_result), sep = "\n")
  cat("\n")
}

main()

