weigh <- function(containers) {
  if (!is.numeric(containers) || length(containers) == 0L) {
    stop("containers must be a non-empty numeric vector")
  }
  if (any(is.na(containers))) {
    stop("containers must not contain missing values")
  }

  total <- sum(containers)
  light_mask <- containers < 50
  heavy_mask <- containers > 200
  light_count <- sum(light_mask)
  heavy_count <- sum(heavy_mask)
  average <- total / length(containers)
  heaviest <- max(containers)
  lightest <- min(containers)
  spread <- heaviest - lightest
  light_total <- sum(containers[light_mask])
  overweight <- if (total > 10000) 1L else 0L

  list(
    total = total,
    light_count = light_count,
    heavy_count = heavy_count,
    average = average,
    heaviest = heaviest,
    lightest = lightest,
    difference = spread,
    light_total = light_total,
    overweight = overweight
  )
}

format_pounds <- function(value) {
  formatted <- formatC(value, format = "f", digits = 2, big.mark = ",")
  paste0(formatted, " lb")
}

report_lines <- function(manifest_name, report) {
  header <- paste0("Manifest: ", manifest_name)
  body <- c(
    paste0("  total weight      : ", format_pounds(report$total)),
    paste0("  light (< 50 lb)   : ", report$light_count),
    paste0("  heavy (> 200 lb)  : ", report$heavy_count),
    paste0("  average weight    : ", format_pounds(report$average)),
    paste0("  heaviest          : ", format_pounds(report$heaviest)),
    paste0("  lightest          : ", format_pounds(report$lightest)),
    paste0("  heaviest-lightest : ", format_pounds(report$difference)),
    paste0("  light subtotal    : ", format_pounds(report$light_total)),
    paste0("  overweight flag   : ", report$overweight)
  )
  c(header, body)
}

weigh_manifests <- function(manifests) {
  reports <- lapply(manifests, weigh)
  names(reports) <- names(manifests)
  reports
}

main <- function() {
  manifests <- list(
    coastal = c(12.5, 48, 205, 310, 77, 49.9),
    freight = c(950, 1200, 3400, 2800, 2100, 45),
    single = c(180)
  )
  reports <- weigh_manifests(manifests)
  for (name in names(reports)) {
    lines <- report_lines(name, reports[[name]])
    cat(lines, sep = "\n")
    cat("\n")
  }
  flagged <- names(reports)[vapply(reports, function(r) r$overweight == 1L, logical(1))]
  summary_line <- if (length(flagged) == 0L) {
    "No manifest exceeds 10,000 lb."
  } else {
    paste("Over 10,000 lb:", paste(flagged, collapse = ", "))
  }
  cat(summary_line, "\n", sep = "")
}

main()

