ticket_price <- function(age) {
  if (age < 12) {
    price <- 8
  } else if (age >= 65) {
    price <- 10
  } else {
    price <- 15
  }
  price
}

clean_ages <- function(ages) {
  numeric_ages <- suppressWarnings(as.numeric(ages))
  valid <- !is.na(numeric_ages) & numeric_ages >= 0
  numeric_ages[valid]
}

boxoffice <- function(ages) {
  valid_ages <- clean_ages(ages)
  prices <- vapply(valid_ages, ticket_price, numeric(1))
  tickets <- length(prices)
  revenue <- sum(prices)
  children <- sum(valid_ages < 12)
  seniors <- sum(valid_ages >= 65)
  adults <- tickets - children - seniors
  adult_revenue <- adults * 15
  if (tickets > 0) {
    average <- revenue / tickets
    adult_share <- 100 * adult_revenue / revenue
  } else {
    average <- 0
    adult_share <- 0
  }
  list(
    total_revenue = revenue,
    ticket_count = tickets,
    average_price = average,
    child_count = children,
    senior_count = seniors,
    adult_count = adults,
    adult_percentage = adult_share
  )
}

format_report <- function(result) {
  money <- function(x) sprintf("%.2f", x)
  lines <- c(
    paste("Tickets sold:", result$ticket_count),
    paste("Child tickets:", result$child_count),
    paste("Senior tickets:", result$senior_count),
    paste("Adult tickets:", result$adult_count),
    paste("Total revenue:", money(result$total_revenue)),
    paste("Average ticket price:", money(result$average_price)),
    paste0("Adult share of revenue: ", money(result$adult_percentage), "%")
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  crowd <- c(5, 11, 12, 30, 44, 64, 65, 80, 9, 17)
  summary_today <- boxoffice(crowd)
  cat(format_report(summary_today), "\n\n")

  matinee <- c(7, 8, 70, 72, 68)
  summary_matinee <- boxoffice(matinee)
  cat(format_report(summary_matinee), "\n\n")

  combined <- boxoffice(c(crowd, matinee))
  busiest <- if (summary_today$ticket_count >= summary_matinee$ticket_count) "evening" else "matinee"
  cat("Combined day:\n")
  cat(format_report(combined), "\n")
  cat("Busiest show:", busiest, "\n")
}

main()

