validate_prices <- function(prices) {
  if (!is.numeric(prices)) {
    stop("prices must be a numeric vector")
  }
  cleaned <- prices[!is.na(prices)]
  if (any(cleaned < 0)) {
    stop("prices must not be negative")
  }
  cleaned
}

discount_for <- function(subtotal) {
  rate <- if (subtotal > 100) 0.10 else 0
  subtotal * rate
}

shipping_for <- function(discounted_subtotal) {
  if (discounted_subtotal < 50) 10 else 0
}

tax_for <- function(discounted_subtotal) {
  tax_rate <- 0.08
  discounted_subtotal * tax_rate
}

checkout <- function(prices) {
  items <- validate_prices(prices)
  subtotal <- sum(items)
  discount <- discount_for(subtotal)
  discounted_subtotal <- subtotal - discount
  shipping <- shipping_for(discounted_subtotal)
  tax <- tax_for(discounted_subtotal)
  grand_total <- discounted_subtotal + shipping + tax
  effective_tax_rate <- if (subtotal > 0) tax / subtotal else 0
  combined_fees <- discount + shipping
  list(
    subtotal = subtotal,
    discount = discount,
    shipping = shipping,
    tax = tax,
    grand_total = grand_total,
    effective_tax_rate = effective_tax_rate,
    combined_fees = combined_fees
  )
}

format_receipt <- function(receipt) {
  money <- function(x) formatC(x, format = "f", digits = 2, big.mark = ",")
  lines <- c(
    paste("Subtotal:          ", money(receipt$subtotal)),
    paste("Discount:          -", money(receipt$discount)),
    paste("Shipping:          ", money(receipt$shipping)),
    paste("Tax:               ", money(receipt$tax)),
    paste("Grand total:       ", money(receipt$grand_total)),
    paste("Effective tax rate:", formatC(100 * receipt$effective_tax_rate,
                                         format = "f", digits = 2), "%"),
    paste("Discount+shipping: ", money(receipt$combined_fees))
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  carts <- list(
    small = c(12.50, 9.99, 4.75),
    large = c(49.95, 39.99, 25.00, 18.60)
  )
  for (name in names(carts)) {
    receipt <- checkout(carts[[name]])
    cat("Cart:", name, "\n")
    cat(format_receipt(receipt), "\n\n")
  }
}

main()

