PALLET_CAPACITY <- 50

validate_boxes <- function(boxes) {
  if (!is.numeric(boxes)) {
    stop("boxes must be a numeric vector")
  }
  cleaned <- boxes[!is.na(boxes)]
  if (length(cleaned) == 0) {
    stop("boxes must contain at least one non-missing count")
  }
  if (any(cleaned < 0)) {
    stop("box counts cannot be negative")
  }
  floor(cleaned)
}

pack <- function(boxes) {
  counts <- validate_boxes(boxes)
  full_pallets <- counts %/% PALLET_CAPACITY
  loose_boxes <- counts %% PALLET_CAPACITY
  large_orders <- sum(full_pallets >= 1)
  total_boxes <- sum(counts)
  list(
    total_full_pallets = sum(full_pallets),
    total_loose_boxes = sum(loose_boxes),
    large_order_count = large_orders,
    largest_order = max(counts),
    smallest_order = min(counts),
    average_boxes = total_boxes / length(counts),
    total_boxes = total_boxes
  )
}

per_order_table <- function(boxes) {
  counts <- validate_boxes(boxes)
  data.frame(
    order = seq_along(counts),
    boxes = counts,
    full_pallets = counts %/% PALLET_CAPACITY,
    loose_boxes = counts %% PALLET_CAPACITY
  )
}

format_summary <- function(totals) {
  captions <- c(
    "Total full pallets", "Total loose boxes", "Orders with a full pallet",
    "Largest order", "Smallest order", "Average boxes per order", "Total boxes"
  )
  values <- c(
    totals$total_full_pallets, totals$total_loose_boxes,
    totals$large_order_count, totals$largest_order,
    totals$smallest_order, round(totals$average_boxes, 2),
    totals$total_boxes
  )
  paste0(format(captions, width = 26), ": ", values)
}

