ANNUAL_RATE <- 0.05
TERM_MONTHS <- 60

validate_principals <- function(principals) {
  if (!is.numeric(principals)) {
    stop("principals must be a numeric vector")
  }
  cleaned <- principals[!is.na(principals)]
  if (length(cleaned) == 0) {
    stop("principals must contain at least one non-missing amount")
  }
  negatives <- cleaned[cleaned < 0]
  if (length(negatives) > 0) {
    stop("principal amounts must not be negative")
  }
  cleaned
}

loan <- function(principals) {
  amounts <- validate_principals(principals)
  years <- TERM_MONTHS / 12
  interest <- amounts * ANNUAL_RATE * years
  total_repay <- amounts + interest
  monthly_payments <- total_repay / TERM_MONTHS
  total_cash_flow <- sum(monthly_payments)
  total_profit <- sum(interest)
  highest_payment <- max(monthly_payments)
  lowest_payment <- min(monthly_payments)
  average_interest <- total_profit / length(amounts)
  list(
    total_cash_flow = total_cash_flow,
    total_profit = total_profit,
    highest_payment = highest_payment,
    lowest_payment = lowest_payment,
    average_interest = average_interest,
    monthly_payments = monthly_payments
  )
}

money <- function(x) {
  formatted <- formatC(x, format = "f", digits = 2, big.mark = ",")
  paste0("$", formatted)
}

report_loans <- function(result) {
  headline <- c(
    paste("Loans analysed:", length(result$monthly_payments)),
    paste("Total monthly cash flow:", money(result$total_cash_flow)),
    paste("Total profit (interest):", money(result$total_profit)),
    paste("Highest monthly payment:", money(result$highest_payment)),
    paste("Lowest monthly payment:", money(result$lowest_payment)),
    paste("Average interest per loan:", money(result$average_interest))
  )
  detail <- paste0(
    "  loan ", seq_along(result$monthly_payments),
    ": ", money(result$monthly_payments), " / month"
  )
  c(headline, "Monthly payment schedule:", detail)
}

main <- function() {
  portfolio <- c(10000, 25000, 7500, 120000, 4300)
  summary_data <- loan(portfolio)
  output <- report_loans(summary_data)
  cat(output, sep = "\n")
  cat("\n")
}

main()

