prey_growth_rate <- 0.05
prey_loss_per_predator <- 0.01
predator_gain_per_prey <- 0.005
predator_death_rate <- 0.03

clamp_zero <- function(value) {
  if (value < 0) {
    return(0)
  }
  value
}

next_state <- function(prey, predators) {
  prey_change <- prey * prey_growth_rate - prey * prey_loss_per_predator * predators
  predator_change <- predators * predator_gain_per_prey * prey - predators * predator_death_rate
  new_prey <- clamp_zero(prey + prey_change)
  new_predators <- clamp_zero(predators + predator_change)
  list(prey = new_prey, predators = new_predators)
}

simulate <- function(steps) {
  if (!is.numeric(steps) || length(steps) != 1 || is.na(steps) || steps < 0) {
    stop("steps must be a single non-negative number")
  }
  steps <- as.integer(steps)
  prey <- 100
  predators <- 20
  prey_history <- list(prey)
  predator_history <- list(predators)
  for (i in seq_len(steps)) {
    state <- next_state(prey, predators)
    prey <- state$prey
    predators <- state$predators
    prey_history[[length(prey_history) + 1]] <- prey
    predator_history[[length(predator_history) + 1]] <- predators
  }
  list(prey = prey_history, predators = predator_history)
}

format_report <- function(result) {
  prey_values <- unlist(result$prey)
  predator_values <- unlist(result$predators)
  header <- sprintf("%5s %12s %12s", "step", "prey", "predators")
  rows <- sprintf("%5d %12.3f %12.3f", seq_along(prey_values) - 1L,
                  prey_values, predator_values)
  paste(c(header, rows), collapse = "\n")
}

summarise_extremes <- function(result) {
  prey_values <- unlist(result$prey)
  predator_values <- unlist(result$predators)
  peak_prey_step <- which.max(prey_values) - 1L
  peak_predator_step <- which.max(predator_values) - 1L
  sprintf("peak prey %.3f at step %d; peak predators %.3f at step %d",
          max(prey_values), peak_prey_step,
          max(predator_values), peak_predator_step)
}

main <- function() {
  history <- simulate(30)
  cat(format_report(history), "\n", sep = "")
  cat(summarise_extremes(history), "\n", sep = "")
}

main()

