ascii_codes <- function(message) {
  if (!is.character(message) || length(message) != 1L) {
    stop("message must be a single character string")
  }
  if (is.na(message)) {
    stop("message must not be NA")
  }
  utf8ToInt(message)
}

hash <- function(message) {
  codes <- ascii_codes(message)
  if (any(codes > 255L)) {
    stop("message contains non-ascii characters")
  }
  additive <- 7L
  multiplicative <- 11L
  xored <- 13L
  for (code in codes) {
    additive <- (additive + code) %% 256L
    multiplicative <- (multiplicative * code) %% 256L
    xored <- bitwXor(code, xored)
  }
  total <- additive + multiplicative + xored
  total %% 65536L
}

hash_hex <- function(message) {
  digest <- hash(message)
  sprintf("0x%04X", digest)
}

hash_table <- function(messages) {
  digests <- vapply(messages, hash, integer(1), USE.NAMES = FALSE)
  hexes <- vapply(messages, hash_hex, character(1), USE.NAMES = FALSE)
  data.frame(
    message = messages,
    digest = digests,
    hex = hexes,
    stringsAsFactors = FALSE
  )
}

collisions <- function(messages) {
  tbl <- hash_table(messages)
  repeated <- tbl$digest[duplicated(tbl$digest)]
  unique_repeats <- unique(repeated)
  grouped <- lapply(unique_repeats, function(d) tbl$message[tbl$digest == d])
  names(grouped) <- as.character(unique_repeats)
  grouped
}

report <- function(messages) {
  tbl <- hash_table(messages)
  width <- max(nchar(tbl$message))
  lines <- sprintf("%-*s  %5d  %s", width, tbl$message, tbl$digest, tbl$hex)
  clashes <- collisions(messages)
  if (length(clashes) > 0L) {
    detail <- vapply(names(clashes), function(key) {
      paste0("collision at ", key, ": ", paste(clashes[[key]], collapse = ", "))
    }, character(1), USE.NAMES = FALSE)
    lines <- c(lines, "", detail)
  }
  paste(lines, collapse = "\n")
}

samples <- c("Hello, World!", "hash", "ROSETTA", "rosetta", "a", "R")
cat(report(samples), "\n", sep = "")
cat("empty string hashes to ", hash(""), "\n", sep = "")

