simulate <- function(accesses) {
  capacity <- 4L
  memory <- integer(0)
  last_used <- integer(0)
  faults <- 0L

  for (i in seq_along(accesses)) {
    page <- as.integer(accesses[[i]])
    pos <- match(page, memory)
    if (is.na(pos)) {
      faults <- faults + 1L
      if (length(memory) >= capacity) {
        victim <- which.min(last_used)
        memory[victim] <- page
        last_used[victim] <- i
      } else {
        memory <- c(memory, page)
        last_used <- c(last_used, i)
      }
    } else {
      last_used[pos] <- i
    }
  }
  faults
}

trace_states <- function(accesses) {
  capacity <- 4L
  memory <- integer(0)
  last_used <- integer(0)
  states <- vector("list", length(accesses))

  for (i in seq_along(accesses)) {
    page <- as.integer(accesses[[i]])
    pos <- match(page, memory)
    hit <- !is.na(pos)
