shot_points <- function(distance) {
  if (distance < 5) {
    award <- 10
  } else if (distance < 10) {
    award <- 8
  } else if (distance < 20) {
    award <- 5
  } else {
    award <- 0
  }
  award
}

validate_shots <- function(shots) {
  values <- unlist(shots, use.names = FALSE)
  if (length(values) == 0) {
    return(numeric(0))
  }
  if (!is.numeric(values)) {
    stop("shots must contain numeric distances only")
  }
  if (anyNA(values)) {
    stop("shots must not contain missing distances")
  }
  if (any(values < 0)) {
    stop("distances from the center cannot be negative")
  }
  values
}

score <- function(shots) {
  distances <- validate_shots(shots)
  total <- 0
  bullseyes <- 0
  streak <- 0
  max_streak <- 0
  for (distance in distances) {
    total <- total + shot_points(distance)
    if (distance < 5) {
      bullseyes <- bullseyes + 1
      streak <- streak + 1
      if (streak > max_streak) {
        max_streak <- streak
      }
    } else {
      streak <- 0
    }
  }
  list(total = total, bullseyes = bullseyes, max_streak = max_streak)
}

format_score <- function(result, label) {
  sprintf(
    "%s: total = %d, bullseyes = %d, longest bullseye streak = %d",
    label, result$total, result$bullseyes, result$max_streak
  )
}

