MAX_CAPACITY_START <- 500
LOW_THRESHOLD_FRACTION <- 0.2

validate_usage <- function(usage) {
  values <- unlist(usage, use.names = FALSE)
  if (length(values) == 0) {
    return(numeric(0))
  }
  if (!is.numeric(values)) {
    stop("usage must contain numeric hourly draws in watts")
  }
  if (any(is.na(values))) {
    stop("usage must not contain missing values")
  }
  if (any(values < 0)) {
    stop("usage must not contain negative draws")
  }
  values
}

step_hour <- function(capacity, max_capacity, draw) {
  blackout <- 0
  remaining <- capacity - draw
  if (remaining < 0) {
    blackout <- 1
    remaining <- 0
  }
  if (remaining < LOW_THRESHOLD_FRACTION * max_capacity) {
    max_capacity <- max_capacity - 1
    if (remaining > max_capacity) {
      remaining <- max_capacity
    }
  }
  list(capacity = remaining, max_capacity = max_capacity, blackout = blackout)
}

simulate <- function(usage) {
  draws <- validate_usage(usage)
  max_capacity <- MAX_CAPACITY_START
  capacity <- MAX_CAPACITY_START
  blackout_hours <- 0
  for (draw in draws) {
    state <- step_hour(capacity, max_capacity, draw)
    capacity <- state$capacity
    max_capacity <- state$max_capacity
    blackout_hours <- blackout_hours + state$blackout
  }
  list(blackout_hours = blackout_hours, final_max_capacity = max_capacity)
}

format_report <- function(result) {
  lines <- c(
    paste("Blackout hours:", result$blackout_hours),
    paste("Final maximum capacity:", result$final_max_capacity, "Wh")
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  light_day <- rep(30, 24)
  heavy_day <- c(rep(120, 6), rep(40, 12), rep(150, 6))
  outage_run <- c(rep(200, 4), rep(90, 20))
  scenarios <- list(light = light_day, heavy = heavy_day, outage = outage_run)
  for (name in names(scenarios)) {
    outcome <- simulate(scenarios[[name]])
    cat(name, "scenario\n")
    cat(format_report(outcome), "\n\n")
  }
}

main()

