tier_thresholds <- function() {
  list(
    silver = list(miles = 25000, flights = 30),
    gold   = list(miles = 50000, flights = 60)
  )
}

validate_flights <- function(flights) {
  values <- unlist(flights, use.names = FALSE)
  if (is.null(values)) {
    return(numeric(0))
  }
  if (!is.numeric(values)) {
    stop("flight distances must be numeric")
  }
  if (any(is.na(values))) {
    stop("flight distances must not be missing")
  }
  if (any(values < 0)) {
    stop("flight distances must not be negative")
  }
  values
}

evaluate <- function(flights) {
  distances <- validate_flights(flights)
  total_miles <- sum(distances)
  flight_count <- length(distances)
  limits <- tier_thresholds()
  tier <- "standard"
  if (total_miles > limits$silver$miles || flight_count > limits$silver$flights) {
    tier <- "silver"
  }
  if (total_miles > limits$gold$miles || flight_count > limits$gold$flights) {
    tier <- "gold"
  }
  next_target <- switch(tier,
    standard = limits$silver$miles,
    silver = limits$gold$miles,
    gold = NA_real_
  )
  miles_to_next <- if (is.na(next_target)) 0 else max(0, next_target - total_miles)
  list(tier = tier, miles_to_next_tier = miles_to_next)
}

format_report <- function(flights) {
  status <- evaluate(flights)
  headline <- paste0("Tier achieved: ", toupper(status$tier))
  detail <- if (status$tier == "gold") {
    "Top tier reached; no further miles required."
  } else {
    paste0(format(status$miles_to_next_tier, big.mark = ","), " miles to the next tier.")
  }
  paste(headline, detail, sep = " - ")
}

main <- function() {
  occasional_traveller <- list(820, 1450, 310)
  frequent_traveller <- as.list(rep(950, 32))
  road_warrior <- as.list(c(rep(4200, 12), rep(1100, 5)))
  profiles <- list(
    occasional = occasional_traveller,
    frequent = frequent_traveller,
    warrior = road_warrior
  )
  for (name in names(profiles)) {
    line <- paste0(name, ": ", format_report(profiles[[name]]))
    cat(line, "\n")
  }
  empty_log <- evaluate(list())
  cat("no flights yet:", empty_log$tier, "needs", empty_log$miles_to_next_tier, "miles\n")
}

main()

