model <- function(days) {
  if (!is.numeric(days) || length(days) != 1 || is.na(days) || days < 0) {
    stop("days must be a single non-negative number")
  }
  total_days <- as.integer(days)
  height <- 2
  leaves <- 0
  heights <- numeric(0)
  for (day in seq_len(total_days)) {
    growth <- 0.1 * height + 1
    if (leaves > 5) {
      growth <- growth * 0.8
    }
    height <- height + growth
    milestones <- floor(height / 10)
    if (milestones > leaves) {
      leaves <- milestones
    }
    heights <- c(heights, height)
  }
  list(leaves = leaves, heights = heights)
}

daily_growth <- function(heights, start_height = 2) {
  previous <- c(start_height, heights[-length(heights)])
  heights - previous
}

leaf_days <- function(heights, start_height = 2) {
  previous <- c(start_height, heights[-length(heights)])
  which(floor(heights / 10) > floor(previous / 10))
}

format_report <- function(simulation, start_height = 2) {
  heights <- simulation$heights
  if (length(heights) == 0) {
    return(sprintf("No growth simulated; plant stays at %.2f cm.", start_height))
  }
  growth <- daily_growth(heights, start_height)
  lines <- sprintf("Day %2d: height %6.2f cm (+%.2f cm)",
                   seq_along(heights), heights, growth)
  sprout <- leaf_days(heights, start_height)
  if (length(sprout) > 0) {
    sprout_note <- paste0("Leaves sprouted on days: ",
                          paste(sprout, collapse = ", "))
    lines <- c(lines, sprout_note)
  }
  summary_line <- sprintf("Final height %.2f cm with %d leaves after %d days.",
                          heights[length(heights)], simulation$leaves,
                          length(heights))
  paste(c(lines, summary_line), collapse = "\n")
}

main <- function() {
  horizons <- c(5, 15, 30)
  for (h in horizons) {
    run <- model(h)
    cat(format_report(run), "\n\n", sep = "")
  }
  long_run <- model(60)
  slowed <- daily_growth(long_run$heights)
  peak_day <- which.max(slowed)
  cat(sprintf("Over 60 days the fastest growth was %.2f cm on day %d.\n",
              slowed[peak_day], peak_day))
}

main()

