validate_sizes = function(asteroids) {
  sizes = unlist(asteroids, use.names = FALSE)
  if (length(sizes) == 0) {
    return(integer(0))
  }
  if (!is.numeric(sizes)) {
    stop("asteroid sizes must be numeric")
  }
  rounded = as.integer(round(sizes))
  if (any(rounded != sizes)) {
    stop("asteroid sizes must be whole numbers")
  }
  if (any(rounded == 0)) {
    stop("an asteroid cannot have size zero")
  }
  rounded
}

detect = function(asteroids) {
  sizes = validate_sizes(asteroids)
  stack = integer(0)
  for (incoming in sizes) {
    current = incoming
    while (current < 0 && length(stack) > 0 && stack[length(stack)] > 0) {
      top = stack[length(stack)]
      if (top < -current) {
        stack = stack[-length(stack)]
      } else if (top == -current) {
        stack = stack[-length(stack)]
        current = 0L
      } else {
        current = 0L
      }
    }
    if (current != 0) {
      stack = c(stack, current)
    }
  }
  as.list(stack)
}

describe_field = function(asteroids) {
  sizes = validate_sizes(asteroids)
  if (length(sizes) == 0) {
    return("empty field")
  }
  arrows = ifelse(sizes > 0, "->", "<-")
  labels = paste0(abs(sizes), arrows)
  paste(labels, collapse = " ")
}

report = function(asteroids) {
  survivors = detect(asteroids)
  before = describe_field(asteroids)
  after = describe_field(survivors)
  destroyed = length(asteroids) - length(survivors)
  cat(before, "=>", after, "\n")
  cat("  destroyed:", destroyed, "of", length(asteroids), "\n")
  invisible(survivors)
}

main = function() {
  fields = list(
    list(5L, 10L, -5L),
    list(8L, -8L),
    list(10L, 2L, -5L),
    list(-2L, -1L, 1L, 2L),
    list(1L, -1L, 3L, -2L, -4L, 5L)
  )
  for (field in fields) {
    report(field)
  }
  totals = vapply(fields, function(f) length(detect(f)), integer(1))
  cat("survivor counts:", paste(totals, collapse = ", "), "\n")
}

main()

