oxygen_rate_per_crew <- function(filter_health) {
  base_rate <- 10
  if (filter_health < 20) {
    base_rate <- base_rate * 2
  }
  base_rate
}

co2_generated <- function(crew) {
  per_crew <- 12
  crew * per_crew
}

filter_wear <- function(co2_units) {
  units_per_percent <- 50
  co2_units / units_per_percent
}

validate_crew <- function(crew) {
  if (!is.numeric(crew) || length(crew) != 1 || is.na(crew)) {
    stop("crew must be a single numeric value")
  }
  if (crew < 0 || crew != round(crew)) {
    stop("crew must be a non-negative whole number")
  }
  as.integer(crew)
}

simulate <- function(crew) {
  members <- validate_crew(crew)
  oxygen <- 10000
  filter_health <- 100
  days <- 30
  for (day in seq_len(days)) {
    rate <- oxygen_rate_per_crew(filter_health)
    oxygen <- oxygen - members * rate
    co2 <- co2_generated(members)
    filter_health <- filter_health - filter_wear(co2)
    if (filter_health < 0) {
      filter_health <- 0
    }
    if (oxygen < 0) {
      oxygen <- 0
    }
  }
  list(oxygen = oxygen, filter_health = filter_health)
}

format_report <- function(crew, result) {
  header <- sprintf("Crew of %d after 30 days:", crew)
  oxygen_line <- sprintf("  oxygen reserves: %.1f units", result$oxygen)
  filter_line <- sprintf("  filter health:   %.1f %%", result$filter_health)
  status <- if (result$oxygen == 0 || result$filter_health == 0) {
    "  status: life support failure"
  } else {
    "  status: nominal"
  }
  paste(header, oxygen_line, filter_line, status, sep = "\n")
}

main <- function() {
  crew_sizes <- c(1, 5, 12, 30)
  for (crew in crew_sizes) {
    outcome <- simulate(crew)
    cat(format_report(crew, outcome), "\n\n", sep = "")
  }
}

main()

