rainfall_multiplier <- function(rainfall) {
  multiplier <- 1
  if (rainfall >= 20 && rainfall <= 40) {
    multiplier <- 1.2
  } else if (rainfall < 10) {
    multiplier <- 0.5
  }
  multiplier
}

fertilizer_bonus <- function(fertilizer) {
  excess <- fertilizer - 10
  if (excess <= 0) {
    return(0)
  }
  2 * excess
}

validate_triplet <- function(triplet, index) {
  if (length(triplet) != 3) {
    stop(sprintf("plot %d must contain exactly three values", index))
  }
  values <- as.numeric(triplet)
  if (any(is.na(values))) {
    stop(sprintf("plot %d contains non-numeric values", index))
  }
  if (any(values < 0)) {
    stop(sprintf("plot %d contains negative values", index))
  }
  values
}

single_yield <- function(triplet, index) {
  values <- validate_triplet(triplet, index)
  acres <- values[1]
  rainfall <- values[2]
  fertilizer <- values[3]
  base <- 50 * acres
  adjusted <- base * rainfall_multiplier(rainfall)
  adjusted + fertilizer_bonus(fertilizer)
}

harvest <- function(plots) {
  total <- 0
  productive <- 0
  for (i in seq_along(plots)) {
    yield <- single_yield(plots[[i]], i)
    total <- total + yield
    if (yield > 1000) {
      productive <- productive + 1
    }
  }
  c(total, productive)
}

harvest_report <- function(plots) {
  result <- harvest(plots)
  text <- character(0)
  for (i in seq_along(plots)) {
    yield <- single_yield(plots[[i]], i)
    text <- c(text, sprintf("Plot %d: %.1f bushels", i, yield))
  }
  summary_line <- sprintf("Total: %.1f bushels, high-yield plots: %d",
                          result[1], as.integer(result[2]))
  paste(c(text, summary_line), collapse = "\n")
}

main <- function() {
  sample_plots <- list(c(10, 25, 15), c(5, 5, 5))
  cat(harvest_report(sample_plots), "\n", sep = "")
  big_farm <- list(c(30, 35, 40), c(12, 15, 8), c(20, 5, 100))
  cat(harvest_report(big_farm), "\n", sep = "")
  totals <- harvest(big_farm)
  cat(sprintf("Average per plot: %.1f bushels\n", totals[1] / length(big_farm)))
}

main()

