deg_to_rad <- function(degrees) {
  degrees * pi / 180
}

validate_initial <- function(initial) {
  values <- as.numeric(initial)
  if (length(values) != 3L || any(is.na(values))) {
    stop("initial must hold speed, angle in degrees and time step")
  }
  if (values[1] < 0) {
    stop("initial speed must not be negative")
  }
  if (values[3] <= 0) {
    stop("time step must be positive")
  }
  values
}

velocity_components <- function(speed, angle) {
  theta <- deg_to_rad(angle)
  c(speed * cos(theta), speed * sin(theta))
}

trajectory <- function(initial) {
  params <- validate_initial(initial)
  components <- velocity_components(params[1], params[2])
  step <- params[3]
  gravity <- 9.8
  vx <- components[1]
  vy <- components[2]
  elapsed <- 0
  horizontal <- 0
  height <- 0
  max_height <- 0
  repeat {
    previous_horizontal <- horizontal
    previous_height <- height
    elapsed <- elapsed + step
    horizontal <- vx * elapsed
    height <- vy * elapsed - 0.5 * gravity * elapsed^2
    if (height > max_height) {
      max_height <- height
    }
    if (height < 0) {
      fraction <- previous_height / (previous_height - height)
      horizontal <- previous_horizontal + fraction * (horizontal - previous_horizontal)
      break
    }
  }
  c(horizontal, max_height)
}

format_flight <- function(initial, result) {
  launch <- sprintf("%g m/s at %g deg (dt = %g s)", initial[1], initial[2], initial[3])
  outcome <- sprintf("range %.1f m, peak %.1f m", result[1], result[2])
  paste(launch, "->", outcome)
}

main <- function() {
  cases <- list(c(20, 45, 0.1), c(30, 30, 0.05), c(15, 60, 0.02))
  best_case <- cases[[1]]
  best <- trajectory(best_case)
  for (case in cases) {
    result <- trajectory(case)
    cat(format_flight(case, result), "\n")
    if (result[1] > best[1]) {
      best <- result
      best_case <- case
    }
  }
  cat(sprintf("Longest range from %g m/s at %g deg: %.1f m\n",
              best_case[1], best_case[2], best[1]))
}

main()

