trip_subtotal <- function(trip) {
  base_charge <- 3
  miles <- trip[[1]]
  minutes <- trip[[2]]
  base_charge + 2 * miles + 0.5 * minutes
}

apply_rush_multiplier <- function(subtotal, rush_flag) {
  if (rush_flag == 1) {
    return(subtotal * 1.5)
  }
  subtotal
}

apply_large_fare_discount <- function(amount) {
  threshold <- 50
  if (amount > threshold) {
    excess <- amount - threshold
    discounted <- threshold + excess * 0.9
    return(list(fare = discounted, discounted = TRUE))
  }
  list(fare = amount, discounted = FALSE)
}

validate_trip <- function(trip, index) {
  if (length(trip) != 3) {
    stop(paste0("Trip ", index, " must have exactly three values"))
  }
  values <- as.numeric(unlist(trip))
  if (any(is.na(values))) {
    stop(paste0("Trip ", index, " contains non-numeric values"))
  }
  if (values[1] < 0 || values[2] < 0) {
    stop(paste0("Trip ", index, " has negative distance or duration"))
  }
  if (!(values[3] %in% c(0, 1))) {
    stop(paste0("Trip ", index, " rush-hour indicator must be 0 or 1"))
  }
  values
}

fare <- function(trips) {
  total_revenue <- 0
  discount_count <- 0
  for (i in seq_along(trips)) {
    trip <- validate_trip(trips[[i]], i)
    subtotal <- trip_subtotal(trip)
    adjusted <- apply_rush_multiplier(subtotal, trip[3])
    result <- apply_large_fare_discount(adjusted)
    total_revenue <- total_revenue + result$fare
    if (result$discounted) {
      discount_count <- discount_count + 1
    }
  }
  c(round(total_revenue, 2), discount_count)
}

format_report <- function(totals) {
  revenue <- sprintf("$%.2f", totals[1])
  paste0("Total revenue: ", revenue, " | Discounted trips: ", totals[2])
}

main <- function() {
  sample_trips <- list(c(15, 20, 1), c(2, 5, 0))
  cat(format_report(fare(sample_trips)), "\n")
  busy_night <- list(c(30, 45, 1), c(8, 12, 1), c(1, 3, 0))
  cat(format_report(fare(busy_night)), "\n")
}

main()

