level <- function(events) {
  current_level <- 1
  health <- 100
  attack <- 10
  experience <- 0
  monsters <- 0
  quests <- 0
  for (event in events) {
    kind <- event[[1]]
    gained <- event[[2]]
    if (kind == 0) {
      monsters <- monsters + 1
    } else {
      quests <- quests + 1
    }
    experience <- experience + gained
    while (experience >= 1000 * current_level) {
      experience <- experience - 1000 * current_level
      current_level <- current_level + 1
      health <- health + 20
      attack <- attack + 5
    }
  }
  list(current_level, health, attack, experience, monsters, quests)
}

validate_events <- function(events) {
  if (!is.list(events)) {
    stop("events must be a list of pairs")
  }
  for (event in events) {
    if (length(event) != 2) {
      stop("each event must have exactly two elements")
    }
    kind <- event[[1]]
    gained <- event[[2]]
    if (!(kind %in% c(0, 1))) {
      stop("event type must be 0 (monster) or 1 (quest)")
    }
    if (!is.numeric(gained) || gained < 0) {
      stop("experience gained must be a non-negative number")
    }
  }
  invisible(TRUE)
}

format_stats <- function(stats) {
  labels <- c("level", "health", "attack", "experience", "monsters", "quests")
  values <- unlist(stats)
  paste(paste0(labels, "=", values), collapse = ", ")
}

report <- function(events) {
  validate_events(events)
  stats <- level(events)
  cat(format_stats(stats), "\n")
  invisible(stats)
}

main <- function() {
  simple_run <- list(c(0, 800), c(1, 400))
  report(simple_run)
  grind <- list(c(0, 500), c(0, 500), c(0, 900), c(1, 1200), c(1, 300))
  report(grind)
  quiet_day <- list()
  report(quiet_day)
  failure <- try(report(list(c(2, 100))), silent = TRUE)
  cat(conditionMessage(attr(failure, "condition")), "\n")
}

main()

