splits <- function(miles) {
  if (length(miles) == 0) {
    stop("splits() requires at least one mile time")
  }
  if (any(!is.finite(miles)) || any(miles <= 0)) {
    stop("mile times must be positive finite numbers")
  }
  total <- 0
