billing <- function(accounts) {
  base_cost <- 40
  overage_rate <- 15
  loyalty_credit <- 5
  revenue <- 0
  excess_data <- 0

  for (account in accounts) {
    allowance <- account[[1]]
    used <- account[[2]]
    bill <- base_cost

    if (used > allowance) {
      over <- ceiling(used - allowance)
      excess_data <- excess_data + over
      bill <- bill + over * overage_rate
    } else if (used < allowance / 2) {
      bill <- bill - loyalty_credit
    }

    revenue <- revenue + bill
  }

  c(revenue, excess_data)
}

validate_accounts <- function(accounts) {
  for (i in seq_along(accounts)) {
    account <- accounts[[i]]
    if (length(account) != 2) {
      stop(paste("Account", i, "must contain an allowance and a usage value"))
    }
    numbers <- as.numeric(account)
    if (anyNA(numbers) || any(numbers < 0)) {
      stop(paste("Account", i, "must hold non-negative numeric values"))
    }
  }
  invisible(TRUE)
}

account_report <- function(accounts) {
  rows <- character(length(accounts))

  for (i in seq_along(accounts)) {
    allowance <- accounts[[i]][[1]]
    used <- accounts[[i]][[2]]
    single <- billing(list(c(allowance, used)))
    note <- if (single[2] > 0) {
      paste0(single[2], " GB over")
    } else if (used < allowance / 2) {
      "credit applied"
    } else {
      "within plan"
    }
    rows[i] <- sprintf("Account %d: %.1f/%.1f GB -> $%.2f (%s)",
                       i, used, allowance, single[1], note)
  }

  rows
}

main <- function() {
  accounts <- list(c(10, 12.3), c(5, 2), c(20, 20), c(8, 3.5), c(15, 17.1))
  validate_accounts(accounts)

  report <- account_report(accounts)
  cat(report, sep = "\n")

  totals <- billing(accounts)
  revenue <- totals[1]
  excess <- totals[2]
  cat("\n")
  cat(sprintf("Total revenue: $%.2f\n", revenue))
  cat(sprintf("Total excess gigabytes: %d\n", as.integer(excess)))
}

main()

