validate_orders <- function(orders) {
  if (!is.numeric(orders) || length(orders) < 1) {
    stop("orders must be a numeric vector holding the roll size and the cuts")
  }
  roll_size <- orders[1]
  if (is.na(roll_size) || roll_size <= 0) {
    stop("the standard roll size must be a positive number of yards")
  }
  requests <- orders[-1]
  if (any(is.na(requests)) || any(requests <= 0)) {
    stop("every requested cut must be a positive number of yards")
  }
  too_long <- requests[requests > roll_size]
  if (length(too_long) > 0) {
    stop(paste("cut of", too_long[1], "yards does not fit on a", roll_size, "yard roll"))
  }
  list(roll_size = roll_size, requests = requests)
}

cut <- function(orders) {
  parsed <- validate_orders(orders)
  roll_size <- parsed$roll_size
  requests <- parsed$requests
  if (length(requests) == 0) {
    return(c(0, 0))
  }
  rolls <- 1
  remaining <- roll_size
  waste <- 0
  for (piece in requests) {
    if (piece > remaining) {
      waste <- waste + remaining
      rolls <- rolls + 1
      remaining <- roll_size
    }
    remaining <- remaining - piece
  }
  c(rolls, waste + remaining)
}

efficiency <- function(orders) {
  result <- cut(orders)
  used <- result[1] * orders[1]
  if (used == 0) {
    return(0)
  }
  100 * (used - result[2]) / used
}

report <- function(orders) {
  result <- cut(orders)
  cuts_text <- paste(orders[-1], collapse = ", ")
  header <- paste0("Roll size ", orders[1], " yd; cuts: ", cuts_text)
  body <- paste0("  rolls used: ", result[1], ", waste: ", result[2], " yd")
  rate <- paste0("  utilisation: ", format(round(efficiency(orders), 1), nsmall = 1), "%")
  paste(header, body, rate, sep = "\n")
}

main <- function() {
  jobs <- list(
    c(10, 4, 5, 3, 6, 2),
    c(12, 3, 3, 3, 3),
    c(7, 2, 2, 4, 1, 5, 3)
  )
  for (job in jobs) {
    cat(report(job), "\n\n", sep = "")
  }
  answer <- cut(c(10, 4, 5, 3, 6, 2))
  cat("Example result: [", answer[1], ", ", answer[2], "]\n", sep = "")
}

main()

