baseline_distance <- function(days, daily_km) {
  days * daily_km
}

wind_adjustment <- function(distance, altitude) {
  if (altitude > 2000) {
    distance <- distance * 0.9
  }
  distance
}

fatigue_adjustment <- function(distance, days) {
  if (days > 10) {
    distance <- distance - 50
  }
  distance
}

flock_distance <- function(record) {
  days <- record[[1]]
  daily_km <- record[[2]]
  altitude <- record[[3]]
  distance <- baseline_distance(days, daily_km)
  distance <- wind_adjustment(distance, altitude)
  fatigue_adjustment(distance, days)
}

validate_record <- function(record, index) {
  if (length(record) != 3) {
    stop(sprintf("record %d must contain exactly three values", index))
  }
  values <- as.numeric(record)
  if (any(is.na(values))) {
    stop(sprintf("record %d contains non-numeric values", index))
  }
  if (any(values < 0)) {
    stop(sprintf("record %d contains negative values", index))
  }
  values
}

migration <- function(flocks) {
  total <- 0
  best <- 0
  for (i in seq_along(flocks)) {
    record <- validate_record(flocks[[i]], i)
    adjusted <- flock_distance(record)
    total <- total + adjusted
    if (adjusted > best) {
      best <- adjusted
    }
  }
  c(total, best)
}

format_report <- function(flocks) {
  result <- migration(flocks)
  lines <- character(0)
  for (i in seq_along(flocks)) {
    record <- validate_record(flocks[[i]], i)
    lines <- c(lines, sprintf("Flock %d: %d days, %.1f km", i, as.integer(record[1]),
                              flock_distance(record)))
  }
  summary_line <- sprintf("Total: %.1f km, best flock: %.1f km", result[1], result[2])
  paste(c(lines, summary_line), collapse = "\n")
}

sample_flocks <- list(c(5, 100, 1500), c(12, 80, 2500))
cat(format_report(sample_flocks), "\n")

