bracket_of <- function(age) {
  if (age < 18) {
    "youth"
  } else if (age <= 64) {
    "adult"
  } else {
    "senior"
  }
}

validate_citizen <- function(citizen) {
  if (length(citizen) != 2) {
    stop("each citizen must be a pair of (age, sex)")
  }
  age <- citizen[[1]]
  sex <- citizen[[2]]
  if (!is.numeric(age) || is.na(age) || age < 0) {
    stop("age must be a non-negative number")
  }
  if (!(sex %in% c(0, 1))) {
    stop("sex indicator must be 0 (male) or 1 (female)")
  }
  list(age = age, sex = sex)
}

demographics <- function(citizens) {
  youth <- 0
  adult <- 0
  senior <- 0
  adult_male <- 0
  adult_female <- 0
  for (entry in citizens) {
    person <- validate_citizen(entry)
    group <- bracket_of(person$age)
    if (group == "youth") {
      youth <- youth + 1
    } else if (group == "senior") {
      senior <- senior + 1
    } else {
      adult <- adult + 1
      if (person$sex == 1) {
        adult_female <- adult_female + 1
      } else {
        adult_male <- adult_male + 1
      }
    }
  }
  ratio <- if (adult > 0) (youth + senior) / adult * 100 else NA_real_
  list(youth, adult, senior, adult_female, ratio)
}

format_summary <- function(summary) {
  labels <- c("youth", "adults", "seniors", "adult females", "dependency ratio")
  values <- vapply(summary, function(v) format(v, nsmall = 0), character(1))
  paste(paste0(labels, ": ", values), collapse = " | ")
}

main <- function() {
  sample_population <- list(c(10, 0), c(30, 1), c(40, 0), c(70, 1))
  summary <- demographics(sample_population)
  cat(format_summary(summary), "\n")
  cat("returned vector:", unlist(summary), "\n")

  wider <- list(c(5, 1), c(17, 0), c(18, 1), c(64, 0), c(65, 1), c(99, 0), c(45, 1))
  wide_summary <- demographics(wider)
  cat(format_summary(wide_summary), "\n")

  ratio <- wide_summary[[5]]
  verdict <- if (ratio > 100) "dependent-heavy" else "working-age majority"
  cat("population is", verdict, "\n")
}

main()

