exchange <- function(transactions) {
  total <- 0
  zero_count <- 0
  for (tx in transactions) {
    parts <- as.numeric(tx)
    if (length(parts) != 3L || anyNA(parts)) {
      stop("each transaction needs numeric amount, rate and fee")
    }
    amount <- parts[1]
    rate <- parts[2]
    fee <- parts[3]
    if (amount > 1000) {
      fee <- 0
    }
    net <- amount * rate - fee
    if (net < 0) {
      net <- 0
    }
    if (net == 0) {
      zero_count <- zero_count + 1L
    }
    total <- total + net
  }
  list(total = total, zeros = zero_count)
}

net_of <- function(transaction) {
  single <- exchange(list(transaction))
  single$total
}

format_report <- function(transactions, currency = "EUR") {
  lines <- character(0)
  for (tx in transactions) {
    net <- net_of(tx)
    label <- sprintf("$%s at %s", format(tx[1], nsmall = 2), tx[2])
    waived <- if (tx[1] > 1000) " (fee waived)" else sprintf(" (fee %s)", tx[3])
    lines <- c(lines, sprintf("%-24s -> %8.2f %s%s", label, net, currency, waived))
  }
  summary <- exchange(transactions)
  footer <- sprintf("TOTAL %.2f %s across %d transactions; %d netted zero",
                    summary$total, currency, length(transactions), summary$zeros)
  paste(c(lines, footer), collapse = "\n")
}

parse_transactions <- function(text) {
  rows <- strsplit(trimws(text), "\n", fixed = TRUE)[[1]]
  rows <- rows[nzchar(trimws(rows))]
  lapply(rows, function(row) {
    fields <- strsplit(trimws(row), "[,;[:space:]]+")[[1]]
    as.numeric(fields)
  })
}

main <- function() {
  sample <- list(c(500, 0.9, 10), c(1500, 0.8, 50), c(10, 0.5, 10))
  result <- exchange(sample)
  cat(sprintf("exchange() -> [%.1f, %d]\n", result$total, result$zeros))
