PKA <- 4.76
PH_LOWER <- PKA - 1
PH_UPPER <- PKA + 1
MIN_TOTAL <- 0.1

henderson_hasselbalch <- function(acid, base) {
  if (acid <= 0 || base <= 0) {
    return(NA_real_)
  }
  PKA + log10(base / acid)
}

validate_sample <- function(sample) {
  if (length(sample) != 2 || any(!is.finite(sample))) {
    stop("each sample must hold two finite numbers: acid and base concentration")
  }
  if (any(sample < 0)) {
    stop("concentrations cannot be negative")
  }
  as.numeric(sample)
}

is_effective <- function(ph, total) {
  if (!is.finite(ph)) {
    return(FALSE)
  }
  ph > PH_LOWER && ph < PH_UPPER && total > MIN_TOTAL
}

buffer <- function(samples) {
  effective <- 0L
  max_ph <- -Inf
  for (entry in samples) {
    pair <- validate_sample(entry)
    acid <- pair[1]
    base <- pair[2]
    ph <- henderson_hasselbalch(acid, base)
    total <- acid + base
    if (is_effective(ph, total)) {
      effective <- effective + 1L
    }
    if (is.finite(ph) && ph > max_ph) {
      max_ph <- ph
    }
  }
  if (!is.finite(max_ph)) {
    max_ph <- NA_real_
  }
  list(effective = effective, max_ph = round(max_ph, 3))
}

describe_sample <- function(sample) {
  pair <- validate_sample(sample)
  ph <- henderson_hasselbalch(pair[1], pair[2])
  total <- pair[1] + pair[2]
  verdict <- if (is_effective(ph, total)) "effective" else "weak"
  ph_text <- if (is.finite(ph)) sprintf("%.3f", ph) else "undefined"
  sprintf("acid=%.3f base=%.3f total=%.3f pH=%s -> %s",
          pair[1], pair[2], total, ph_text, verdict)
}

report <- function(samples) {
  detail <- vapply(samples, describe_sample, character(1))
  totals <- buffer(samples)
  tail_line <- sprintf("effective=%d maxPH=%s", totals$effective,
                       format(totals$max_ph, nsmall = 3))
  c(detail, tail_line)
}

main <- function() {
  samples <- list(c(0.1, 0.1), c(0.01, 0.01), c(0.2, 0.8))
  cat(report(samples), sep = "\n")
  cat("\n")
  result <- buffer(samples)
  cat(sprintf("[%d, %s]\n", result$effective, format(result$max_ph, nsmall = 3)))
}

main()

