TARGET_TEMP <- 70
RATE_PER_DEGREE <- 0.5
EXTREME_PENALTY <- 2
HOT_THRESHOLD <- 90
COLD_THRESHOLD <- 30

validate_temperatures <- function(temperatures) {
  values <- suppressWarnings(as.numeric(unlist(temperatures)))
  if (length(values) == 0) {
    stop("hvac: at least one hourly temperature is required")
  }
  if (any(is.na(values))) {
    bad <- which(is.na(values))
    stop(paste("hvac: non-numeric temperature at position(s)",
               paste(bad, collapse = ", ")))
  }
  values
}

hourly_energy <- function(temperature) {
  difference <- abs(temperature - TARGET_TEMP)
  usage <- 0
  if (difference > 5) {
    usage <- RATE_PER_DEGREE * difference
  }
  if (temperature > HOT_THRESHOLD || temperature < COLD_THRESHOLD) {
    usage <- usage + EXTREME_PENALTY
  }
  usage
}

hvac <- function(temperatures) {
  readings <- validate_temperatures(temperatures)
  total <- 0
  peak <- 0
  for (temperature in readings) {
    usage <- hourly_energy(temperature)
    total <- total + usage
    if (usage > peak) {
      peak <- usage
    }
  }
  c(total, peak)
}

peak_hour <- function(temperatures) {
  readings <- validate_temperatures(temperatures)
  usages <- vapply(readings, hourly_energy, numeric(1))
  which.max(usages)
}

format_report <- function(temperatures) {
  result <- hvac(temperatures)
  hour <- peak_hour(temperatures)
  lines <- c(
    paste("Hours measured:", length(unlist(temperatures))),
    paste("Total energy:", format(result[1], nsmall = 1), "kWh"),
    paste("Peak hourly energy:", format(result[2], nsmall = 1), "kWh"),
    paste0("Peak occurred at hour ", hour, " (",
           unlist(temperatures)[hour], " F outside)")
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  sample_day <- c(72, 60, 95)
  winter_day <- c(28, 25, 31, 40, 55, 68, 70, 71, 66, 50, 35, 29)
  cat(format_report(sample_day), "\n\n", sep = "")
  cat(format_report(winter_day), "\n", sep = "")
  totals <- hvac(sample_day)
  cat("hvac(c(72, 60, 95)) -> [", totals[1], ", ", totals[2], "]\n", sep = "")
}

main()

