BASE_FEE <- 2.00
AXLE_FEE <- 1.50
OVERWEIGHT_SURCHARGE <- 5.00
ETC_DISCOUNT <- 0.20
WEIGHT_LIMIT <- 5

validate_vehicle <- function(record, index) {
  if (length(record) != 3) {
    stop(sprintf("vehicle %d must have exactly 3 fields", index))
  }
  axles <- record[[1]]
  weight <- record[[2]]
  etc <- record[[3]]
  if (!is.numeric(axles) || axles < 1 || axles != round(axles)) {
    stop(sprintf("vehicle %d has an invalid axle count", index))
  }
  if (!is.numeric(weight) || weight <= 0) {
    stop(sprintf("vehicle %d has an invalid weight", index))
  }
  if (!(identical(as.numeric(etc), 0) || identical(as.numeric(etc), 1))) {
    stop(sprintf("vehicle %d has an invalid ETC indicator", index))
  }
  c(axles = axles, weight = weight, etc = as.numeric(etc))
}

vehicle_fee <- function(axles, weight, etc) {
  fee <- BASE_FEE + AXLE_FEE * axles
  if (weight > WEIGHT_LIMIT) {
    fee <- fee + OVERWEIGHT_SURCHARGE
  }
  if (etc == 1) {
    fee <- fee * (1 - ETC_DISCOUNT)
  }
  fee
}

toll <- function(vehicles) {
  revenue <- 0
  overweight_count <- 0
  etc_count <- 0
  for (i in seq_along(vehicles)) {
    record <- validate_vehicle(vehicles[[i]], i)
    axles <- record[["axles"]]
    weight <- record[["weight"]]
    etc <- record[["etc"]]
    revenue <- revenue + vehicle_fee(axles, weight, etc)
    if (weight > WEIGHT_LIMIT) {
      overweight_count <- overweight_count + 1
    }
    if (etc == 1) {
      etc_count <- etc_count + 1
    }
  }
  list(revenue = revenue, overweight = overweight_count, etc = etc_count)
}

format_report <- function(result) {
  money <- formatC(result$revenue, format = "f", digits = 2)
  lines <- c(
    sprintf("Total revenue: $%s", money),
    sprintf("Overweight vehicles: %d", result$overweight),
    sprintf("Electronic collection: %d", result$etc)
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  sample_traffic <- list(c(2, 3, 1), c(4, 6, 0))
  summary <- toll(sample_traffic)
  cat(format_report(summary), "\n", sep = "")
  busy_hour <- list(c(2, 2, 0), c(3, 5, 1), c(5, 12, 1), c(6, 20, 0), c(2, 4.5, 1))
  hourly <- toll(busy_hour)
  cat(format_report(hourly), "\n", sep = "")
}

main()

