slots_for_duration = function(duration) {
  full_blocks = duration %/% 20
  as.integer(full_blocks)
}

rate_per_slot = function(downloads) {
  base_rate = 50 * (downloads / 1000)
  if (downloads > 50000) {
    base_rate = base_rate + 500
  }
  base_rate
}

validate_episode = function(episode, index) {
  if (length(episode) != 2) {
    stop(sprintf("episode %d must contain downloads and duration", index))
  }
  downloads = episode[[1]]
  duration = episode[[2]]
  if (!is.numeric(downloads) || !is.numeric(duration)) {
    stop(sprintf("episode %d must hold numeric values", index))
  }
  if (is.na(downloads) || is.na(duration) || downloads < 0 || duration < 0) {
    stop(sprintf("episode %d must hold non-negative values", index))
  }
  c(downloads = downloads, duration = duration)
}

episode_revenue = function(episode, index) {
  fields = validate_episode(episode, index)
  slots = slots_for_duration(fields[["duration"]])
  revenue = slots * rate_per_slot(fields[["downloads"]])
  premium = fields[["downloads"]] > 50000 && slots > 0
  list(revenue = revenue, slots = slots, premium = premium)
}

advertising = function(episodes) {
  total_revenue = 0
  total_slots = 0L
  premium_count = 0L
  for (i in seq_along(episodes)) {
    outcome = episode_revenue(episodes[[i]], i)
    total_revenue = total_revenue + outcome$revenue
    total_slots = total_slots + outcome$slots
    if (outcome$premium) {
      premium_count = premium_count + 1L
    }
  }
  list(as.numeric(total_revenue), total_slots, premium_count)
}

format_report = function(episodes) {
  result = advertising(episodes)
  lines = character(0)
  for (i in seq_along(episodes)) {
    outcome = episode_revenue(episodes[[i]], i)
    tag = if (outcome$premium) " (premium)" else ""
    lines = c(lines, sprintf("Episode %d: %d slot(s), $%.2f%s",
                              i, outcome$slots, outcome$revenue, tag))
  }
  summary_line = sprintf("Total: $%.2f across %d slot(s), %d premium episode(s)",
                          result[[1]], result[[2]], result[[3]])
  paste(c(lines, summary_line), collapse = "\n")
}

