NGP_RA_DEG <- 192.85948
NGP_DEC_DEG <- 27.12825
NCP_L_DEG <- 122.93192

deg2rad <- function(deg) deg * pi / 180
rad2deg <- function(rad) rad * 180 / pi

normalise_longitude <- function(l_deg) {
  wrapped <- l_deg %% 360
  wrapped
}

validate_pair <- function(pair, index) {
  if (length(pair) != 2 || !is.numeric(pair) || any(is.na(pair))) {
    stop(sprintf("coordinate %d must be a numeric pair (ra, dec)", index))
  }
  dec <- pair[2]
  if (dec < -90 || dec > 90) {
    stop(sprintf("declination %g at coordinate %d is outside [-90, 90]", dec, index))
  }
  invisible(TRUE)
}

equatorial_to_galactic <- function(ra_deg, dec_deg) {
  ra <- deg2rad(ra_deg)
  dec <- deg2rad(dec_deg)
  pole_ra <- deg2rad(NGP_RA_DEG)
  pole_dec <- deg2rad(NGP_DEC_DEG)

  sin_dec <- sin(dec)
  cos_dec <- cos(dec)
  sin_pole <- sin(pole_dec)
  cos_pole <- cos(pole_dec)
  sin_dra <- sin(ra - pole_ra)
  cos_dra <- cos(ra - pole_ra)

  sin_b <- sin_dec * sin_pole + cos_dec * cos_pole * cos_dra
  b <- asin(pmin(pmax(sin_b, -1), 1))

  y <- cos_dec * sin_dra
  x <- sin_dec * cos_pole - cos_dec * sin_pole * cos_dra
  l <- deg2rad(NCP_L_DEG) - atan2(y, x)

  c(normalise_longitude(rad2deg(l)), rad2deg(b))
}

astronomy <- function(coordinates) {
  result <- vector("list", length(coordinates))
  for (i in seq_along(coordinates)) {
    pair <- coordinates[[i]]
    validate_pair(pair, i)
    result[[i]] <- equatorial_to_galactic(pair[1], pair[2])
  }
  result
}

format_report <- function(coordinates, galactic) {
  lines <- character(length(galactic))
  for (i in seq_along(galactic)) {
    eq <- coordinates[[i]]
    gal <- galactic[[i]]
    lines[i] <- sprintf("RA %8.3f  Dec %8.3f  ->  l %8.3f  b %8.3f",
                        eq[1], eq[2], gal[1], gal[2])
  }
  paste(lines, collapse = "\n")
}

main <- function() {
  input <- list(c(10, 20), c(192.85948, 27.12825), c(266.405, -28.936))
  galactic <- astronomy(input)
  cat(format_report(input, galactic), "\n", sep = "")
}

main()

