pressure <- function(readings) {
  results <- vector("list", length(readings))
  for (i in seq_along(readings)) {
    pair <- readings[[i]]
    systolic <- pair[[1]]
    diastolic <- pair[[2]]
    pulse <- systolic - diastolic
    map <- diastolic + pulse / 3
    category <- classify(map, pulse)
    results[[i]] <- list(pulse, map, category)
  }
  results
}

classify <- function(map, pulse) {
  category <- "normal risk"
  if (map > 100 && pulse > 60) {
    category <- "high risk"
  } else if (map < 70) {
    category <- "low risk"
  }
  category
}

validate_readings <- function(readings) {
  for (i in seq_along(readings)) {
    pair <- readings[[i]]
    if (length(pair) != 2) {
      stop(sprintf("reading %d must contain exactly two values", i))
    }
    values <- as.numeric(unlist(pair))
    if (any(is.na(values))) {
      stop(sprintf("reading %d contains non-numeric values", i))
    }
    if (values[1] <= values[2]) {
      stop(sprintf("reading %d has systolic not above diastolic", i))
    }
  }
  invisible(TRUE)
}

format_report <- function(readings, analysis) {
  lines <- character(length(analysis))
  for (i in seq_along(analysis)) {
    row <- analysis[[i]]
    pair <- readings[[i]]
    label <- paste0(pair[[1]], "/", pair[[2]])
    lines[i] <- sprintf("%-8s pulse=%3d  MAP=%6.2f  %s",
                        label, as.integer(row[[1]]), row[[2]], row[[3]])
  }
  paste(lines, collapse = "\n")
}

summarise_categories <- function(analysis) {
  categories <- vapply(analysis, function(row) row[[3]], character(1))
  counts <- table(factor(categories,
                         levels = c("low risk", "normal risk", "high risk")))
  parts <- sprintf("%s: %d", names(counts), as.integer(counts))
  paste(parts, collapse = ", ")
}

main <- function() {
  samples <- list(c(120, 80), c(180, 100), c(95, 65), c(150, 85))
  validate_readings(samples)
  analysis <- pressure(samples)
  cat(format_report(samples, analysis), "\n", sep = "")
  cat("Totals -> ", summarise_categories(analysis), "\n", sep = "")
  single <- pressure(list(c(120, 80)))
  cat("Single reading 120/80 -> ", single[[1]][[3]], "\n", sep = "")
}

main()

