degrees_plato <- function(sg) {
  -616.868 + 1111.14 * sg - 630.272 * sg^2 + 135.997 * sg^3
}

apparent_attenuation <- function(og, fg) {
  (og - fg) / (og - 1) * 100
}

alcohol_by_weight <- function(og, fg) {
  (og - fg) * 76.08
}

alcohol_by_volume <- function(abw, fg) {
  abw * fg / 0.794
}

carbohydrate_calories <- function(fg) {
  extract_grams <- 3.5488 * fg * degrees_plato(fg)
  4 * extract_grams
}

alcohol_calories <- function(abw, fg) {
  alcohol_grams <- 3.5488 * fg * abw
  7 * alcohol_grams
}

check_gravity_pair <- function(pair) {
  if (length(pair) != 2 || !is.numeric(pair) || any(is.na(pair))) {
    stop("each reading must be a numeric pair of original and final gravity")
  }
  og <- pair[[1]]
  fg <- pair[[2]]
  if (og <= 1 || fg <= 1) {
    stop("gravities must be greater than 1.000")
  }
  if (fg >= og) {
    stop("final gravity must be below original gravity")
  }
  invisible(TRUE)
}

fermentation <- function(gravities) {
  results <- vector("list", length(gravities))
  for (i in seq_along(gravities)) {
    pair <- gravities[[i]]
    check_gravity_pair(pair)
    og <- pair[[1]]
    fg <- pair[[2]]
    attenuation <- apparent_attenuation(og, fg)
    abw <- alcohol_by_weight(og, fg)
    abv <- alcohol_by_volume(abw, fg)
    calories <- carbohydrate_calories(fg) + alcohol_calories(abw, fg)
    results[[i]] <- list(abv, attenuation, calories)
  }
  results
}

format_row <- function(pair, result) {
  sprintf("%.3f  %.3f  %6.2f %%  %6.2f %%  %7.1f",
          pair[[1]], pair[[2]], result[[1]], result[[2]], result[[3]])
}

gravities <- list(c(1.050, 1.010), c(1.075, 1.015), c(1.040, 1.008))
readings <- fermentation(gravities)
header <- sprintf("%-5s  %-5s  %8s  %8s  %7s", "OG", "FG", "ABV", "AA", "Cal/12oz")
cat(header, "\n")
cat(strrep("-", nchar(header)), "\n")
for (i in seq_along(readings)) {
  line <- format_row(gravities[[i]], readings[[i]])
  cat(line, "\n")
}

