base_ev <- function(aperture, shutter) {
  log2(aperture^2 / shutter)
}

iso_adjustment <- function(film_speed) {
  log2(film_speed / 100)
}

standard_ev <- function(aperture, shutter, film_speed) {
  base <- base_ev(aperture, shutter)
  base - iso_adjustment(film_speed)
}

illuminance_lux <- function(ev100, calibration = 2.5) {
  calibration * 2^ev100
}

hyperfocal_metres <- function(aperture, focal_length = 50, coc = 0.03) {
  distance_mm <- focal_length^2 / (aperture * coc)
  distance_mm / 1000
}

validate_setting <- function(setting) {
  if (length(setting) != 3) {
    stop("each setting needs aperture, shutter speed and film speed")
  }
  values <- as.numeric(unlist(setting))
  if (any(is.na(values)) || any(values <= 0)) {
    stop("aperture, shutter speed and film speed must be positive numbers")
  }
  values
}

exposure <- function(settings) {
  results <- vector("list", length(settings))
  for (i in seq_along(settings)) {
    values <- validate_setting(settings[[i]])
    aperture <- values[1]
    shutter <- values[2]
    film_speed <- values[3]
    ev100 <- standard_ev(aperture, shutter, film_speed)
    lux <- illuminance_lux(ev100)
    hyperfocal <- hyperfocal_metres(aperture)
    results[[i]] <- list(ev = ev100, lux = lux, hyperfocal = hyperfocal)
  }
  results
}

format_result <- function(setting, result) {
  values <- as.numeric(unlist(setting))
  shutter_label <- if (values[2] < 1) paste0("1/", round(1 / values[2])) else format(values[2])
  header <- sprintf("f/%s at %ss, ISO %s", format(values[1]), shutter_label, format(values[3]))
  body <- sprintf("  EV100 = %.2f | illuminance = %.1f lux | hyperfocal = %.2f m",
                  result$ev, result$lux, result$hyperfocal)
  paste(header, body, sep = "\n")
}

report <- function(settings) {
  computed <- exposure(settings)
  lines <- mapply(format_result, settings, computed, USE.NAMES = FALSE)
  paste(lines, collapse = "\n")
}

main <- function() {
  settings <- list(
    list(2.8, 1 / 100, 400),
    list(8, 1 / 250, 100),
    list(16, 1 / 60, 200)
  )
  text <- report(settings)
  cat(text, "\n", sep = "")
}

main()

