EARTH_RADIUS_KM <- 6371.0

to_radians <- function(degrees) {
  degrees * pi / 180
}

haversine_term <- function(delta) {
  sin(delta / 2)^2
}

great_circle_distance <- function(lat1, lon1, lat2, lon2) {
  dlat <- lat2 - lat1
  dlon <- lon2 - lon1
  a <- haversine_term(dlat) + cos(lat1) * cos(lat2) * haversine_term(dlon)
  angular <- 2 * atan2(sqrt(a), sqrt(1 - a))
  EARTH_RADIUS_KM * angular
}

initial_bearing <- function(lat1, lon1, lat2, lon2) {
  dlon <- lon2 - lon1
  y <- sin(dlon) * cos(lat2)
  x <- cos(lat1) * sin(lat2) - sin(lat1) * cos(lat2) * cos(dlon)
  theta <- atan2(y, x)
  degrees <- theta * 180 / pi
  (degrees + 360) %% 360
}

validate_route <- function(route) {
  if (length(route) != 4) {
    stop("each route needs latitude one, longitude one, latitude two, longitude two")
  }
  values <- as.numeric(route)
  if (any(is.na(values))) {
    stop("route coordinates must be numeric")
  }
  if (any(abs(values[c(1, 3)]) > 90)) {
    stop("latitudes must lie between -90 and 90 degrees")
  }
  if (any(abs(values[c(2, 4)]) > 180)) {
    stop("longitudes must lie between -180 and 180 degrees")
  }
