decay <- function(isotopes) {
    parent0 <- isotopes[[1]]
    parent_half_life <- isotopes[[2]]
    daughter_half_life <- isotopes[[3]]
    times <- isotopes[[4]]
    daughter0 <- 0

    validate_inputs(parent0, parent_half_life, daughter_half_life, times)

    lambda_p <- log(2) / parent_half_life
    lambda_d <- log(2) / daughter_half_life

    result <- vector("list", length(times))
    for (i in seq_along(times)) {
        t <- times[[i]]
        parent <- parent0 * exp(-lambda_p * t)
        daughter <- daughter0 * exp(-lambda_d * t) +
            bateman(parent0, lambda_p, lambda_d, t)
        result[[i]] <- c(parent = parent, daughter = daughter)
    }
    result
}

bateman <- function(parent0, lambda_p, lambda_d, t) {
    if (isTRUE(all.equal(lambda_p, lambda_d))) {
        return(parent0 * lambda_p * t * exp(-lambda_p * t))
    }
    ratio <- lambda_p / (lambda_d - lambda_p)
    ratio * parent0 * (exp(-lambda_p * t) - exp(-lambda_d * t))
}

validate_inputs <- function(parent0, parent_half_life, daughter_half_life, times) {
    if (!is.numeric(parent0) || length(parent0) != 1 || parent0 < 0) {
        stop("initial parent quantity must be a single non-negative number")
    }
    half_lives <- c(parent_half_life, daughter_half_life)
    if (!is.numeric(half_lives) || length(half_lives) != 2 || any(half_lives <= 0)) {
        stop("both half lives must be positive numbers")
    }
    time_values <- unlist(times)
    if (!is.numeric(time_values) || length(time_values) == 0 || any(time_values < 0)) {
        stop("time points must be non-negative numbers")
    }
    invisible(TRUE)
}

format_report <- function(isotopes, quantities) {
    times <- unlist(isotopes[[4]])
    header <- sprintf("%10s %14s %14s", "time (yr)", "parent", "daughter")
    rows <- character(length(times))
    for (i in seq_along(times)) {
        pair <- quantities[[i]]
        rows[i] <- sprintf("%10.2f %14.4f %14.4f", times[i], pair[["parent"]], pair[["daughter"]])
    }
    paste(c(header, rows), collapse = "\n")
}

main <- function() {
    isotopes <- list(1000, 10, 5, list(0, 5, 10))
    quantities <- decay(isotopes)
    cat(format_report(isotopes, quantities), "\n", sep = "")

    long_run <- list(500, 4.5, 30, as.list(seq(0, 60, by = 15)))
    cat("\n", format_report(long_run, decay(long_run)), "\n", sep = "")
}

main()

