tide_cycle <- function(cycle) {
  low_time <- cycle[[1]]
  low_height <- cycle[[2]]
  high_time <- cycle[[3]]
  high_height <- cycle[[4]]
  target_time <- cycle[[5]]

  duration <- high_time - low_time
  amplitude <- (high_height - low_height) / 2
  mean_level <- low_height + amplitude
  elapsed <- target_time - low_time
  phase <- pi * elapsed / duration

  mean_level - amplitude * cos(phase)
}

validate_cycle <- function(cycle, index) {
  if (length(cycle) != 5) {
    stop(sprintf("cycle %d must contain exactly 5 values", index))
  }
  values <- unlist(cycle)
  if (!is.numeric(values) || any(is.na(values))) {
    stop(sprintf("cycle %d must contain only numeric values", index))
  }
  if (values[3] == values[1]) {
    stop(sprintf("cycle %d has equal low and high tide times", index))
  }
  invisible(TRUE)
}

tides <- function(data) {
  if (!is.list(data) || length(data) == 0) {
    stop("data must be a non-empty list of cycles")
  }
  results <- vector("list", length(data))
  for (i in seq_along(data)) {
    cycle <- data[[i]]
    validate_cycle(cycle, i)
    results[[i]] <- tide_cycle(cycle)
  }
  results
}

format_clock <- function(hours) {
  whole <- floor(hours)
  minutes <- round((hours - whole) * 60)
  sprintf("%02d:%02d", as.integer(whole) %% 24, as.integer(minutes))
}

tide_report <- function(data) {
  heights <- tides(data)
  lines <- character(length(heights))
  for (i in seq_along(heights)) {
    cycle <- data[[i]]
    stamp <- format_clock(cycle[[5]])
    lines[i] <- sprintf("cycle %d: at %s the water is %.3f m deep (low %.2f m, high %.2f m)",
                        i, stamp, heights[[i]], cycle[[2]], cycle[[4]])
  }
  lines
}

main <- function() {
  sample_data <- list(
    list(2, 1, 8, 5, 5),
    list(0.5, 0.8, 6.75, 4.2, 3),
    list(13, 1.2, 19.5, 6.4, 18)
  )
  report <- tide_report(sample_data)
  cat(report, sep = "\n")
  cat("\n")
  estimates <- unlist(tides(sample_data))
  cat(sprintf("mean estimated depth: %.3f m\n", mean(estimates)))
}

main()

