validate_measurement <- function(m) {
  if (length(m) != 4) {
    stop("each measurement must contain exactly four volumes")
  }
  values <- as.numeric(unlist(m))
  if (any(is.na(values))) {
    stop("volumes must be numeric")
  }
  if (any(values <= 0)) {
    stop("volumes must be positive, in liters")
  }
  values
}

lung_volumes <- function(m) {
  v <- validate_measurement(m)
  tidal <- v[1]
  inspiratory_reserve <- v[2]
  expiratory_reserve <- v[3]
  residual <- v[4]
  inspiratory_capacity <- tidal + inspiratory_reserve
  vital_capacity <- inspiratory_capacity + expiratory_reserve
  functional_residual <- expiratory_reserve + residual
  total_lung_capacity <- vital_capacity + residual
  capacity_ratio <- 100 * functional_residual / total_lung_capacity
  list(
    inspiratory_capacity = inspiratory_capacity,
    vital_capacity = vital_capacity,
    functional_residual_capacity = functional_residual,
    total_lung_capacity = total_lung_capacity,
    capacity_ratio = capacity_ratio
  )
}

spirometry <- function(measurements) {
  if (!is.list(measurements)) {
    stop("measurements must be a list")
  }
  if (length(measurements) > 0 && !is.list(measurements[[1]])) {
    measurements <- list(measurements)
  }
  lapply(measurements, lung_volumes)
}

format_report <- function(index, result) {
  numbers <- sprintf("%.2f", unlist(result[1:4]))
  ratio <- sprintf("%.1f%%", result$capacity_ratio)
  labels <- c("IC", "VC", "FRC", "TLC")
  body <- paste(labels, numbers, "L", collapse = "  ")
  paste0("Patient ", index, ": ", body, "  FRC/TLC ", ratio)
}

print_report <- function(results) {
  lines <- vapply(seq_along(results),
                  function(i) format_report(i, results[[i]]),
                  character(1))
  cat(lines, sep = "\n")
  cat("\n")
}

main <- function() {
  patients <- list(
    list(0.5, 2.5, 1.5, 1.2),
    list(0.45, 3.1, 1.1, 1.3),
    list(0.6, 2.0, 0.9, 1.5)
  )
  results <- spirometry(patients)
  print_report(results)
  mean_tlc <- mean(vapply(results, function(r) r$total_lung_capacity, numeric(1)))
  cat(sprintf("Mean total lung capacity: %.2f L\n", mean_tlc))
  single <- spirometry(list(0.5, 2.5, 1.5, 1.2))
  cat(format_report(1, single[[1]]), "\n")
}

main()

