normalize_fractions <- function(parts) {
  total <- sum(parts)
  if (total <= 0) {
    stop("particle percentages must sum to a positive value")
  }
  if (abs(total - 100) > 1e-9) {
    parts <- parts / total * 100
  }
  parts
}

validate_sample <- function(entry, index) {
  if (length(entry) != 3) {
    stop(sprintf("sample %d must contain sand, silt and clay", index))
  }
  values <- as.numeric(unlist(entry))
  if (anyNA(values)) {
    stop(sprintf("sample %d contains a non-numeric value", index))
  }
  if (any(values < 0)) {
    stop(sprintf("sample %d contains a negative percentage", index))
  }
  values
}

classify_texture <- function(sand, silt, clay) {
  label <- "loam"
  if (clay > 40 && sand > 45) {
    label <- "sandy clay"
  } else if (clay > 40 && silt > 40) {
    label <- "silty clay"
  } else if (clay > 40) {
    label <- "clay"
  } else if (sand > 85) {
    label <- "sand"
  }
  label
}

soil <- function(samples) {
  classes <- character(length(samples))
  for (i in seq_along(samples)) {
    values <- validate_sample(samples[[i]], i)
    parts <- normalize_fractions(values)
    sand <- parts[1]
    silt <- parts[2]
    clay <- parts[3]
    classes[i] <- classify_texture(sand, silt, clay)
  }
  as.list(classes)
}

soil_report <- function(samples) {
  textures <- soil(samples)
  rows <- character(length(textures))
  for (i in seq_along(textures)) {
    parts <- normalize_fractions(validate_sample(samples[[i]], i))
    rows[i] <- sprintf("sand %5.1f%%  silt %5.1f%%  clay %5.1f%%  ->  %s",
                       parts[1], parts[2], parts[3], textures[[i]])
  }
  rows
}

main <- function() {
  samples <- list(
    list(50, 30, 20),
    list(20, 20, 60),
    list(50, 5, 45),
    list(10, 45, 45),
    list(90, 5, 5),
    list(30, 20, 10)
  )
  report <- soil_report(samples)
  cat(report, sep = "\n")
  cat("\n")
}

main()

