pressure_altitude <- function(station_pressure) {
  difference <- STANDARD_SEA_LEVEL_PRESSURE - station_pressure
  difference * 1000 + FIELD_ELEVATION
}

standard_temperature <- function(altitude) {
  SEA_LEVEL_STANDARD_TEMP - LAPSE_RATE_PER_1000FT * (altitude / 1000)
}

density_altitude <- function(altitude, ambient_temp) {
  deviation <- ambient_temp - standard_temperature(altitude)
  altitude + DEVIATION_FACTOR * deviation
}

validate_reading <- function(reading, index) {
  if (length(reading) != 2) {
    stop(sprintf("Reading %d must contain pressure and temperature", index))
  }
  values <- as.numeric(unlist(reading))
  if (any(is.na(values))) {
    stop(sprintf("Reading %d contains non-numeric values", index))
  }
  values
}

aviation <- function(readings) {
  results <- vector("list", length(readings))
  for (i in seq_along(readings)) {
    values <- validate_reading(readings[[i]], i)
    station_pressure <- values[1]
    ambient_temp <- values[2]
    p_alt <- pressure_altitude(station_pressure)
    d_alt <- density_altitude(p_alt, ambient_temp)
    results[[i]] <- list(p_alt, d_alt)
  }
  results
}

format_report <- function(readings, results) {
  lines <- character(length(results))
  for (i in seq_along(results)) {
    values <- as.numeric(unlist(readings[[i]]))
    altitudes <- as.numeric(unlist(results[[i]]))
    lines[i] <- sprintf(
      "%6.2f inHg %6.1f C -> pressure altitude %8.1f ft, density altitude %8.1f ft",
      values[1], values[2], altitudes[1], altitudes[2]
    )
  }
  paste(lines, collapse = "\n")
}

main <- function() {
  observations <- list(
    list(29.5, 25),
    list(29.92, 15),
    list(30.15, -5),
    list(28.75, 32)
  )
  computed <- aviation(observations)
  report <- format_report(observations, computed)
  cat(report, "\n", sep = "")
  single <- aviation(list(list(29.5, 25)))
  cat(sprintf("Example: %s\n", paste(unlist(single[[1]]), collapse = ", ")))
}

main()

