inequality <- function(incomes) {
  cum_pop <- 0
  cum_inc <- 0
  area <- 0
  for (segment in incomes) {
    pop_frac <- segment[[1]]
    inc_frac <- segment[[2]]
    prev_pop <- cum_pop
    prev_inc <- cum_inc
    cum_pop <- prev_pop + pop_frac
    cum_inc <- prev_inc + inc_frac
    trapezoid <- (cum_pop - prev_pop) * (prev_inc + cum_inc) / 2
    area <- area + trapezoid
  }
  gini <- 1 - 2 * area
  gini
}

validate_segments <- function(incomes) {
  if (length(incomes) == 0) {
    stop("at least one demographic segment is required")
  }
  pops <- vapply(incomes, function(s) s[[1]], numeric(1))
  incs <- vapply(incomes, function(s) s[[2]], numeric(1))
  if (any(pops < 0) || any(incs < 0)) {
    stop("population and income fractions must be non-negative")
  }
  pop_total <- sum(pops)
  inc_total <- sum(incs)
  if (abs(pop_total - 1) > 1e-6 || abs(inc_total - 1) > 1e-6) {
    stop("population and income fractions must each sum to 1")
  }
  invisible(TRUE)
}

lorenz_points <- function(incomes) {
  pops <- vapply(incomes, function(s) s[[1]], numeric(1))
  incs <- vapply(incomes, function(s) s[[2]], numeric(1))
  data.frame(population = c(0, cumsum(pops)), income = c(0, cumsum(incs)))
}

describe_inequality <- function(gini) {
  label <- if (gini < 0.25) {
    "low inequality"
  } else if (gini < 0.4) {
    "moderate inequality"
  } else {
    "high inequality"
  }
  sprintf("Gini coefficient %.4f (%s)", gini, label)
}

report <- function(name, incomes) {
  validate_segments(incomes)
  curve <- lorenz_points(incomes)
  gini <- inequality(incomes)
  cat(name, "\n")
  for (i in seq_len(nrow(curve))) {
    cat(sprintf("  cum pop %.2f -> cum income %.2f\n",
                curve$population[i], curve$income[i]))
  }
  cat(" ", describe_inequality(gini), "\n\n")
  invisible(gini)
}

quintiles <- list(list(0.2, 0.05), list(0.2, 0.10), list(0.2, 0.15),
                  list(0.2, 0.25), list(0.2, 0.45))
equal_shares <- list(list(0.25, 0.25), list(0.25, 0.25),
                     list(0.25, 0.25), list(0.25, 0.25))
skewed <- list(list(0.5, 0.02), list(0.4, 0.18), list(0.1, 0.80))

report("Quintile distribution", quintiles)
report("Perfectly equal distribution", equal_shares)
report("Highly skewed distribution", skewed)

