room_metrics <- function(len, width, height, alpha) {
  floor_area <- len * width
  ceiling_area <- floor_area
  perimeter <- 2 * (len + width)
  wall_area <- perimeter * height
  surface_area <- floor_area + ceiling_area + wall_area
  volume <- len * width * height
  absorption_area <- surface_area * alpha
  sabine <- 0.161 * volume / absorption_area
  list(volume = volume, surface = surface_area, sabine = sabine)
}

validate_room <- function(room, index) {
  if (length(room) != 4) {
    stop(sprintf("Room %d must have length, width, height and absorption coefficient", index))
  }
  values <- as.numeric(unlist(room))
  if (any(is.na(values))) {
    stop(sprintf("Room %d contains non-numeric entries", index))
  }
  dims <- values[1:3]
  if (any(dims <= 0)) {
    stop(sprintf("Room %d has non-positive dimensions", index))
  }
  alpha <- values[4]
  if (alpha <= 0 || alpha > 1) {
    stop(sprintf("Room %d has an absorption coefficient outside (0, 1]", index))
  }
  values
}

acoustics <- function(rooms) {
  results <- vector("list", length(rooms))
  for (i in seq_along(rooms)) {
    room <- validate_room(rooms[[i]], i)
    metrics <- room_metrics(room[1], room[2], room[3], room[4])
    results[[i]] <- list(metrics$volume, metrics$surface, metrics$sabine)
  }
  results
}

classify_reverberation <- function(sabine) {
  if (sabine < 0.6) {
    label <- "dry"
  } else if (sabine < 1.2) {
    label <- "speech-friendly"
  } else if (sabine < 2.0) {
    label <- "music-friendly"
  } else {
    label <- "reverberant"
  }
  label
}

format_report <- function(rooms, results) {
  report <- character(length(results))
  for (i in seq_along(results)) {
    entry <- results[[i]]
    dims <- as.numeric(unlist(rooms[[i]]))[1:3]
    shape <- paste(format(dims, trim = TRUE), collapse = " x ")
    report[i] <- sprintf("Room %d (%s m): V = %.2f m3, S = %.2f m2, T60 = %.3f s [%s]",
                         i, shape, entry[[1]], entry[[2]], entry[[3]],
                         classify_reverberation(entry[[3]]))
  }
  report
}

main <- function() {
  rooms <- list(list(10, 8, 3, 0.2),
                list(20, 15, 8, 0.12),
                list(4, 3, 2.5, 0.45))
  results <- acoustics(rooms)
  report <- format_report(rooms, results)
  cat(report, sep = "\n")
  cat("\n")
}

main()

