metrics <- function(lambda, mu) {
  rho <- lambda / mu
  p0 <- 1 - rho
  l <- lambda / (mu - lambda)
  w <- l / lambda
  service_time <- 1 / mu
  wq <- w - service_time
  list(intensity = rho, empty = p0, number = l, time = w, queue = wq)
}

validate <- function(system, index) {
  if (length(system) != 2) {
    stop(sprintf("system %d must contain an arrival rate and a service rate", index))
  }
  lambda <- system[[1]]
  mu <- system[[2]]
  if (!is.numeric(lambda) || !is.numeric(mu)) {
    stop(sprintf("system %d must use numeric rates", index))
  }
  if (lambda <= 0 || mu <= 0) {
    stop(sprintf("system %d must use positive rates", index))
  }
  if (lambda >= mu) {
    stop(sprintf("system %d is unstable: arrival rate %g is not below service rate %g",
                 index, lambda, mu))
  }
  c(lambda = lambda, mu = mu)
}

queue <- function(systems) {
  results <- vector("list", length(systems))
  for (i in seq_along(systems)) {
    rates <- validate(systems[[i]], i)
    stats <- metrics(rates[["lambda"]], rates[["mu"]])
    results[[i]] <- list(stats$intensity, stats$number, stats$queue)
  }
  results
}

report_line <- function(system, result) {
  lambda <- system[[1]]
  mu <- system[[2]]
  intensity <- result[[1]]
  number <- result[[2]]
  wait <- result[[3]]
  sprintf("lambda=%5.2f mu=%5.2f | rho=%.4f | P0=%.4f | L=%.4f | Wq=%.4f h (%.2f min)",
          lambda, mu, intensity, 1 - intensity, number, wait, wait * 60)
}

report <- function(systems) {
  results <- queue(systems)
  lines <- mapply(report_line, systems, results, USE.NAMES = FALSE)
  cat(lines, sep = "\n")
  cat("\n")
  invisible(results)
}

main <- function() {
  systems <- list(
    list(10, 15),
    list(20, 25),
    list(4.5, 9)
  )
  summary_stats <- report(systems)
  busiest <- which.max(vapply(summary_stats, function(r) r[[1]], numeric(1)))
  cat(sprintf("Most heavily loaded system: #%d\n", busiest))
}

main()

