GRAIN_SPECIFIC_HEAT <- 1.59
WATER_SPECIFIC_HEAT <- 4.18
BOILING_POINT <- 100

validate_step <- function(step) {
  if (length(step) != 4) {
    stop("each step needs grain weight, current temp, target temp and ratio")
  }
  values <- as.numeric(unlist(step))
  if (any(is.na(values))) {
    stop("step values must be numeric")
  }
  names(values) <- c("grain", "current", "target", "ratio")
  if (values[["grain"]] <= 0 || values[["ratio"]] <= 0) {
    stop("grain weight and water to grain ratio must be positive")
  }
  if (values[["target"]] < values[["current"]]) {
    stop("target temperature must not be below the current temperature")
  }
  if (values[["target"]] >= BOILING_POINT) {
    stop("target temperature must stay below boiling point")
  }
  values
}

boiling_addition <- function(grain, current, target, ratio) {
  water_volume <- grain * ratio
  grain_mass <- grain * GRAIN_SPECIFIC_HEAT
  water_mass <- water_volume * WATER_SPECIFIC_HEAT
  temp_gap <- target - current
  energy_needed <- (grain_mass + water_mass) * temp_gap
  energy_per_litre <- WATER_SPECIFIC_HEAT * (BOILING_POINT - target)
  added <- energy_needed / energy_per_litre
  list(added = added, total = water_volume + added)
}

mashing <- function(steps) {
  results <- vector("list", length(steps))
  for (i in seq_along(steps)) {
    step <- validate_step(steps[[i]])
    outcome <- boiling_addition(step[["grain"]], step[["current"]],
                                step[["target"]], step[["ratio"]])
    results[[i]] <- list(outcome$added, outcome$total)
  }
  results
}

format_result <- function(step, result) {
  values <- as.numeric(unlist(step))
  header <- sprintf("%.2f kg grain at %.1fC -> %.1fC (ratio %.2f L/kg)",
                    values[1], values[2], values[3], values[4])
  detail <- sprintf("  add %.3f L of boiling water, mash volume %.3f L",
                    result[[1]], result[[2]])
  paste(header, detail, sep = "\n")
}

main <- function() {
  schedule <- list(
    list(5, 65, 68, 3),
    list(5, 68, 72, 3.6),
    list(8.5, 52, 66, 2.8)
  )
  additions <- mashing(schedule)
  report <- mapply(format_result, schedule, additions)
  cat(paste(report, collapse = "\n"), "\n", sep = "")
  grand_total <- sum(vapply(additions, function(r) r[[1]], numeric(1)))
  cat(sprintf("Total boiling water required: %.3f L\n", grand_total))
}

main()

