front_power <- function(radius, index) {
  (index - 1) / radius
}

back_power <- function(radius, index) {
  (1 - index) / radius
}

thickness_effect <- function(p_front, p_back, thickness, index) {
  (p_front * p_back * thickness) / index
}

total_power <- function(p_front, p_back, effect) {
  p_front + p_back - effect
}

parse_lens <- function(spec) {
  values <- as.numeric(unlist(spec))
  if (length(values) != 4) {
    stop("each lens needs front radius, back radius, thickness and index")
  }
  if (any(is.na(values))) {
    stop("lens parameters must be numeric")
  }
  if (values[3] <= 0) {
    stop("lens thickness must be positive")
  }
  if (values[4] <= 1) {
    stop("refractive index must exceed 1")
  }
  values
}

focal_length <- function(values) {
  index <- values[4]
  p_front <- front_power(values[1], index)
  p_back <- back_power(values[2], index)
  effect <- thickness_effect(p_front, p_back, values[3], index)
  power <- total_power(p_front, p_back, effect)
  1 / power
}

lens <- function(parameters) {
  results <- numeric(length(parameters))
  for (i in seq_along(parameters)) {
    results[i] <- focal_length(parse_lens(parameters[[i]]))
  }
  as.list(results)
}

describe_lens <- function(values, focal) {
  shape <- if (focal > 0) "converging" else "diverging"
  paste0("R1=", values[1], " R2=", values[2], " d=", values[3],
         " n=", values[4], " -> EFL = ", format(round(focal, 6), nsmall = 6),
         " (", shape, ")")
}

report <- function(parameters) {
  focal_lengths <- lens(parameters)
  lines <- character(length(parameters))
  for (i in seq_along(parameters)) {
    values <- parse_lens(parameters[[i]])
    lines[i] <- describe_lens(values, focal_lengths[[i]])
  }
  lines
}

catalogue <- list(
  list(50, -50, 5, 1.5),
  list(-50, 50, 5, 1.5),
  list(100, -100, 8, 1.6),
  list(1e10, -50, 3, 1.52)
)

for (line in report(catalogue)) {
  cat(line, "\n")
}

