validate_details <- function(details) {
  required <- c("weight", "distance", "priority")
  absent <- setdiff(required, names(details))
  if (length(absent) > 0) {
    stop(paste("shipment details missing:", paste(absent, collapse = ", ")))
  }
  weight <- details$weight
  distance <- details$distance
  priority <- details$priority
  if (!is.numeric(weight) || length(weight) != 1 || is.na(weight) || weight <= 0) {
    stop("weight must be a single positive number")
  }
  if (!is.numeric(distance) || length(distance) != 1 || is.na(distance) || distance < 0) {
    stop("distance must be a single non-negative number")
  }
  if (!is.logical(priority) || length(priority) != 1 || is.na(priority)) {
    stop("priority must be TRUE or FALSE")
  }
  list(weight = weight, distance = distance, priority = priority)
}

base_fee <- function(weight) {
  weight * 3
}

distance_surcharge <- function(distance) {
  ceiling(distance / 50)
}

rush_fee <- function(priority) {
  if (priority) 20 else 0
}

shipment <- function(details) {
  clean <- validate_details(details)
  base <- base_fee(clean$weight)
  surcharge <- distance_surcharge(clean$distance)
  rush <- rush_fee(clean$priority)
  subtotal <- base + surcharge + rush
  tax <- subtotal * 0.05
  subtotal + tax
}

shipment_breakdown <- function(details) {
  clean <- validate_details(details)
  base <- base_fee(clean$weight)
  surcharge <- distance_surcharge(clean$distance)
  rush <- rush_fee(clean$priority)
  subtotal <- base + surcharge + rush
  data.frame(
    item = c("base fee", "distance surcharge", "rush fee", "subtotal", "tax", "total"),
    amount = c(base, surcharge, rush, subtotal, subtotal * 0.05, shipment(details)),
    stringsAsFactors = FALSE
  )
}

format_money <- function(amount) {
  paste0("$", formatC(amount, format = "f", digits = 2))
}

print_quote <- function(label, details) {
  breakdown <- shipment_breakdown(details)
  cat(label, "\n")
  for (i in seq_len(nrow(breakdown))) {
    line <- sprintf("  %-20s %10s", breakdown$item[i], format_money(breakdown$amount[i]))
    cat(line, "\n")
  }
}

main <- function() {
  standard <- list(weight = 4.5, distance = 120, priority = FALSE)
  express <- list(weight = 12, distance = 310, priority = TRUE)
  print_quote("Standard parcel:", standard)
  print_quote("Express parcel:", express)
  fleet_total <- shipment(standard) + shipment(express)
  cat("Combined total:", format_money(fleet_total), "\n")
}

main()

