count_outcome <- function(serves, outcome) {
  matches <- vapply(serves, function(s) identical(tolower(trimws(s)), outcome), logical(1))
  sum(matches)
}

normalise_serves <- function(serves) {
  if (!is.list(serves) && !is.character(serves)) {
    stop("serves must be a list or character vector of outcomes")
  }
  flat <- unlist(serves, use.names = FALSE)
  if (length(flat) == 0) {
    return(character(0))
  }
  cleaned <- tolower(trimws(as.character(flat)))
  known <- c("ace", "fault", "rally")
  unknown <- setdiff(unique(cleaned), known)
  if (length(unknown) > 0) {
    warning(paste("unrecognised outcomes:", paste(unknown, collapse = ", ")))
  }
  cleaned
}

percentage <- function(part, whole) {
  if (whole == 0) {
    return(0)
  }
  100 * part / whole
}

tennis <- function(serves) {
  outcomes <- normalise_serves(serves)
  total <- length(outcomes)
  aces <- count_outcome(outcomes, "ace")
  faults <- count_outcome(outcomes, "fault")
  ace_pct <- percentage(aces, total)
  fault_pct <- percentage(faults, total)
  in_play <- total - aces - faults
  dominance <- aces / (faults + 1)
  list(
    total = total,
    aces = aces,
    faults = faults,
    ace_percentage = ace_pct,
    fault_percentage = fault_pct,
    in_play = in_play,
    dominance = dominance
  )
}

format_report <- function(stats) {
  header <- sprintf("Serves played: %d", stats$total)
  ace_line <- sprintf("Aces: %d (%.1f%%)", stats$aces, stats$ace_percentage)
  fault_line <- sprintf("Faults: %d (%.1f%%)", stats$faults, stats$fault_percentage)
  play_line <- sprintf("Balls in play: %d", stats$in_play)
  dominance_line <- sprintf("Dominance: %.2f", stats$dominance)
  paste(c(header, ace_line, fault_line, play_line, dominance_line), collapse = "\n")
}

main <- function() {
  match_serves <- list("ace", "fault", "rally", "ace", "rally",
                       "fault", "ace", "rally", "rally", "ace")
  stats <- tennis(match_serves)
  cat(format_report(stats), "\n")
  tie_break <- c("ace", "ace", "rally", "fault")
  cat(format_report(tennis(tie_break)), "\n")
}

main()

