FUEL_PRICE_PER_GALLON <- 3.5
AVERAGE_SPEED_MPH <- 50
DRIVER_RATE_PER_HOUR <- 20
STOP_PENALTY <- 5

validate_route <- function(route) {
  required <- c("distance", "stops", "mpg")
  missing_fields <- required[!required %in% names(route)]
  if (length(missing_fields) > 0) {
    stop(paste("route is missing:", paste(missing_fields, collapse = ", ")))
  }
  values <- unlist(route[required])
  if (!is.numeric(values) || any(is.na(values))) {
    stop("distance, stops and mpg must all be numeric values")
  }
  if (route$mpg <= 0) {
    stop("mpg must be greater than zero")
  }
  if (route$distance < 0 || route$stops < 0) {
    stop("distance and stops cannot be negative")
  }
  invisible(TRUE)
}

fuel_needed <- function(distance, mpg) {
  distance / mpg
}

fuel_cost <- function(distance, mpg) {
  gallons <- fuel_needed(distance, mpg)
  gallons * FUEL_PRICE_PER_GALLON
}

driver_wage <- function(distance) {
  hours <- distance / AVERAGE_SPEED_MPH
  hours * DRIVER_RATE_PER_HOUR
}

stop_penalties <- function(stops) {
  stops * STOP_PENALTY
}

fleet <- function(route) {
  validate_route(route)
  distance <- route$distance
  stops <- route$stops
  mpg <- route$mpg
  fuel <- fuel_cost(distance, mpg)
  wage <- driver_wage(distance)
  penalty <- stop_penalties(stops)
  fuel + wage + penalty
}

route_report <- function(name, route) {
  total <- fleet(route)
  breakdown <- c(
    fuel = fuel_cost(route$distance, route$mpg),
    wage = driver_wage(route$distance),
    stops = stop_penalties(route$stops)
  )
  lines <- sprintf("  %-5s $%8.2f", names(breakdown), breakdown)
  c(sprintf("%s (%.1f mi, %d stops, %.1f mpg)",
            name, route$distance, as.integer(route$stops), route$mpg),
    lines,
    sprintf("  %-5s $%8.2f", "TOTAL", total))
}

main <- function() {
  routes <- list(
    "City loop" = list(distance = 120, stops = 8, mpg = 12),
    "Regional haul" = list(distance = 480, stops = 3, mpg = 7.5),
    "Suburban run" = list(distance = 65.5, stops = 14, mpg = 18)
  )
  for (name in names(routes)) {
    cat(route_report(name, routes[[name]]), sep = "\n")
    cat("\n")
  }
  grand_total <- sum(vapply(routes, fleet, numeric(1)))
  cat(sprintf("Fleet operating cost: $%.2f\n", grand_total))
}

main()

