AIR_DENSITY <- 1.2
BETZ_LIMIT <- 0.59

validate_conditions <- function(conditions) {
  required <- c("wind_speed", "radius", "efficiency")
  missing_fields <- required[!required %in% names(conditions)]
  if (length(missing_fields) > 0) {
    stop(paste("missing field(s):", paste(missing_fields, collapse = ", ")))
  }
  values <- unlist(conditions[required])
  if (any(!is.finite(values)) || any(values < 0)) {
    stop("wind speed, radius and efficiency must be finite and non-negative")
  }
  if (conditions$efficiency > 1) {
    stop("efficiency factor must not exceed 1")
  }
  invisible(TRUE)
}

swept_area <- function(radius) {
  pi * radius^2
}

kinetic_energy_flux <- function(area, wind_speed) {
  0.5 * AIR_DENSITY * area * wind_speed^3
}

turbine <- function(conditions) {
  validate_conditions(conditions)
  wind_speed <- conditions$wind_speed
  radius <- conditions$radius
  efficiency <- conditions$efficiency
  area <- swept_area(radius)
  flux <- kinetic_energy_flux(area, wind_speed)
  theoretical_power <- flux * BETZ_LIMIT
  actual_power <- theoretical_power * efficiency
  actual_power / 1000
}

format_report <- function(conditions, power_kw) {
  label <- sprintf("v=%.1f m/s, r=%.1f m, eta=%.2f",
                   conditions$wind_speed, conditions$radius, conditions$efficiency)
  sprintf("%-32s -> %8.2f kW", label, power_kw)
}

turbine_table <- function(cases) {
  lines <- vapply(cases, function(case) {
    power <- turbine(case)
    format_report(case, power)
  }, character(1))
  paste(lines, collapse = "\n")
}

main <- function() {
  small <- list(wind_speed = 8, radius = 12, efficiency = 0.35)
  medium <- list(wind_speed = 12, radius = 40, efficiency = 0.42)
  large <- list(wind_speed = 15, radius = 60, efficiency = 0.45)
  fleet <- list(small, medium, large)
  cat(turbine_table(fleet), "\n", sep = "")
  total <- sum(vapply(fleet, turbine, numeric(1)))
  cat(sprintf("Fleet output: %.2f kW\n", total))
  attempt <- try(turbine(list(wind_speed = 10, radius = 20)), silent = TRUE)
  if (inherits(attempt, "try-error")) {
    cat("Rejected incomplete conditions:", conditionMessage(attr(attempt, "condition")), "\n")
  }
}

main()

