validate_counts <- function(counts) {
  required <- c("expected", "actual", "unit_value")
  missing_fields <- required[!required %in% names(counts)]
  if (length(missing_fields) > 0) {
    stop(paste("missing fields:", paste(missing_fields, collapse = ", ")))
  }
  values <- unlist(counts[required])
  if (!is.numeric(values) || any(is.na(values))) {
    stop("expected, actual and unit_value must be numeric and non-missing")
  }
  if (counts$expected <= 0) {
    stop("expected inventory must be greater than zero")
  }
  if (counts$actual < 0 || counts$unit_value < 0) {
    stop("actual inventory and unit_value must be non-negative")
  }
  invisible(TRUE)
}

shrinkage <- function(counts) {
  validate_counts(counts)
  expected <- counts$expected
  actual <- counts$actual
  unit_value <- counts$unit_value
  missing_items <- expected - actual
  shrinkage_pct <- missing_items / expected
  financial_loss <- missing_items * unit_value
  flagged <- shrinkage_pct > 0.05 || financial_loss > 1000
  list(
    missing_items = missing_items,
    shrinkage_pct = shrinkage_pct,
    financial_loss = financial_loss,
    flagged = flagged
  )
}

format_report <- function(label, result) {
  status <- if (result$flagged) "INVESTIGATE" else "ok"
  pct <- sprintf("%.2f%%", result$shrinkage_pct * 100)
  loss <- sprintf("$%.2f", result$financial_loss)
  sprintf(
    "%-12s missing=%6.1f  shrinkage=%8s  loss=%12s  %s",
    label, result$missing_items, pct, loss, status
  )
}

audit_stores <- function(store_counts) {
  labels <- names(store_counts)
  lines <- character(length(store_counts))
  for (i in seq_along(store_counts)) {
    result <- shrinkage(store_counts[[i]])
    lines[i] <- format_report(labels[i], result)
  }
  lines
}

main <- function() {
  stores <- list(
    Downtown = list(expected = 1200, actual = 1185, unit_value = 4.50),
    Airport = list(expected = 800, actual = 735, unit_value = 12.00),
    Suburbia = list(expected = 500, actual = 480, unit_value = 60.00),
    Warehouse = list(expected = 10000, actual = 9995, unit_value = 0.75)
  )
  report <- audit_stores(stores)
  cat(report, sep = "\n")
  cat("\n")
  flagged_count <- sum(vapply(stores, function(s) shrinkage(s)$flagged, logical(1)))
  cat(sprintf("%d of %d locations flagged for investigation\n",
              flagged_count, length(stores)))
}

main()

