coagulant_dose <- function(turbidity) {
  turbidity * 2.5
}

chlorine_dose <- function(chlorine_demand) {
  chlorine_demand + 1.2
}

validate_water <- function(water) {
  required <- c("volume", "turbidity", "chlorine_demand")
  missing_fields <- setdiff(required, names(water))
  if (length(missing_fields) > 0) {
    stop(paste("missing water fields:", paste(missing_fields, collapse = ", ")))
  }
  values <- unlist(water[required])
  if (any(!is.finite(values)) || any(values < 0)) {
    stop("water volume, turbidity and chlorine demand must be non-negative numbers")
  }
  invisible(TRUE)
}

treatment <- function(water) {
  validate_water(water)
  volume <- water$volume
  turbidity <- water$turbidity
  demand <- water$chlorine_demand

  coag_rate <- coagulant_dose(turbidity)
  total_coagulant <- coag_rate * volume

  chlor_rate <- chlorine_dose(demand)
  total_chlorine <- chlor_rate * volume

  total_mass <- total_coagulant + total_chlorine

  list(coagulant = total_coagulant,
       chlorine = total_chlorine,
       total_mass = total_mass)
}

format_report <- function(label, water, doses) {
  header <- sprintf("%s: %.1f m3 raw water, turbidity %.1f NTU, demand %.1f mg/L",
                    label, water$volume, water$turbidity, water$chlorine_demand)
  report <- c(header,
              sprintf("  coagulant required : %.2f g", doses$coagulant),
              sprintf("  chlorine required  : %.2f g", doses$chlorine),
              sprintf("  total chemical mass: %.2f g", doses$total_mass))
  paste(report, collapse = "\n")
}

main <- function() {
  batches <- list(
    lowland_intake = list(volume = 1200, turbidity = 8.4, chlorine_demand = 2.1),
    reservoir_draw = list(volume = 850, turbidity = 3.2, chlorine_demand = 1.5),
    storm_runoff = list(volume = 2000, turbidity = 25, chlorine_demand = 4.8)
  )

  running_total <- 0
  for (label in names(batches)) {
    water <- batches[[label]]
    doses <- treatment(water)
    running_total <- running_total + doses$total_mass
    cat(format_report(label, water, doses), "\n\n", sep = "")
  }

  kilograms <- running_total / 1000
  cat(sprintf("Combined chemical demand for %d batches: %.3f kg\n",
              length(batches), kilograms))
}

main()

