STANDARD_DEDUCTION <- 12000

bracket_limits <- c(10000, 40000)
bracket_rates <- c(0.10, 0.20, 0.30)

taxable_income <- function(income) {
  if (!is.numeric(income) || length(income) != 1 || is.na(income)) {
    stop("income must be a single numeric value")
  }
  reduced <- income - STANDARD_DEDUCTION
  max(reduced, 0)
}

first_bracket <- function(taxable) {
  base <- min(taxable, bracket_limits[1])
  base * bracket_rates[1]
}

second_bracket <- function(taxable) {
  upper <- min(taxable, bracket_limits[2])
  span <- upper - bracket_limits[1]
  if (span <= 0) {
    return(0)
  }
  span * bracket_rates[2]
}

third_bracket <- function(taxable) {
  span <- taxable - bracket_limits[2]
  if (span <= 0) {
    return(0)
  }
  span * bracket_rates[3]
}

taxation <- function(income) {
  taxable <- taxable_income(income)
  tier_one <- first_bracket(taxable)
  tier_two <- second_bracket(taxable)
  tier_three <- third_bracket(taxable)
  total <- tier_one + tier_two + tier_three
  list(taxable_income = taxable, total_tax = total)
}

format_money <- function(amount) {
  formatC(amount, format = "f", digits = 2, big.mark = ",")
}

tax_report <- function(income) {
  result <- taxation(income)
  gross <- format_money(income)
  taxable <- format_money(result$taxable_income)
  owed <- format_money(result$total_tax)
  effective <- if (income > 0) 100 * result$total_tax / income else 0
  rate <- formatC(effective, format = "f", digits = 1)
  paste0(
    "Gross ", gross,
    " | Taxable ", taxable,
    " | Tax ", owed,
    " | Effective ", rate, "%"
  )
}

main <- function() {
  salaries <- c(8000, 12000, 20000, 45000, 90000, 150000)
  lines <- vapply(salaries, tax_report, character(1))
  cat(lines, sep = "\n")
  cat("\n")
}

main()

