target_levels <- c(nitrogen = 50, phosphorus = 30, potassium = 40)

conversion_rates <- c(urea = 2, phosphate = 1.5, potash = 1.2)

deficit <- function(level, target) {
  gap <- target - level
  max(gap, 0)
}

validate_soil <- function(soil) {
  values <- unlist(soil, use.names = FALSE)
  if (length(values) < 3) {
    stop("soil must supply nitrogen, phosphorus and potassium levels")
  }
  if (!is.numeric(values) || any(is.na(values))) {
    stop("soil nutrient levels must be numeric and non-missing")
  }
  if (any(values < 0)) {
    stop("soil nutrient levels cannot be negative")
  }
  values[1:3]
}

fertilizer <- function(soil) {
  levels <- validate_soil(soil)
  nitrogen <- levels[1]
  phosphorus <- levels[2]
  potassium <- levels[3]

  nitrogen_deficit <- deficit(nitrogen, target_levels[["nitrogen"]])
  phosphorus_deficit <- deficit(phosphorus, target_levels[["phosphorus"]])
  potassium_deficit <- deficit(potassium, target_levels[["potassium"]])

  urea <- nitrogen_deficit * conversion_rates[["urea"]]
  phosphate <- phosphorus_deficit * conversion_rates[["phosphate"]]
  potash <- potassium_deficit * conversion_rates[["potash"]]

  list(urea, phosphate, potash)
}

format_plan <- function(soil, plan) {
  levels <- unlist(soil, use.names = FALSE)
  header <- sprintf("N=%.1f P=%.1f K=%.1f", levels[1], levels[2], levels[3])
  products <- names(conversion_rates)
  amounts <- vapply(seq_along(products), function(i) {
    sprintf("%s: %.2f kg/ha", products[i], plan[[i]])
  }, character(1))
  total <- sum(unlist(plan))
  paste0(header, " -> ", paste(amounts, collapse = ", "),
         sprintf(" (total %.2f kg/ha)", total))
}

main <- function() {
  samples <- list(
    list(20, 10, 15),
    list(50, 35, 40),
    list(0, 0, 0),
    list(45.5, 28, 12.5)
  )
  for (soil in samples) {
    plan <- fertilizer(soil)
    cat(format_plan(soil, plan), "\n")
  }
}

main()

