demand_multiplier <- function(seats_left) {
  multiplier <- 1
  if (seats_left < 50) {
    multiplier <- multiplier * 1.20
  }
  multiplier
}

timing_adjustment <- function(price, days_out) {
  adjusted <- price
  if (days_out < 7) {
    adjusted <- adjusted + 10
  }
  if (days_out > 30) {
    adjusted <- adjusted * 0.85
  }
  adjusted
}

validate_event <- function(event) {
  if (!is.list(event) || length(event) < 3) {
    stop("event must be a list of base price, days to event, remaining seats")
  }
  numeric_fields <- vapply(event[1:3], function(x) is.numeric(x) && length(x) == 1, logical(1))
  if (!all(numeric_fields)) {
    stop("base price, days to event and remaining seats must be single numbers")
  }
  invisible(TRUE)
}

FACILITY_FEE <- 5
TAX_RATE <- 0.08

ticketing <- function(event) {
  validate_event(event)
  base_price <- event[[1]]
  days_to_event <- event[[2]]
  seats_left <- event[[3]]

  demand_price <- base_price * demand_multiplier(seats_left)
  timed_price <- timing_adjustment(demand_price, days_to_event)
  subtotal <- timed_price + FACILITY_FEE
  tax <- subtotal * TAX_RATE
  subtotal + tax
}

format_quote <- function(event) {
  final_price <- ticketing(event)
  label <- sprintf("base $%.2f / %d days out / %d seats",
                   event[[1]], as.integer(event[[2]]), as.integer(event[[3]]))
  sprintf("%-46s -> $%.2f", label, final_price)
}

main <- function() {
  catalogue <- list(
    list(80, 3, 20),
    list(80, 45, 300),
    list(120, 14, 49),
    list(65, 31, 12),
    list(150, 7, 500)
  )
  quotes <- vapply(catalogue, format_quote, character(1))
  cat(quotes, sep = "\n")
  cat("\n")
  average <- mean(vapply(catalogue, ticketing, numeric(1)))
  cat(sprintf("Average dynamic price: $%.2f\n", average))
}

main()

