cover_allowance <- function(cover_type) {
  if (cover_type == 2) {
    allowance <- 0.1
  } else {
    allowance <- 0.05
  }
  allowance
}

validate_book <- function(book) {
  required <- c("pages", "paper_weight", "cover_type")
  missing <- required[!required %in% names(book)]
  if (length(missing) > 0) {
    stop(paste("book is missing fields:", paste(missing, collapse = ", ")))
  }
  pages <- book$pages
  if (!is.numeric(pages) || length(pages) != 1 || is.na(pages) || pages <= 0) {
    stop("pages must be a single positive number")
  }
  weight <- book$paper_weight
  if (!is.numeric(weight) || length(weight) != 1 || is.na(weight) || weight <= 0) {
    stop("paper_weight must be a single positive number")
  }
  cover <- book$cover_type
  if (!is.numeric(cover) || length(cover) != 1 || is.na(cover) || !(cover %in% c(1, 2))) {
    stop("cover_type must be 1 (paperback) or 2 (hardcover)")
  }
  invisible(TRUE)
}

spine <- function(book) {
  validate_book(book)
  pages <- book$pages
  paper_weight <- book$paper_weight
  cover_type <- book$cover_type
  sheets <- pages / 2
