validate_tasks <- function(tasks) {
  if (!is.list(tasks) && !is.numeric(tasks)) {
    stop("tasks must be a list or numeric vector of estimated hours")
  }
  hours <- unlist(tasks, use.names = FALSE)
  if (length(hours) == 0) {
    stop("tasks must contain at least one module estimate")
  }
  if (!is.numeric(hours) || any(is.na(hours))) {
    stop("every module estimate must be a real number of hours")
  }
  if (any(hours < 0)) {
    stop("module estimates cannot be negative")
  }
  hours
}

complexity_multiplier <- function(module_count) {
  extra_modules <- max(0, module_count - 3)
  1 + 0.1 * extra_modules
}

estimation <- function(tasks) {
  hours <- validate_tasks(tasks)
  base_hours <- sum(hours)
  module_count <- length(hours)
  multiplier <- complexity_multiplier(module_count)
  overhead_hours <- 20
  adjusted_hours <- base_hours * multiplier + overhead_hours
  hourly_rate <- 150
  total_cost <- adjusted_hours * hourly_rate
  list(base_hours = base_hours,
       adjusted_hours = adjusted_hours,
       total_cost = total_cost)
}

format_money <- function(amount) {
  paste0("$", formatC(amount, format = "f", digits = 2, big.mark = ","))
}

estimation_report <- function(tasks) {
  estimate <- estimation(tasks)
  labels <- names(tasks)
  if (is.null(labels)) {
    labels <- paste("Module", seq_along(tasks))
  }
  module_rows <- sprintf("  %-20s %8.1f h", labels,
                         unlist(tasks, use.names = FALSE))
  summary_rows <- c(
    sprintf("  %-20s %8.1f h", "Base hours", estimate$base_hours),
    sprintf("  %-20s %8.1f h", "Adjusted hours", estimate$adjusted_hours),
    sprintf("  %-20s %8s", "Total cost", format_money(estimate$total_cost))
  )
  c("Software build estimate", module_rows, strrep("-", 32), summary_rows)
}

main <- function() {
  project <- list(
    "Authentication" = 40,
    "Data layer" = 65.5,
    "REST API" = 80,
    "Web frontend" = 120,
    "Reporting" = 35
  )
  report <- estimation_report(project)
  cat(report, sep = "\n")
  cat("\n")
}

main()

