CONTAINER_OVERHEAD_MB <- 5

validate_video <- function(video) {
  required <- c("duration", "video_bitrate", "audio_bitrate")
  absent <- setdiff(required, names(video))
  if (length(absent) > 0) {
    stop(paste("missing video fields:", paste(absent, collapse = ", ")))
  }
  values <- unlist(video[required])
  if (!is.numeric(values) || any(is.na(values))) {
    stop("duration and bitrates must be numeric and non-missing")
  }
  if (any(values < 0)) {
    stop("duration and bitrates must be non-negative")
  }
  invisible(TRUE)
}

combined_bitrate <- function(video_bitrate, audio_bitrate) {
  video_bitrate + audio_bitrate
}

kilobits_to_megabytes <- function(kilobits) {
  kilobytes <- kilobits / 8
  kilobytes / 1024
}

encoding <- function(video) {
  validate_video(video)
  duration <- video$duration
  video_bitrate <- video$video_bitrate
  audio_bitrate <- video$audio_bitrate
  total_bitrate <- combined_bitrate(video_bitrate, audio_bitrate)
  total_kilobits <- total_bitrate * duration
  size_mb <- kilobits_to_megabytes(total_kilobits)
  size_mb + CONTAINER_OVERHEAD_MB
}

format_duration <- function(seconds) {
  minutes <- floor(seconds / 60)
  remainder <- seconds - minutes * 60
  sprintf("%d:%05.2f", minutes, remainder)
}

encoding_report <- function(name, video) {
  size_mb <- encoding(video)
  sprintf("%-18s %8s  %5d kbps video  %3d kbps audio  -> %8.2f MB",
          name,
          format_duration(video$duration),
          video$video_bitrate,
          video$audio_bitrate,
          size_mb)
}

main <- function() {
  clips <- list(
    "trailer" = list(duration = 90, video_bitrate = 4500, audio_bitrate = 128),
    "episode" = list(duration = 1320, video_bitrate = 2800, audio_bitrate = 192),
    "feature film" = list(duration = 7260, video_bitrate = 6000, audio_bitrate = 384),
    "silent loop" = list(duration = 12.5, video_bitrate = 1200, audio_bitrate = 0)
  )
  report <- vapply(names(clips),
                   function(name) encoding_report(name, clips[[name]]),
                   character(1))
  cat(report, sep = "\n")
  cat("\n")
  total <- sum(vapply(clips, encoding, numeric(1)))
  cat(sprintf("Total estimated output: %.2f MB\n", total))
}

main()

