validate_weather <- function(weather) {
  temps <- unlist(weather, use.names = FALSE)
  if (length(temps) == 0L) {
    stop("weather must contain at least one daily peak temperature")
  }
  if (!is.numeric(temps) || anyNA(temps)) {
    stop("weather must contain only numeric, non-missing temperatures")
  }
  temps
}

average_temperature <- function(temps) {
  sum(temps) / length(temps)
}

peak_temperature <- function(temps) {
  max(temps)
}

count_hot_days <- function(temps, threshold = 85) {
  sum(temps > threshold)
}

watering_duration <- function(hot_days, avg_temp) {
  base <- 20
  duration <- base + 5 * hot_days
  if (avg_temp > 75) {
    duration <- duration * 1.2
  }
  duration
}

watering <- function(weather) {
  temps <- validate_weather(weather)
  avg_temp <- average_temperature(temps)
  hottest <- peak_temperature(temps)
  hot_days <- count_hot_days(temps)
  minutes <- watering_duration(hot_days, avg_temp)
  list(
    average_temperature = avg_temp,
    peak_temperature = hottest,
    hot_days = hot_days,
    watering_minutes = minutes
  )
}

format_report <- function(label, plan) {
  heat_note <- if (plan$peak_temperature > 100) " (severe heatwave)" else ""
  lines <- c(
    sprintf("%s", label),
    sprintf("  average temperature : %.1f", plan$average_temperature),
    sprintf("  peak temperature    : %.1f%s", plan$peak_temperature, heat_note),
    sprintf("  days above 85       : %d", plan$hot_days),
    sprintf("  watering duration   : %.1f minutes", plan$watering_minutes)
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  mild_week <- list(68, 71, 70, 74, 69, 72, 73)
  warm_week <- list(80, 86, 88, 79, 91, 84, 87)
  scorching_week <- list(95, 101, 104, 99, 97, 106, 98)
  weeks <- list(
    "Mild week" = mild_week,
    "Warm week" = warm_week,
    "Scorching week" = scorching_week
  )
  for (label in names(weeks)) {
    plan <- watering(weeks[[label]])
    cat(format_report(label, plan), "\n\n", sep = "")
  }
}

main()

