snowfall <- function(daily, melt, sublimation) {
  if (length(daily) == 0) {
    stop("daily must contain at least one day of snowfall")
  }
  if (any(is.na(daily)) || any(daily < 0)) {
    stop("daily snowfall amounts must be non-negative numbers")
  }
  if (melt < 0 || sublimation < 0) {
    stop("melt and sublimation rates must be non-negative")
  }
  loss <- melt + sublimation
  depth <- 0
  total <- 0
  peak <- 0
  for (snow in daily) {
    depth <- depth + snow - loss
    if (depth < 0) {
      depth <- 0
    }
    if (depth > peak) {
      peak <- depth
    }
    total <- total + depth
  }
  average <- total / length(daily)
  list(final = depth, average = average, maximum = peak)
}

parse_amounts <- function(text) {
  pieces <- strsplit(text, ",", fixed = TRUE)[[1]]
  trimmed <- trimws(pieces)
  kept <- trimmed[nzchar(trimmed)]
  values <- suppressWarnings(as.numeric(kept))
  if (any(is.na(values))) {
    stop(paste("cannot read snowfall record:", text))
  }
  values
}

format_report <- function(label, result) {
  numbers <- c(result$final, result$average, result$maximum)
  shown <- formatC(numbers, format = "f", digits = 2)
  paste0(label, ": final = ", shown[1],
         ", average = ", shown[2],
         ", maximum = ", shown[3])
}

season_table <- function(records, melt, sublimation) {
  lines <- character(0)
  for (label in names(records)) {
    daily <- parse_amounts(records[[label]])
    result <- snowfall(daily, melt, sublimation)
    lines <- c(lines, format_report(label, result))
  }
  lines
}

main <- function() {
  example <- snowfall(c(5, 10, 0, 2), 2, 1)
  cat(format_report("Example", example), "\n")
  records <- list(
    "December" = "5, 10, 0, 2, 8, 0, 0, 14",
    "January" = "0, 0, 3, 3, 3, 20, 1, 0",
    "February" = "12, 0, 0, 0, 0, 6, 9, 2"
  )
  melt <- 2.5
  sublimation <- 0.5
  report <- season_table(records, melt, sublimation)
  cat(report, sep = "\n")
  cat("\n")
  peaks <- vapply(names(records), function(label) {
    snowfall(parse_amounts(records[[label]]), melt, sublimation)$maximum
  }, numeric(1))
  deepest <- names(peaks)[which.max(peaks)]
  cat("Deepest snowpack occurred in", deepest, "\n")
}

main()

