validate_trips <- function(distances, densities, capacity) {
  if (length(distances) != length(densities)) {
    stop("distances and densities must have the same length")
  }
  if (length(capacity) != 1 || is.na(capacity) || capacity < 0) {
    stop("capacity must be a single non-negative number")
  }
  bad_distance <- any(is.na(distances) | distances < 0)
  if (bad_distance) {
    stop("distances must be non-negative numbers")
  }
  bad_density <- any(is.na(densities) | densities < 0)
  if (bad_density) {
    stop("densities must be non-negative numbers")
  }
  invisible(TRUE)
}

forage <- function(distances, densities, capacity) {
  validate_trips(distances, densities, capacity)
  total_nectar <- 0
  longest_flight <- 0
  successful_trips <- 0
  for (i in seq_along(distances)) {
    distance <- distances[i]
    collected <- densities[i] * capacity
    energy_spent <- distance * 2
    net_nectar <- collected - energy_spent
    if (net_nectar < 0) {
      net_nectar <- 0
    }
    total_nectar <- total_nectar + net_nectar
    if (distance > longest_flight) {
      longest_flight <- distance
    }
    if (net_nectar > 10) {
      successful_trips <- successful_trips + 1
    }
  }
  list(total_nectar, longest_flight, successful_trips)
}

format_report <- function(label, result) {
  total <- result[[1]]
  longest <- result[[2]]
  successes <- result[[3]]
  lines <- c(
    sprintf("%s", label),
    sprintf("  total nectar      : %.2f", total),
    sprintf("  longest flight    : %.2f", longest),
    sprintf("  successful trips  : %d", successes)
  )
