orbit <- function(altitudes, drags, limit) {
  final_altitudes <- list()
  statuses <- list()
  for (i in seq_along(altitudes)) {
    altitude <- altitudes[[i]]
    drag <- drags[[i]]
    status <- 1
    for (day in 1:30) {
      altitude <- altitude - drag / altitude
      if (altitude < limit) {
        status <- 0
        break
      }
    }
    final_altitudes[[i]] <- altitude
    statuses[[i]] <- status
  }
  list(final_altitudes, statuses)
}

validate_fleet <- function(altitudes, drags, limit) {
  if (length(altitudes) != length(drags)) {
    stop("altitudes and drags must describe the same number of satellites")
  }
  if (!is.numeric(limit) || length(limit) != 1 || limit <= 0) {
    stop("limit must be a single positive number")
  }
  start <- unlist(altitudes)
  bad_altitudes <- which(!is.finite(start) | start <= limit)
  if (length(bad_altitudes) > 0) {
    stop(paste("starting altitude must exceed the limit for satellite(s):",
               paste(bad_altitudes, collapse = ", ")))
  }
  coefficients <- unlist(drags)
  bad_drags <- which(!is.finite(coefficients) | coefficients < 0)
  if (length(bad_drags) > 0) {
    stop(paste("drag coefficient must be non-negative for satellite(s):",
               paste(bad_drags, collapse = ", ")))
  }
  invisible(TRUE)
}

format_report <- function(result, satellite_ids = NULL) {
  finals <- unlist(result[[1]])
  flags <- unlist(result[[2]])
  tags <- satellite_ids
  if (is.null(tags)) {
    tags <- paste0("SAT-", seq_along(finals))
  }
  verdicts <- ifelse(flags == 1, "in orbit", "re-entered")
  rows <- sprintf("%-8s final altitude %8.2f km  (%s)",
                  tags, finals, verdicts)
  paste(rows, collapse = "\n")
}

survival_rate <- function(result) {
  flags <- unlist(result[[2]])
  sum(flags) / length(flags)
}

main <- function() {
  altitudes <- c(200, 180, 300, 160)
  drags <- c(1000, 1500, 800, 400)
  limit <- 150
  validate_fleet(altitudes, drags, limit)
  result <- orbit(altitudes, drags, limit)
  fleet_ids <- c("ALPHA", "BETA", "GAMMA", "DELTA")
  cat(format_report(result, fleet_ids), "\n")
  rate <- survival_rate(result)
  cat(sprintf("Survival rate after 30 days: %.0f%%\n", 100 * rate))
}

main()

