process_tank <- function(feed, plants, temperature) {
  ammonia <- feed * 0.8
  nitrite <- ammonia / 2
  ammonia <- ammonia - nitrite
  nitrate <- nitrite / 2
  nitrite <- nitrite - nitrate
  uptake <- plants * 0.2
  nitrate <- max(0, nitrate - uptake)
  list(ammonia = ammonia, nitrite = nitrite, nitrate = nitrate,
       temperature = temperature)
}

check_inputs <- function(feeds, plants, temperatures) {
  sizes <- c(length(feeds), length(plants), length(temperatures))
  if (length(unique(sizes)) != 1L) {
    stop("feeds, plants and temperatures must describe the same tanks")
  }
  if (any(feeds < 0) || any(plants < 0)) {
    stop("feeds and plant counts cannot be negative")
  }
  sizes[1]
}

aquaponics <- function(feeds, plants, temperatures) {
  n <- check_inputs(feeds, plants, temperatures)
  ammonia_levels <- list()
  nitrate_levels <- list()
  danger <- 0
  for (i in seq_len(n)) {
    tank <- process_tank(feeds[[i]], plants[[i]], temperatures[[i]])
    if (tank$ammonia > 5) {
      danger <- 1
    }
    ammonia_levels[[i]] <- tank$ammonia
    nitrate_levels[[i]] <- tank$nitrate
  }
  list(ammonia_levels, nitrate_levels, danger)
}

format_report <- function(result, temperatures) {
  ammonia_levels <- result[[1]]
  nitrate_levels <- result[[2]]
  lines <- character(length(ammonia_levels))
  for (i in seq_along(ammonia_levels)) {
    lines[i] <- sprintf("Tank %d: %.1f C, ammonia %.2f mg/L, nitrate %.2f mg/L",
                        i, temperatures[[i]], ammonia_levels[[i]],
                        nitrate_levels[[i]])
  }
  status <- if (result[[3]] == 1) "DANGER: ammonia above 5 mg/L" else "System stable"
  c(lines, status)
}

main <- function() {
  single <- aquaponics(c(10), c(5), c(20))
  cat(sprintf("[[%g], [%g], %g]\n", single[[1]][[1]], single[[2]][[1]], single[[3]]))

  feeds <- c(10, 25, 4)
  plants <- c(5, 12, 30)
  temperatures <- c(20, 24.5, 18)
  farm <- aquaponics(feeds, plants, temperatures)
  report <- format_report(farm, temperatures)
  cat(report, sep = "\n")
  cat("\n")
}

main()

