gymnast <- function(scores, difficulties, deductions) {
  final_scores <- numeric(0)
  total <- 0
  perfect <- 0
  for (i in seq_along(scores)) {
    base <- scores[i] * difficulties[i]
    penalty <- deductions[i] * 0.5
    final <- base - penalty
    if (final < 0) {
      final <- 0
    }
    total <- total + final
    if (final > 15 && deductions[i] == 0) {
      perfect <- perfect + 1
    }
    final_scores <- c(final_scores, final)
  }
  list(final_scores, total, perfect)
}

validate_routines <- function(scores, difficulties, deductions) {
  sizes <- c(length(scores), length(difficulties), length(deductions))
  if (length(unique(sizes)) != 1) {
    stop("scores, difficulties and deductions must have equal length")
  }
  values <- c(scores, difficulties, deductions)
  if (any(!is.finite(values))) {
    stop("all routine values must be finite numbers")
  }
  if (any(values < 0)) {
    stop("routine values must not be negative")
  }
  invisible(TRUE)
}

format_report <- function(gymnasts, result) {
  final_scores <- result[[1]]
  total <- result[[2]]
  perfect <- result[[3]]
  rows <- character(0)
  for (i in seq_along(final_scores)) {
    entry <- sprintf("%-10s %6.2f", gymnasts[i], final_scores[i])
    rows <- c(rows, entry)
  }
  average <- if (length(final_scores) > 0) total / length(final_scores) else 0
  summary_rows <- c(
    sprintf("Total      %6.2f", total),
    sprintf("Average    %6.2f", average),
    sprintf("Perfect routines: %d", perfect)
  )
  paste(c(rows, summary_rows), collapse = "\n")
}

main <- function() {
  gymnasts <- c("Ana", "Beatriz", "Chloe", "Dasha")
  scores <- c(8.5, 9.2, 7.8, 9.9)
  difficulties <- c(1.5, 1.8, 2.0, 1.7)
  deductions <- c(1, 0, 3, 0)
  validate_routines(scores, difficulties, deductions)
  result <- gymnast(scores, difficulties, deductions)
  cat(format_report(gymnasts, result), "\n")
}

main()

