validate_inputs <- function(trees, ages, frosts) {
  section_counts <- c(length(trees), length(ages), length(frosts))
  if (length(unique(section_counts)) != 1L) {
    stop("trees, ages and frosts must describe the same number of sections")
  }
  if (section_counts[1] == 0L) {
    stop("at least one orchard section is required")
  }
  if (any(trees < 0) || any(ages < 0) || any(frosts < 0)) {
    stop("trees, ages and frost days must all be non-negative")
  }
  invisible(TRUE)
}

section_yield <- function(tree_count, age, frost_days) {
  base_yield <- tree_count * 50
  if (age > 8) {
    base_yield <- base_yield + tree_count * 20
  }
  frost_penalty <- frost_days * 0.05
  actual_yield <- base_yield * (1 - frost_penalty)
  lost_apples <- base_yield - actual_yield
  list(harvested = actual_yield, lost = lost_apples)
}

orchard <- function(trees, ages, frosts) {
  validate_inputs(trees, ages, frosts)
  total_harvested <- 0
  total_lost <- 0
  mature_trees <- 0
  for (i in seq_along(trees)) {
    section <- section_yield(trees[i], ages[i], frosts[i])
    total_harvested <- total_harvested + section$harvested
    total_lost <- total_lost + section$lost
    if (ages[i] > 3) {
      mature_trees <- mature_trees + trees[i]
    }
  }
  c(total_harvested, total_lost, mature_trees)
}

format_report <- function(result) {
  captions <- c("Harvested apples", "Lost apples", "Mature trees")
  values <- format(round(result, 2), big.mark = ",", trim = TRUE)
  paste0(captions, ": ", values, collapse = "\n")
}

main <- function() {
  single_result <- orchard(c(10), c(5), c(2))
  cat(format_report(single_result), "\n\n")

  farm_trees <- c(40, 25, 60, 15)
  farm_ages <- c(2, 6, 12, 9)
  farm_frosts <- c(0, 3, 5, 10)
  farm_result <- orchard(farm_trees, farm_ages, farm_frosts)
  cat(format_report(farm_result), "\n\n")

  loss_share <- farm_result[2] / (farm_result[1] + farm_result[2]) * 100
  cat(sprintf("Share of the crop lost to frost: %.1f%%\n", loss_share))
  per_mature <- farm_result[1] / farm_result[3]
  cat(sprintf("Apples harvested per mature tree: %.1f\n", per_mature))
}

main()

