mining = function(weights, grades, recoveries) {
  n = length(weights)
  if (length(grades) != n || length(recoveries) != n) {
    stop("weights, grades and recoveries must have the same length")
  }
  total_pure_metal = 0
  total_waste = 0
  profitable_batches = 0
  for (i in seq_len(n)) {
    theoretical_metal = weights[i] * grades[i]
    extracted_metal = theoretical_metal * recoveries[i]
    waste_material = weights[i] - extracted_metal
    total_pure_metal = total_pure_metal + extracted_metal
    total_waste = total_waste + waste_material
    if (extracted_metal > 50) {
      profitable_batches = profitable_batches + 1
    }
  }
  list(total_pure_metal = total_pure_metal,
       total_waste = total_waste,
       profitable_batches = profitable_batches)
}

validate_batches = function(weights, grades, recoveries) {
  if (any(weights < 0)) {
    stop("batch weights must be non-negative")
  }
  bad_grades = grades < 0 | grades > 1
  if (any(bad_grades)) {
    stop("ore grades must lie between 0 and 1")
  }
  bad_recoveries = recoveries < 0 | recoveries > 1
  if (any(bad_recoveries)) {
    stop("recovery percentages must lie between 0 and 1")
  }
  invisible(TRUE)
}

batch_table = function(weights, grades, recoveries) {
  theoretical = weights * grades
  extracted = theoretical * recoveries
  data.frame(batch = seq_along(weights),
             weight = weights,
             grade = grades,
             recovery = recoveries,
             theoretical_metal = round(theoretical, 3),
             extracted_metal = round(extracted, 3),
             waste = round(weights - extracted, 3))
}

report = function(weights, grades, recoveries) {
  validate_batches(weights, grades, recoveries)
  details = batch_table(weights, grades, recoveries)
  print(details, row.names = FALSE)
  summary_stats = mining(weights, grades, recoveries)
  yield_pct = 100 * summary_stats$total_pure_metal / sum(weights)
  cat(sprintf("Total pure metal: %.3f units\n", summary_stats$total_pure_metal))
  cat(sprintf("Total waste: %.3f units\n", summary_stats$total_waste))
  cat(sprintf("Profitable batches: %d of %d\n",
              summary_stats$profitable_batches, length(weights)))
  cat(sprintf("Overall metal yield: %.2f%%\n", yield_pct))
  invisible(summary_stats)
}

main = function() {
  single_weight = c(1000)
  single_grade = c(0.1)
  single_recovery = c(0.8)
  report(single_weight, single_grade, single_recovery)
  cat("\n")
  mine_weights = c(1200, 450, 2000, 800)
  mine_grades = c(0.05, 0.12, 0.03, 0.09)
  mine_recoveries = c(0.9, 0.75, 0.85, 0.6)
  report(mine_weights, mine_grades, mine_recoveries)
}

main()

