telescope <- function(diameters, wavelengths, exposures) {
  collected_signal <- 0
  resolutions <- list()
  viable <- 0
  for (i in seq_along(diameters)) {
    diameter <- diameters[i]
    wavelength <- wavelengths[i]
    exposure <- exposures[i]
    resolution <- 1.22 * wavelength / diameter
    resolutions[[length(resolutions) + 1]] <- resolution
    gathering_power <- diameter^2
    total_signal <- gathering_power * exposure
    collected_signal <- collected_signal + total_signal
    if (resolution < 2 && total_signal > 50) {
      viable <- viable + 1
    }
  }
  list(resolutions = resolutions,
       collected_signal = collected_signal,
       viable = viable)
}

validate_setups <- function(diameters, wavelengths, exposures) {
  lengths_seen <- c(length(diameters), length(wavelengths), length(exposures))
  if (length(unique(lengths_seen)) != 1) {
    stop("diameters, wavelengths and exposures must have equal length")
  }
  if (any(diameters <= 0)) {
    stop("mirror diameters must be strictly positive")
  }
  if (any(wavelengths <= 0) || any(exposures < 0)) {
    stop("wavelengths must be positive and exposures non-negative")
  }
  invisible(TRUE)
}

format_report <- function(diameters, wavelengths, exposures, result) {
  rows <- character(0)
  for (i in seq_along(diameters)) {
    resolution <- round(result$resolutions[[i]], 3)
    signal <- diameters[i]^2 * exposures[i]
    line <- sprintf("D=%.2f m  lambda=%.3f um  t=%.1f s  res=%.3f  signal=%.1f",
                    diameters[i], wavelengths[i], exposures[i], resolution, signal)
    rows <- c(rows, line)
  }
  summary_line <- sprintf("total signal=%.1f  viable setups=%d",
                          result$collected_signal, result$viable)
  paste(c(rows, summary_line), collapse = "\n")
}

evaluate_survey <- function(diameters, wavelengths, exposures) {
  validate_setups(diameters, wavelengths, exposures)
  outcome <- telescope(diameters, wavelengths, exposures)
  cat(format_report(diameters, wavelengths, exposures, outcome), "\n")
  outcome
}

main <- function() {
  demo <- evaluate_survey(c(2), c(0.5), c(20))
  cat("resolutions:", unlist(demo$resolutions), "\n\n")
  mirrors <- c(1.0, 2.4, 8.2, 0.6)
  bands <- c(0.55, 0.8, 2.2, 0.44)
  times <- c(30, 120, 600, 45)
  survey <- evaluate_survey(mirrors, bands, times)
  best <- which.min(unlist(survey$resolutions))
  cat(sprintf("sharpest setup: mirror %.1f m at %.2f um (%.3f arcsec)\n",
              mirrors[best], bands[best], survey$resolutions[[best]]))
}

main()

