wildfire <- function(winds, dryness, slopes) {
  n <- length(winds)
  if (length(dryness) != n || length(slopes) != n) {
    stop("winds, dryness and slopes must have the same length")
  }
  total_area <- 100
  total_danger <- 0
  spread_rates <- list()
  for (i in seq_len(n)) {
    base_factor <- winds[i] * dryness[i]
    terrain_multiplier <- 1 + slopes[i] * 0.05
    spread_rate <- base_factor * terrain_multiplier
    spread_rates[[length(spread_rates) + 1]] <- spread_rate
    total_area <- total_area + spread_rate
    daily_danger <- spread_rate / 10
    total_danger <- total_danger + daily_danger
  }
  list(total_area, total_danger, spread_rates)
}

danger_label <- function(score) {
  if (score < 5) {
    label <- "low"
  } else if (score < 15) {
    label <- "moderate"
  } else if (score < 40) {
    label <- "high"
  } else {
    label <- "extreme"
  }
  label
}

format_report <- function(result) {
  total_area <- result[[1]]
  total_danger <- result[[2]]
  rates <- unlist(result[[3]])
  header <- sprintf("Days simulated: %d", length(rates))
  area_line <- sprintf("Total burned area: %.2f hectares", total_area)
  danger_line <- sprintf("Total danger score: %.2f (%s)", total_danger,
                         danger_label(total_danger))
  peak_line <- if (length(rates) > 0) {
    peak_day <- which.max(rates)
    sprintf("Peak spread on day %d: %.2f", peak_day, rates[peak_day])
  } else {
    "No daily data supplied"
  }
  rate_line <- paste("Daily spread rates:",
                     paste(sprintf("%.2f", rates), collapse = ", "))
  paste(header, area_line, danger_line, peak_line, rate_line, sep = "\n")
}

main <- function() {
  demo <- wildfire(c(20), c(0.8), c(10))
  cat(format_report(demo), "\n\n")

  winds <- c(12, 25, 30, 18, 40)
  dryness <- c(0.5, 0.7, 0.9, 0.6, 0.95)
  slopes <- c(5, 12, 20, 8, 30)
  week <- wildfire(winds, dryness, slopes)
  cat(format_report(week), "\n\n")

  growth <- week[[1]] - 100
  cat(sprintf("Fire grew by %.2f hectares over %d days.\n",
              growth, length(winds)))
}

main()

