elevator <- function(floors, weights, brakes) {
  total_consumed <- 0
  total_recovered <- 0
  trip_energies <- list()
  for (i in seq_along(floors)) {
    base_energy <- floors[i] * 15
    weight_penalty <- weights[i] * 0.1
    gross_energy <- base_energy + weight_penalty
    if (brakes[i] == 1) {
      recovered <- gross_energy * 0.25
    } else {
      recovered <- 0
    }
    net_energy <- gross_energy - recovered
    trip_energies[[length(trip_energies) + 1]] <- net_energy
    total_consumed <- total_consumed + net_energy
    total_recovered <- total_recovered + recovered
  }
  list(total_consumed, total_recovered, trip_energies)
}

validate_trips <- function(floors, weights, brakes) {
  lengths_seen <- c(length(floors), length(weights), length(brakes))
  if (length(unique(lengths_seen)) != 1) {
    stop("floors, weights and brakes must have the same length")
  }
  if (any(floors < 0) || any(weights < 0)) {
    stop("floors travelled and passenger weights must be non-negative")
  }
  bad_flags <- setdiff(unique(brakes), c(0, 1))
  if (length(bad_flags) > 0) {
    stop("braking flags must be 0 or 1")
  }
  invisible(TRUE)
}

format_report <- function(result) {
  consumed <- result[[1]]
  recovered <- result[[2]]
  trips <- unlist(result[[3]])
  gross <- consumed + recovered
  trip_lines <- sprintf("  trip %d: %.2f kWh", seq_along(trips), trips)
  header <- sprintf("%d trip(s), gross demand %.2f kWh", length(trips), gross)
  efficiency <- if (gross > 0) 100 * recovered / gross else 0
  summary_lines <- c(
    sprintf("net consumed:  %.2f kWh", consumed),
    sprintf("recovered:     %.2f kWh", recovered),
    sprintf("recovery rate: %.1f%%", efficiency)
  )
  paste(c(header, trip_lines, summary_lines), collapse = "\n")
}

run_building <- function(floors, weights, brakes) {
  validate_trips(floors, weights, brakes)
  result <- elevator(floors, weights, brakes)
  cat(format_report(result), "\n\n")
  result
}

main <- function() {
  single_trip <- run_building(c(10), c(200), c(1))
  cat("example output:", single_trip[[1]], single_trip[[2]],
      unlist(single_trip[[3]]), "\n\n")

  day_floors <- c(10, 4, 7, 12, 3)
  day_weights <- c(200, 450, 80, 610, 150)
  day_brakes <- c(1, 0, 1, 1, 0)
  day_result <- run_building(day_floors, day_weights, day_brakes)

  busiest <- which.max(unlist(day_result[[3]]))
  cat(sprintf("most expensive trip: #%d (%d floors, %d kg)\n",
              busiest, day_floors[busiest], day_weights[busiest]))
}

main()

