laundry <- function(loads, hardness, soils) {
  n <- length(loads)
  if (length(hardness) != n || length(soils) != n) {
    stop("loads, hardness and soils must have equal lengths")
  }
  remaining <- 1000
  total_used <- 0
  dosages <- list()
  for (i in seq_len(n)) {
    dosage <- loads[i] * 20
    if (hardness[i] > 120) {
      dosage <- dosage + 15
    }
    if (soils[i] > 5) {
      dosage <- dosage + 30
    }
    dosages[[length(dosages) + 1]] <- dosage
    remaining <- remaining - dosage
    total_used <- total_used + dosage
    if (remaining < 0) {
      remaining <- 0
    }
  }
  list(total_used, remaining, dosages)
}

validate_inputs <- function(loads, hardness, soils) {
  numeric_ok <- is.numeric(loads) && is.numeric(hardness) && is.numeric(soils)
  if (!numeric_ok) {
    stop("all inputs must be numeric vectors")
  }
  if (any(loads < 0) || any(hardness < 0) || any(soils < 0)) {
    stop("inputs must not contain negative values")
  }
  invisible(TRUE)
}

format_report <- function(result) {
  total_used <- result[[1]]
  remaining <- result[[2]]
  dosages <- unlist(result[[3]])
  lines <- character(0)
  for (i in seq_along(dosages)) {
    entry <- sprintf("  wash %d: %g units", i, dosages[i])
    lines <- c(lines, entry)
  }
  header <- sprintf("Washes: %d", length(dosages))
  footer <- sprintf("Total used: %g units, remaining: %g units", total_used, remaining)
  paste(c(header, lines, footer), collapse = "\n")
}

run_laundromat <- function(loads, hardness, soils) {
  validate_inputs(loads, hardness, soils)
  result <- laundry(loads, hardness, soils)
  cat(format_report(result), "\n", sep = "")
  result
}

main <- function() {
  single <- run_laundromat(c(5), c(150), c(2))
  cat("Returned dosages:", unlist(single[[3]]), "\n")
  day_loads <- c(8, 12, 6, 20, 15)
  day_hardness <- c(90, 130, 121, 60, 200)
  day_soils <- c(3, 7, 5, 6, 9)
  shift <- run_laundromat(day_loads, day_hardness, day_soils)
  if (shift[[2]] == 0) {
    cat("Detergent exhausted during the shift; restock required.\n")
  } else {
    cat("Detergent left for the next shift:", shift[[2]], "units\n")
  }
}

main()

