STANDARD_GRAVITY <- 9.81
SPECIFIC_IMPULSE <- 320
THRUST_NEWTONS <- 450000
FUEL_LOAD <- 20000

exhaust_velocity <- function(isp = SPECIFIC_IMPULSE, g0 = STANDARD_GRAVITY) {
  isp * g0
}

fuel_consumed <- function(duration, ve) {
  flow_rate <- THRUST_NEWTONS / ve
  flow_rate * duration
}

validate_inputs <- function(durations, mass) {
  flat <- unlist(durations)
  if (length(flat) == 0) {
    stop("at least one burn duration is required")
  }
  if (!is.numeric(flat) || any(is.na(flat)) || any(flat < 0)) {
    stop("burn durations must be non-negative numbers")
  }
  if (!is.numeric(mass) || length(mass) != 1 || is.na(mass) || mass <= 0) {
    stop("dry mass must be a single positive number")
  }
  flat
}

