pure_water_density <- function(temperature) {
  baseline <- 999.8
  linear_term <- temperature * 0.06
  quadratic_term <- temperature^2 * 0.008
  baseline + linear_term - quadratic_term
}

base_density <- function(temperature, salinity) {
  water <- pure_water_density(temperature)
  salinity_contribution <- salinity * 0.8
  water + salinity_contribution
}

secant_bulk_modulus <- function(temperature, salinity, pressure) {
  modulus <- 19652 + temperature * 148 - temperature^2 * 2
  modulus <- modulus + 54 * salinity
  modulus + 3.2 * pressure
}

validate_inputs <- function(temperature, salinity, pressure) {
  values <- c(temperature = temperature, salinity = salinity, pressure = pressure)
  if (any(!is.finite(values))) {
    stop("temperature, salinity and pressure must be finite numbers")
  }
  if (salinity < 0) {
    stop("salinity cannot be negative")
  }
  if (pressure < 0) {
    stop("pressure cannot be negative")
  }
  invisible(values)
}

density <- function(temperature, salinity, pressure) {
  validate_inputs(temperature, salinity, pressure)
  rho_base <- base_density(temperature, salinity)
  modulus <- secant_bulk_modulus(temperature, salinity, pressure)
  compressibility <- 1 - pressure / modulus
  final_density <- rho_base / compressibility
  specific_volume <- 1 / final_density
  list(density = final_density, specific_volume = specific_volume)
}

format_report <- function(temperature, salinity, pressure, metrics) {
  header <- sprintf(
    "T = %.1f C, S = %.1f ppt, P = %.1f dbar",
    temperature, salinity, pressure
  )
  density_line <- sprintf("  density        : %.4f kg/m^3", metrics$density)
  volume_line <- sprintf("  specific volume: %.8f m^3/kg", metrics$specific_volume)
  paste(header, density_line, volume_line, sep = "\n")
}

main <- function() {
  temperature <- 15
  salinity <- 35
  pressure <- 1000
  metrics <- density(temperature, salinity, pressure)
  report <- format_report(temperature, salinity, pressure, metrics)
  cat(report, "\n", sep = "")
}

main()

