eccentric_anomaly <- function(mean_rad, eccentricity) {
  ecc_anom <- mean_rad
  for (i in seq_len(5)) {
    numerator <- ecc_anom - eccentricity * sin(ecc_anom) - mean_rad
    denominator <- 1 - eccentricity * cos(ecc_anom)
    ecc_anom <- ecc_anom - numerator / denominator
  }
  ecc_anom
}

true_anomaly <- function(ecc_anom, eccentricity) {
  ratio <- sqrt((1 + eccentricity) / (1 - eccentricity))
  2 * atan(ratio * tan(ecc_anom / 2))
}

radial_distance <- function(ecc_anom, eccentricity, semi_major) {
  semi_major * (1 - eccentricity * cos(ecc_anom))
}

check_inputs <- function(anomaly, eccentricity, semi_major) {
  if (!is.numeric(anomaly) || length(anomaly) != 1 || !is.finite(anomaly)) {
    stop("anomaly must be a single finite number of degrees")
  }
  if (!is.numeric(eccentricity) || length(eccentricity) != 1 ||
      eccentricity < 0 || eccentricity >= 1) {
    stop("eccentricity must be a single value in [0, 1)")
  }
  if (!is.numeric(semi_major) || length(semi_major) != 1 || semi_major <= 0) {
    stop("semi major axis must be a single positive number of AU")
  }
  invisible(TRUE)
}

orbit <- function(anomaly, eccentricity, axis) {
  check_inputs(anomaly, eccentricity, axis)
  mean_rad <- anomaly * pi / 180
  ecc_anom <- eccentric_anomaly(mean_rad, eccentricity)
  nu <- true_anomaly(ecc_anom, eccentricity)
  distance <- radial_distance(ecc_anom, eccentricity, axis)
  x <- distance * cos(nu)
  y <- distance * sin(nu)
  list(true_anomaly = nu, distance = distance, x = x, y = y)
}

format_orbit <- function(state) {
  degrees <- state$true_anomaly * 180 / pi
  report <- c(
    sprintf("true anomaly : %.6f rad (%.4f deg)", state$true_anomaly, degrees),
    sprintf("distance     : %.6f AU", state$distance),
    sprintf("x coordinate : %.6f AU", state$x),
    sprintf("y coordinate : %.6f AU", state$y)
  )
  paste(report, collapse = "\n")
}

main <- function() {
  state <- orbit(30, 0.1, 1.5)
  cat(format_orbit(state), "\n", sep = "")
  mean_anomalies <- seq(0, 300, by = 60)
  for (m in mean_anomalies) {
    sample_state <- orbit(m, 0.1, 1.5)
    cat(sprintf("M = %6.1f deg -> r = %.6f AU, (x, y) = (%.6f, %.6f)\n",
                m, sample_state$distance, sample_state$x, sample_state$y))
  }
  invisible(state)
}

main()

