glide <- function(altitude, speed, distance) {
  if (!is.numeric(altitude) || !is.numeric(speed) || !is.numeric(distance)) {
    stop("altitude, speed and distance must be numeric")
  }
  if (speed <= 0 || distance <= 0) {
    stop("speed and distance must be positive")
  }
  altitude_nm <- altitude / 6076
  angle_rad <- atan(altitude_nm / distance)
  angle_deg <- angle_rad * 180 / pi
  descent_rate <- speed * 101.26 * sin(angle_rad)
  time_to_touchdown <- distance / speed * 60
  check_altitude <- altitude / 2
  check_distance <- distance / 2
  list(angle_deg = angle_deg,
       descent_rate = descent_rate,
       time_to_touchdown = time_to_touchdown,
       check_altitude = check_altitude,
       check_distance = check_distance)
}

format_descent <- function(params) {
  lines <- c(
    sprintf("Flight path angle   : %.3f degrees", params$angle_deg),
    sprintf("Required descent rate: %.1f ft/min", params$descent_rate),
    sprintf("Time to touchdown    : %.2f minutes", params$time_to_touchdown),
    sprintf("Halfway check        : %.0f ft at %.1f nm",
            params$check_altitude, params$check_distance)
  )
  paste(lines, collapse = "\n")
}

descent_profile <- function(altitude, speed, distance, steps = 3) {
  fractions <- seq(1, 0, length.out = steps + 1)
  rows <- lapply(fractions, function(f) {
    leg_distance <- distance * f
    leg_altitude <- altitude * f
    if (leg_distance == 0) {
      leg_angle <- 0
    } else {
      leg <- glide(leg_altitude, speed, leg_distance)
      leg_angle <- leg$angle_deg
    }
    data.frame(distance_nm = leg_distance,
               altitude_ft = leg_altitude,
               angle_deg = leg_angle)
  })
  do.call(rbind, rows)
}

report_approach <- function(altitude, speed, distance) {
  params <- glide(altitude, speed, distance)
  header <- sprintf("Approach from %.0f ft at %.0f kt, %.0f nm out",
                    altitude, speed, distance)
  profile <- descent_profile(altitude, speed, distance)
  cat(header, "\n")
  cat(format_descent(params), "\n\n")
  print(profile, row.names = FALSE)
  invisible(params)
}

main <- function() {
  altitude <- 10000
  speed <- 120
  distance <- 30
  report_approach(altitude, speed, distance)
}

main()

