loom_speed <- function(weft) {
  speed <- 500 - weft * 2
  speed
}

effective_minutes <- function(hours) {
  total_minutes <- hours * 60
  downtime <- total_minutes * 0.15
  total_minutes - downtime
}

fabric_yards <- function(picks, weft) {
  length_inches <- picks / weft
  length_inches / 36
}

warp_yarn_yards <- function(yards, warp, width = 60) {
  base_yarn <- yards * warp * width
  crimp <- base_yarn * 0.10
  base_yarn + crimp
}

validate_inputs <- function(hours, warp, weft) {
  numbers <- c(hours, warp, weft)
  if (any(!is.finite(numbers)) || any(numbers <= 0)) {
    stop("hours, warp and weft must be positive finite numbers")
  }
  speed <- loom_speed(weft)
  if (speed <= 0) {
    stop("weft density is too high for a viable loom speed")
  }
  invisible(TRUE)
}

weave <- function(hours, warp, weft) {
  validate_inputs(hours, warp, weft)
  speed <- loom_speed(weft)
  running_minutes <- effective_minutes(hours)
  total_picks <- speed * running_minutes
  yards <- fabric_yards(total_picks, weft)
  warp_length <- warp_yarn_yards(yards, warp)
  list(
    effective_minutes = running_minutes,
    fabric_yards = yards,
    warp_yarn_yards = warp_length
  )
}

format_report <- function(metrics) {
  labels <- c(
    effective_minutes = "Effective running minutes",
    fabric_yards = "Fabric woven (yards)",
    warp_yarn_yards = "Warp yarn with crimp (yards)"
  )
  values <- formatC(unlist(metrics[names(labels)]), format = "f", digits = 2, big.mark = ",")
  paste0(labels, ": ", values)
}

main <- function() {
  hours <- 8
  warp <- 80
  weft <- 60
  metrics <- weave(hours, warp, weft)
  header <- sprintf("Loom run: %g h, %g ends/in warp, %g picks/in weft", hours, warp, weft)
  cat(header, "\n")
  cat(format_report(metrics), sep = "\n")
  cat("\n")
  invisible(metrics)
}

main()

