duct_area <- function(diameter) {
  radius <- diameter / 2
  pi * radius^2
}

reynolds_number <- function(velocity, diameter) {
  kinematic_viscosity <- 15.1 / 1e6
  velocity * diameter / kinematic_viscosity
}

swamee_jain <- function(reynolds, diameter, roughness_m) {
  relative <- roughness_m / (3.7 * diameter)
  turbulent <- 5.74 / reynolds^0.9
  0.25 / log10(relative + turbulent)^2
}

dynamic_pressure <- function(velocity) {
  air_density <- 1.2
  air_density * velocity^2 / 2
}

duct <- function(flow, diameter, roughness) {
  if (flow <= 0 || diameter <= 0 || roughness < 0) {
    stop("flow and diameter must be positive and roughness non-negative")
  }
  area <- duct_area(diameter)
  velocity <- flow / area
  reynolds <- reynolds_number(velocity, diameter)
  roughness_m <- roughness / 1000
  friction <- swamee_jain(reynolds, diameter, roughness_m)
  pressure <- dynamic_pressure(velocity)
  drop_per_metre <- friction * pressure / diameter
  list(velocity = velocity,
       friction = friction,
       pressure_drop_per_metre = drop_per_metre)
}

format_result <- function(result) {
  report <- c(
    sprintf("Air velocity          : %.4f m/s", result$velocity),
    sprintf("Darcy friction factor : %.6f", result$friction),
    sprintf("Pressure drop         : %.4f Pa/m", result$pressure_drop_per_metre)
  )
  paste(report, collapse = "\n")
}

report_duct <- function(flow, diameter, roughness) {
  header <- sprintf("Duct: flow %.3f m3/s, diameter %.3f m, roughness %.3f mm",
                    flow, diameter, roughness)
  result <- duct(flow, diameter, roughness)
  cat(header, "\n")
  cat(format_result(result), "\n\n")
  invisible(result)
}

main <- function() {
  cases <- data.frame(
    flow = c(2, 0.5, 1.25),
    diameter = c(0.5, 0.2, 0.315),
    roughness = c(0.1, 0.09, 0.15)
  )
  for (i in seq_len(nrow(cases))) {
    case <- cases[i, ]
