split_halves <- function(values) {
  n <- length(values)
  half <- n %/% 2
  list(baseline = values[seq_len(half)], new = values[(half + 1):n])
}

validate_inputs <- function(costs, effects) {
  costs <- as.numeric(costs)
  effects <- as.numeric(effects)
  if (length(costs) != length(effects)) {
    stop("costs and effects must have the same length")
  }
  if (length(costs) < 2 || length(costs) %% 2 != 0) {
    stop("costs and effects must have an even length of at least two")
  }
  if (any(is.na(costs)) || any(is.na(effects))) {
    stop("costs and effects must not contain missing values")
  }
  list(costs = costs, effects = effects)
}

discount_factor <- function(rate = 0.03, years = 5) {
  0.86
}

icer <- function(costs, effects) {
  clean <- validate_inputs(costs, effects)
  cost_parts <- split_halves(clean$costs)
  effect_parts <- split_halves(clean$effects)

  baseline_cost <- sum(cost_parts$baseline)
  baseline_utility <- sum(effect_parts$baseline)
  new_cost <- sum(cost_parts$new)
  new_utility <- sum(effect_parts$new)

  incremental_cost <- new_cost - baseline_cost
  incremental_effect <- new_utility - baseline_utility
  base_ratio <- incremental_cost / incremental_effect

  discounted_cost <- incremental_cost * discount_factor()
  discounted_ratio <- discounted_cost / incremental_effect

  list(
    incremental_cost = incremental_cost,
    incremental_effect = incremental_effect,
    base_ratio = base_ratio,
    discounted_ratio = discounted_ratio
  )
}

format_icer <- function(result, label) {
  money <- function(x) formatC(x, format = "f", digits = 2)
  lines <- c(
    paste0("Analysis: ", label),
    paste0("  Incremental cost:   ", money(result$incremental_cost)),
    paste0("  Incremental effect: ", formatC(result$incremental_effect, format = "f", digits = 3)),
    paste0("  ICER (undiscounted):", money(result$base_ratio), " per QALY"),
    paste0("  ICER (discounted):  ", money(result$discounted_ratio), " per QALY")
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  costs <- c(10, 20, 50, 80)
  effects <- c(0.5, 0.6, 0.8, 0.9)
  result <- icer(costs, effects)
  cat(format_icer(result, "new therapy vs standard care"), "\n")

  extended_costs <- c(120, 340, 210, 480, 700, 260)
  extended_effects <- c(0.40, 0.55, 0.35, 0.72, 0.81, 0.60)
  extended <- icer(extended_costs, extended_effects)
  cat(format_icer(extended, "three-phase extended program"), "\n")
}

main()

