wavelength_km <- function(frequency) {
  speed_of_light <- 3e5
  speed_of_light / (frequency * 1e9)
}

fspl_db <- function(distance, wavelength) {
  ratio <- 4 * pi * distance / wavelength
  20 * log10(ratio)
}

noise_power_dbw <- function() {
  boltzmann <- 1.38e-23
  system_temperature <- 290
  bandwidth <- 20e6
  10 * log10(boltzmann * system_temperature * bandwidth)
}

validate_inputs <- function(frequency, distance, power) {
  values <- c(frequency = frequency, distance = distance, power = power)
  if (any(!is.finite(values))) {
    stop("frequency, distance and power must be finite numbers")
  }
  nonpositive <- names(values)[values <= 0]
  if (length(nonpositive) > 0) {
    stop(paste("must be strictly positive:", paste(nonpositive, collapse = ", ")))
  }
  invisible(TRUE)
}

link <- function(frequency, distance, power) {
  validate_inputs(frequency, distance, power)
  transmit_power_dbw <- 10 * log10(power)
  transmit_gain <- 35
  receive_gain <- 40
  wavelength <- wavelength_km(frequency)
  path_loss <- fspl_db(distance, wavelength)
  other_losses <- 3
  received_power <- transmit_power_dbw + transmit_gain + receive_gain -
    path_loss - other_losses
  noise_power <- noise_power_dbw()
  snr <- received_power - noise_power
  list(received_power = received_power, snr = snr)
}

format_link_report <- function(frequency, distance, power, budget) {
  header <- sprintf("Link at %.3g GHz over %.0f km with %.3g W transmit power",
                    frequency, distance, power)
  power_line <- sprintf("  Received power : %.2f dBW", budget$received_power)
  snr_line <- sprintf("  Signal/noise   : %.2f dB", budget$snr)
  quality <- if (budget$snr >= 10) "usable margin" else "marginal margin"
  verdict <- sprintf("  Assessment     : %s", quality)
  paste(header, power_line, snr_line, verdict, sep = "\n")
}

main <- function() {
  frequency <- 12
  distance <- 36000
  power <- 50
  budget <- link(frequency, distance, power)
  cat(format_link_report(frequency, distance, power, budget), "\n", sep = "")
}

main()

