MU_MAX <- 0.4
KS <- 2.0
YIELD <- 0.5

specific_growth_rate <- function(substrate) {
  MU_MAX * substrate / (KS + substrate)
}

validate_inputs <- function(time, cells, substrate) {
  if (!is.numeric(time) || length(time) != 1 || is.na(time) || time < 0) {
    stop("time must be a single non-negative number of hours")
  }
  if (!is.numeric(cells) || length(cells) != 1 || is.na(cells) || cells <= 0) {
    stop("initial cell concentration must be a single positive number")
  }
  if (!is.numeric(substrate) || length(substrate) != 1 || is.na(substrate) || substrate < 0) {
    stop("initial substrate concentration must be a single non-negative number")
  }
  invisible(TRUE)
}

ferment <- function(time, cells, substrate) {
  validate_inputs(time, cells, substrate)
  hours <- floor(time)
  current_cells <- cells
  current_substrate <- substrate
  peak_cells <- cells
  mu <- 0
  for (hour in seq_len(hours)) {
    mu <- specific_growth_rate(current_substrate)
    cell_increase <- mu * current_cells
    current_cells <- current_cells + cell_increase
    consumed <- cell_increase / YIELD
    current_substrate <- current_substrate - consumed
    if (current_substrate < 0) {
      current_substrate <- 0
      peak_cells <- max(peak_cells, current_cells)
      break
    }
    peak_cells <- max(peak_cells, current_cells)
  }
  list(cells = current_cells,
       substrate = current_substrate,
       growth_rate = mu,
       peak_cells = peak_cells)
}

format_state <- function(state) {
  cells_line <- sprintf("Final cell concentration : %.4f g/L", state$cells)
  substrate_line <- sprintf("Final substrate         : %.4f g/L", state$substrate)
  rate_line <- sprintf("Last specific growth rate: %.4f 1/h", state$growth_rate)
  peak_line <- sprintf("Peak cell concentration : %.4f g/L", state$peak_cells)
  paste(cells_line, substrate_line, rate_line, peak_line, sep = "\n")
}

run_batch_report <- function(time, cells, substrate) {
  header <- sprintf("Batch run: %g h, X0 = %g g/L, S0 = %g g/L", time, cells, substrate)
  state <- ferment(time, cells, substrate)
  cat(header, "\n", sep = "")
  cat(format_state(state), "\n\n", sep = "")
  invisible(state)
}

main <- function() {
  run_batch_report(10, 0.1, 20)
  starved <- run_batch_report(24, 0.5, 4)
  if (starved$substrate == 0) {
    cat("Substrate exhausted before the end of the run; growth halted.\n")
  }
}

main()

