TRANSDUCER_DIAMETER <- 0.02

validate_inputs <- function(time, velocity, frequency) {
  if (!is.numeric(time) || !is.numeric(velocity) || !is.numeric(frequency)) {
    stop("time, velocity and frequency must be numeric")
  }
  if (time <= 0 || velocity <= 0 || frequency <= 0) {
    stop("time, velocity and frequency must be strictly positive")
  }
  invisible(TRUE)
}

wavelength <- function(velocity, frequency) {
  frequency_hz <- frequency * 1e6
  velocity / frequency_hz
}

near_field_distance <- function(diameter, lambda) {
  (diameter^2) / (4 * lambda)
}

beam_spread_angle <- function(diameter, lambda) {
  ratio <- 1.2 * lambda / diameter
  if (ratio > 1) {
    stop("beam spread undefined: wavelength too large for this transducer")
  }
  asin(ratio)
}

beam_diameter_at_depth <- function(depth, diameter, near_field, spread_angle) {
  spread <- depth * 2 * tan(spread_angle / 2)
  if (depth < near_field) {
    spread <- diameter
  }
  spread
}

echo <- function(time, velocity, frequency) {
  validate_inputs(time, velocity, frequency)
  time_seconds <- time / 1e6
  total_distance <- time_seconds * velocity
  flaw_depth <- total_distance / 2
  lambda <- wavelength(velocity, frequency)
  diameter <- TRANSDUCER_DIAMETER
  near_field <- near_field_distance(diameter, lambda)
  spread_angle <- beam_spread_angle(diameter, lambda)
  beam_diameter <- beam_diameter_at_depth(flaw_depth, diameter, near_field, spread_angle)
  list(flaw_depth = flaw_depth,
       near_field_distance = near_field,
       beam_diameter = beam_diameter)
}

format_report <- function(result) {
  lines <- c(
    sprintf("Flaw depth            : %.5f m", result$flaw_depth),
    sprintf("Near field distance   : %.5f m", result$near_field_distance),
    sprintf("Beam diameter at flaw : %.5f m", result$beam_diameter)
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  echo_time <- 50
  sound_velocity <- 5900
  transducer_frequency <- 5
  result <- echo(echo_time, sound_velocity, transducer_frequency)
  cat(sprintf("Echo time %.1f us, velocity %.0f m/s, frequency %.1f MHz\n",
              echo_time, sound_velocity, transducer_frequency))
  cat(format_report(result), "\n", sep = "")
  zone <- if (result$flaw_depth < result$near_field_distance) "near field" else "far field"
  cat(sprintf("The flaw lies in the %s of the beam.\n", zone))
}

main()

