T1_MS <- 800
T2_MS <- 100
DENSITY_CALIBRATION <- 100
RECEIVER_GAIN <- 10
BASELINE_NOISE <- 0.5

validate_inputs <- function(repetition, echo, density) {
  values <- c(repetition = repetition, echo = echo, density = density)
  if (any(!is.finite(values))) {
    stop("repetition, echo and density must be finite numeric values")
  }
  if (any(values < 0)) {
    stop("repetition, echo and density must be non-negative")
  }
  invisible(TRUE)
}

longitudinal_recovery <- function(repetition) {
  ratio <- repetition / T1_MS
  1 - exp(-ratio)
}

transverse_decay <- function(echo) {
  ratio <- echo / T2_MS
  exp(-ratio)
}

signal <- function(repetition, echo, density) {
  validate_inputs(repetition, echo, density)
  recovery <- longitudinal_recovery(repetition)
  decay <- transverse_decay(echo)
  adjusted_density <- density * DENSITY_CALIBRATION
  base_signal <- adjusted_density * recovery * decay
  amplified <- base_signal * RECEIVER_GAIN
  intensity <- amplified + BASELINE_NOISE
  contrast <- recovery / decay
  sar <- repetition^2 / contrast
  list(intensity = intensity, contrast = contrast, sar = sar)
}

format_report <- function(repetition, echo, density, result) {
  header <- sprintf("Spin echo: TR = %g ms, TE = %g ms, density = %g",
                    repetition, echo, density)
  lines <- c(
    header,
    sprintf("  signal intensity        : %.6f", result$intensity),
    sprintf("  contrast weighting      : %.6f", result$contrast),
    sprintf("  specific absorption rate: %.6f", result$sar)
  )
  paste(lines, collapse = "\n")
}

run_sequence <- function(repetition, echo, density) {
  result <- signal(repetition, echo, density)
  report <- format_report(repetition, echo, density, result)
  cat(report, "\n", sep = "")
  invisible(result)
}

main <- function() {
  repetition <- 500
  echo <- 20
  density <- 0.8
  run_sequence(repetition, echo, density)
}

main()

