focal_to_meters <- function(focal) {
  if (!is.numeric(focal) || length(focal) != 1 || is.na(focal) || focal <= 0) {
    stop("focal length must be a single positive number in millimetres")
  }
  focal / 1000
}

relative_height <- function(height, elevation) {
  if (!is.numeric(height) || !is.numeric(elevation)) {
    stop("height and elevation must be numeric")
  }
  h_rel <- height - elevation
  if (is.na(h_rel) || h_rel <= 0) {
    stop("flying height must be above the terrain elevation")
  }
  h_rel
}

ground_coverage <- function(scale_factor) {
  sensor_width <- 0.23
  sensor_height <- 0.23
  ground_width <- sensor_width * scale_factor
  ground_height <- sensor_height * scale_factor
  list(width = ground_width, height = ground_height)
}

footprint_area_km2 <- function(coverage) {
  area_m2 <- coverage$width * coverage$height
  area_m2 / 1e6
}

forward_spacing <- function(coverage) {
  coverage$height * 0.4
}

scale <- function(height, focal, elevation) {
  if (missing(focal) || missing(elevation)) {
    return(base::scale(height))
  }
  f <- focal_to_meters(focal)
  h_rel <- relative_height(height, elevation)
  scale_factor <- h_rel / f
  photo_scale <- 1 / scale_factor
  coverage <- ground_coverage(scale_factor)
  area <- footprint_area_km2(coverage)
  spacing <- forward_spacing(coverage)
  list(scale_factor = scale_factor,
       photo_scale = photo_scale,
       footprint_area = area,
       forward_spacing = spacing)
}

report <- function(params) {
  lines <- c(
    sprintf("Scale factor        : %.0f (1:%s)", params$scale_factor,
            format(round(params$scale_factor), big.mark = ",")),
    sprintf("Photo scale         : %.8f", params$photo_scale),
    sprintf("Footprint area      : %.4f km^2", params$footprint_area),
    sprintf("Forward spacing     : %.2f m", params$forward_spacing)
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  flying_height <- 3000
  focal_length <- 150
  terrain_elevation <- 500
  params <- scale(flying_height, focal_length, terrain_elevation)
  cat(report(params), "\n")
}

main()

