atmospheric_head <- function(elevation) {
  sea_level_head <- 10.33
  elevation_penalty <- elevation * 0.0012
  sea_level_head - elevation_penalty
}

vapor_pressure_head <- function(temperature) {
  reduced_temperature <- temperature / 100
  5.2 * reduced_temperature^2
}

static_suction_head <- function() {
  source_depth <- 2.5
  -source_depth
}

total_dynamic_suction_head <- function(static_head, friction) {
  static_head + friction
}

validate_inputs <- function(elevation, temperature, friction) {
  if (!is.numeric(elevation) || !is.numeric(temperature) || !is.numeric(friction)) {
    stop("elevation, temperature and friction must be numeric")
  }
  if (elevation < 0) {
    stop("elevation above sea level cannot be negative")
  }
  if (temperature < 0 || temperature > 100) {
    stop("water temperature must lie between 0 and 100 Celsius")
  }
  if (friction < 0) {
    stop("friction loss in the suction pipe cannot be negative")
  }
  invisible(TRUE)
}

npsh <- function(elevation, temperature, friction) {
  validate_inputs(elevation, temperature, friction)
  atmos_head <- atmospheric_head(elevation)
  vapor_head <- vapor_pressure_head(temperature)
  static_head <- static_suction_head()
  dynamic_head <- total_dynamic_suction_head(static_head, friction)
  raw_available <- atmos_head - vapor_head - dynamic_head
  safety_margin <- 0.5
  available_head <- raw_available - safety_margin
  critical_parameter <- available_head / dynamic_head
  list(
    atmospheric_head = atmos_head,
    available_head = available_head,
    critical_parameter = critical_parameter
  )
}

format_report <- function(metrics) {
  atmos_line <- sprintf("Atmospheric pressure head : %.3f m of water", metrics$atmospheric_head)
  available_line <- sprintf("Available suction head    : %.3f m of water", metrics$available_head)
  critical_line <- sprintf("Critical cavitation param : %.3f", metrics$critical_parameter)
  paste(atmos_line, available_line, critical_line, sep = "\n")
}

main <- function() {
  elevation <- 500
  temperature <- 25
  friction <- 1.2
  metrics <- npsh(elevation, temperature, friction)
  header <- sprintf(
    "Pump at %.0f m elevation, water at %.0f C, friction loss %.1f m",
    elevation, temperature, friction
  )
  cat(header, "\n", sep = "")
  cat(format_report(metrics), "\n", sep = "")
}

main()

