INLET_PRESSURE <- 101
REFERENCE_TEMPERATURE <- 298

validate_inputs <- function(flow, speed, pressure) {
  values <- c(flow = flow, speed = speed, pressure = pressure)
  if (any(!is.finite(values))) {
    stop("flow, speed and pressure must be finite numeric values")
  }
  if (any(values <= 0)) {
    stop("flow, speed and pressure must be strictly positive")
  }
  invisible(TRUE)
}

corrected_value <- function(quantity) {
  quantity / sqrt(REFERENCE_TEMPERATURE)
}

surge_margin_flow <- function(corrected_speed) {
  0.5 + 0.0015 * corrected_speed
}

surge_pressure_limit <- function(corrected_flow) {
  1.0 + 2.5 * corrected_flow
}

classify_operating_point <- function(flow_deviation, pressure_deviation) {
  if (flow_deviation <= 0 && pressure_deviation >= 0) {
    status <- "SURGE"
  } else if (flow_deviation <= 0 || pressure_deviation >= 0) {
    status <- "NEAR SURGE"
  } else {
    status <- "STABLE"
  }
  status
}

surge <- function(flow, speed, pressure) {
  validate_inputs(flow, speed, pressure)
  pressure_ratio <- pressure / INLET_PRESSURE
  corrected_speed <- corrected_value(speed)
  margin_flow <- surge_margin_flow(corrected_speed)
  corrected_flow <- corrected_value(flow)
  flow_deviation <- corrected_flow - margin_flow
  pressure_limit <- surge_pressure_limit(corrected_flow)
  pressure_deviation <- pressure_ratio - pressure_limit
  safety_metric <- (flow_deviation / margin_flow) * 100
  list(
    corrected_flow = corrected_flow,
    pressure_ratio = pressure_ratio,
    safety_margin_percent = safety_metric,
    status = classify_operating_point(flow_deviation, pressure_deviation)
  )
}

format_report <- function(state) {
  lines <- c(
    sprintf("Corrected mass flow : %.6f kg/s/sqrt(K)", state$corrected_flow),
    sprintf("Pressure ratio      : %.6f", state$pressure_ratio),
    sprintf("Safety margin       : %.2f %%", state$safety_margin_percent),
    sprintf("Operating point     : %s", state$status)
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  operating_points <- list(
    c(flow = 2, speed = 10000, pressure = 300),
    c(flow = 6, speed = 8000, pressure = 450)
  )
  for (point in operating_points) {
    state <- surge(point[["flow"]], point[["speed"]], point[["pressure"]])
    header <- sprintf("flow=%.1f kg/s, speed=%.0f rpm, pressure=%.0f kPa",
                      point[["flow"]], point[["speed"]], point[["pressure"]])
    cat(header, "\n", sep = "")
    cat(format_report(state), "\n\n", sep = "")
  }
}

main()

