fiber_loss <- function(distance) {
  loss_per_km <- 0.25
  distance * loss_per_km
}

splice_loss <- function(splices) {
  loss_per_splice <- 0.1
  splices * loss_per_splice
}

connector_loss <- function() {
  loss_per_connector <- 0.75
  2 * loss_per_connector
}

validate_inputs <- function(power, distance, splices) {
  if (!is.numeric(power) || length(power) != 1 || is.na(power)) {
    stop("power must be a single numeric value in dBm")
  }
  if (!is.numeric(distance) || length(distance) != 1 || is.na(distance) || distance < 0) {
    stop("distance must be a single non-negative numeric value in km")
  }
  if (!is.numeric(splices) || length(splices) != 1 || is.na(splices) || splices < 0) {
    stop("splices must be a single non-negative count")
  }
  invisible(TRUE)
}

budget <- function(power, distance, splices) {
  validate_inputs(power, distance, splices)
  sensitivity <- -28
  repair_margin <- 3
  attenuation <- fiber_loss(distance)
  splices_total <- splice_loss(splices)
  connectors <- connector_loss()
  total_loss <- attenuation + splices_total + connectors + repair_margin
  received_power <- power - total_loss
  power_margin <- received_power - sensitivity
  viable <- if (power_margin > 0) 1 else 0
  list(
    total_loss = total_loss,
    received_power = received_power,
    power_margin = power_margin,
    viable = viable
  )
}

format_report <- function(result, power, distance, splices) {
  verdict <- if (result$viable == 1) "LINK VIABLE" else "LINK NOT VIABLE"
  header <- sprintf("Tx %.2f dBm over %.1f km with %d splices", power, distance, splices)
  lines <- c(
    header,
    sprintf("Total system loss : %.2f dB", result$total_loss),
    sprintf("Received power    : %.2f dBm", result$received_power),
    sprintf("Power margin      : %.2f dB", result$power_margin),
    sprintf("Verdict           : %s (%d)", verdict, result$viable)
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  tx_power <- 0
  span_km <- 40
  splice_count <- 4
  analysis <- budget(tx_power, span_km, splice_count)
  cat(format_report(analysis, tx_power, span_km, splice_count), "\n")

  long_haul <- budget(3, 90, 12)
  cat(format_report(long_haul, 3, 90, 12), "\n")
}

main()

