    stop("radius, speed and area must be numeric")
  }
  if (radius <= HUB_RADIUS) {
    stop("tip radius must exceed the hub radius of 0.4 m")
  }
  if (area <= 0) {
    stop("root cross sectional area must be positive")
  }
  invisible(TRUE)
}

stress = function(radius, speed, area) {
  validate_inputs(radius, speed, area)
  omega = angular_velocity(speed)
  r_cm = centre_of_mass_radius(radius)
  mass = blade_mass(radius, area)
  force = mass * r_cm * omega^2
  stress_pa = force / area
  stress_mpa = stress_pa / 1e6
  safety = YIELD_STRENGTH_MPA / stress_mpa
  list(
    angular_velocity = omega,
    centrifugal_force = force,
    stress_mpa = stress_mpa,
    safety_factor = safety
  )
}

format_report = function(result) {
  rows = c(
    sprintf("Angular velocity : %.2f rad/s", result$angular_velocity),
    sprintf("Centrifugal force: %.1f N", result$centrifugal_force),
    sprintf("Root stress      : %.2f MPa", result$stress_mpa),
    sprintf("Safety factor    : %.3f", result$safety_factor)
  )
  paste(rows, collapse = "\n")
}

main = function() {
  tip_radius = 0.8
  rpm = 3000
  root_area = 0.005
  metrics = stress(tip_radius, rpm, root_area)
  cat(sprintf("Blade: tip radius %.2f m, %.0f rpm, root area %.4f m^2\n",
              tip_radius, rpm, root_area))
  cat(format_report(metrics), "\n", sep = "")
  verdict = if (metrics$safety_factor >= 1) "acceptable" else "overstressed"
  cat("Assessment: ", verdict, "\n", sep = "")
}

main()

