validate_parameters <- function(parameters) {
  if (!is.numeric(parameters) || length(parameters) != 5L) {
    stop("parameters must be a numeric vector of length five")
  }
  if (any(!is.finite(parameters))) {
    stop("parameters must all be finite numbers")
  }
  named <- parameters
  names(named) <- c("spot", "strike", "rate", "volatility", "maturity")
  if (named[["spot"]] <= 0 || named[["strike"]] <= 0) {
    stop("spot and strike prices must be positive")
  }
  if (named[["volatility"]] <= 0 || named[["maturity"]] <= 0) {
    stop("volatility and time to maturity must be positive")
  }
  named
}

black_scholes_terms <- function(p) {
  spread <- p[["volatility"]] * sqrt(p[["maturity"]])
  moneyness <- log(p[["spot"]] / p[["strike"]])
  drift <- (p[["rate"]] + 0.5 * p[["volatility"]]^2) * p[["maturity"]]
  d1 <- (moneyness + drift) / spread
  d2 <- d1 - spread
  c(d1 = d1, d2 = d2)
}

erf_approximation <- function(x) {
  direction <- ifelse(x < 0, -1, 1)
  z <- abs(x)
  u <- 1 / (1 + 0.3275911 * z)
  series <- ((((1.061405429 * u - 1.453152027) * u) + 1.421413741) * u - 0.284496736) * u + 0.254829592
  direction * (1 - series * u * exp(-z * z))
}

normal_cdf <- function(x) {
  0.5 * (1 + erf_approximation(x / sqrt(2)))
}

price <- function(parameters) {
  p <- validate_parameters(parameters)
  d <- black_scholes_terms(p)
  discount <- p[["strike"]] * exp(-p[["rate"]] * p[["maturity"]])
  nd1 <- normal_cdf(d[["d1"]])
  nd2 <- normal_cdf(d[["d2"]])
  call <- p[["spot"]] * nd1 - discount * nd2
  put <- discount * (1 - nd2) - p[["spot"]] * (1 - nd1)
  list(call = round(call, 2), put = round(put, 2))
}

format_quote <- function(parameters, prices) {
  inputs <- sprintf("S=%g K=%g r=%g sigma=%g T=%g",
                    parameters[1], parameters[2], parameters[3],
                    parameters[4], parameters[5])
  outputs <- sprintf("call = %.2f, put = %.2f", prices$call, prices$put)
  paste(inputs, outputs, sep = " -> ")
}

main <- function() {
  scenarios <- list(c(100, 100, 0.05, 0.2, 1),
                    c(60, 65, 0.08, 0.3, 0.25),
                    c(120, 100, 0.03, 0.45, 2))
  for (scenario in scenarios) {
    quoted <- price(scenario)
    cat(format_quote(scenario, quoted), "\n")
  }
  invisible(NULL)
}

main()

