coupon_payment <- function(bond) {
  bond$face_value * bond$coupon_rate
}

cash_flows <- function(bond) {
  coupon <- coupon_payment(bond)
  n <- bond$years_to_maturity
  flows <- rep(coupon, n)
  flows[n] <- flows[n] + bond$face_value
  flows
}

present_values <- function(flows, rate) {
  times <- seq_along(flows)
  flows / (1 + rate) ^ times
}

price_at_yield <- function(bond, rate) {
  sum(present_values(cash_flows(bond), rate))
}

find_yield <- function(bond, tolerance = 1e-10, max_iter = 200L) {
  low <- -0.9999
  high <- 5
  guess <- (low + high) / 2
  for (i in seq_len(max_iter)) {
    guess <- (low + high) / 2
    difference <- price_at_yield(bond, guess) - bond$market_price
    if (abs(difference) < tolerance) break
    if (difference > 0) {
      low <- guess
    } else {
      high <- guess
    }
  }
  guess
}

macaulay_duration <- function(bond, rate) {
  flows <- cash_flows(bond)
  discounted <- present_values(flows, rate)
  weighted <- seq_along(flows) * discounted
  sum(weighted) / bond$market_price
}

validate_bond <- function(bond) {
  required <- c("face_value", "coupon_rate", "years_to_maturity", "market_price")
  missing_fields <- setdiff(required, names(bond))
  if (length(missing_fields) > 0) {
    stop(paste("missing bond fields:", paste(missing_fields, collapse = ", ")))
  }
  if (bond$years_to_maturity < 1 || bond$years_to_maturity != round(bond$years_to_maturity)) {
    stop("years_to_maturity must be a whole number of at least 1")
  }
  if (bond$market_price <= 0 || bond$face_value <= 0) {
    stop("face_value and market_price must be positive")
  }
  invisible(TRUE)
}

evaluate <- function(bond) {
  validate_bond(bond)
  ytm <- find_yield(bond)
  duration <- macaulay_duration(bond, ytm)
  c(yield = ytm, duration = duration)
}

report <- function(bond) {
  result <- evaluate(bond)
  coupon <- coupon_payment(bond)
  lines <- c(
    sprintf("Face value: %.2f, market price: %.2f", bond$face_value, bond$market_price),
    sprintf("Annual coupon payment: %.2f", coupon),
    sprintf("Yield to maturity: %.4f%%", 100 * result[["yield"]]),
    sprintf("Macaulay duration: %.4f years", result[["duration"]])
  )
  cat(lines, sep = "\n")
  cat("\n")
  invisible(result)
}

sample_bond <- list(face_value = 1000, coupon_rate = 0.05,
                    years_to_maturity = 10, market_price = 920)
discount_bond <- list(face_value = 500, coupon_rate = 0.08,
                      years_to_maturity = 5, market_price = 530)
report(sample_bond)
report(discount_bond)

