expected_score <- function(rating_self, rating_opponent) {
  exponent <- (rating_opponent - rating_self) / 400
  1 / (1 + 10^exponent)
}

rating_change <- function(actual, expected, k_factor = 32) {
  k_factor * (actual - expected)
}

validate_results <- function(results) {
  if (!is.matrix(results) || !is.numeric(results)) {
    stop("results must be a numeric matrix")
  }
  if (ncol(results) != 3L) {
    stop("results must have three columns: rating one, rating two, win indicator")
  }
  outcomes <- results[, 3]
  if (any(is.na(outcomes)) || any(!outcomes %in% c(0, 0.5, 1))) {
    stop("win indicator must be 0, 0.5 or 1")
  }
  invisible(TRUE)
}

update <- function(results) {
  validate_results(results)
  updated <- matrix(0, nrow = nrow(results), ncol = 2L,
                    dimnames = list(NULL, c("player_one", "player_two")))
  for (row in seq_len(nrow(results))) {
    rating_one <- results[row, 1]
    rating_two <- results[row, 2]
    score_one <- results[row, 3]
    score_two <- 1 - score_one
    expected_one <- expected_score(rating_one, rating_two)
    expected_two <- expected_score(rating_two, rating_one)
    delta_one <- rating_change(score_one, expected_one)
    delta_two <- rating_change(score_two, expected_two)
    updated[row, ] <- c(rating_one + delta_one, rating_two + delta_two)
  }
  updated
}

format_report <- function(results, updated) {
  labels <- ifelse(results[, 3] == 1, "player one wins",
                   ifelse(results[, 3] == 0, "player two wins", "draw"))
  lines <- character(nrow(results))
  for (row in seq_len(nrow(results))) {
    before <- sprintf("%.0f vs %.0f", results[row, 1], results[row, 2])
    after <- sprintf("%.2f vs %.2f", updated[row, 1], updated[row, 2])
    lines[row] <- sprintf("%-15s %-12s -> %s", before, labels[row], after)
  }
  lines
}

main <- function() {
  matches <- matrix(c(
    1200, 1200, 1,
    1500, 1300, 0,
    1000, 1400, 0.5,
    2400, 2000, 1
  ), ncol = 3L, byrow = TRUE)
  updated <- update(matches)
  report <- format_report(matches, updated)
  cat(report, sep = "\n")
  cat("\n")
  invisible(updated)
}

main()

