number_words <- c(
  one = 1, two = 2, three = 3, four = 4, five = 5, six = 6, seven = 7,
  eight = 8, nine = 9, ten = 10, eleven = 11, twelve = 12, thirteen = 13,
  fourteen = 14, fifteen = 15, sixteen = 16, seventeen = 17,
  eighteen = 18, nineteen = 19, twenty = 20
)

multipliers <- c(single = 1, double = 2, treble = 3, triple = 3)

normalize_throw <- function(text) {
  cleaned <- tolower(trimws(text))
  tokens <- strsplit(cleaned, "[[:space:]]+")[[1]]
  tokens[nzchar(tokens)]
}

bull_value <- function(qualifier) {
  if (qualifier %in% c("inner", "double")) {
    50
  } else if (qualifier == "outer") {
    25
  } else {
    stop(sprintf("unknown bull qualifier: %s", qualifier))
  }
}

throw_value <- function(text) {
  tokens <- normalize_throw(text)
  if (length(tokens) == 0 || length(tokens) > 2) {
    stop(sprintf("cannot parse throw: '%s'", text))
  }
  if (tokens[length(tokens)] == "bull") {
    qualifier <- if (length(tokens) == 2) tokens[1] else "inner"
    return(bull_value(qualifier))
  }
  base_word <- tokens[length(tokens)]
  if (!base_word %in% names(number_words)) {
    stop(sprintf("unknown segment: %s", base_word))
  }
  factor_word <- if (length(tokens) == 2) tokens[1] else "single"
  if (!factor_word %in% names(multipliers)) {
    stop(sprintf("unknown multiplier: %s", factor_word))
  }
  multipliers[[factor_word]] * number_words[[base_word]]
}

score <- function(throws) {
  remaining <- 501
  valid <- 0
  still_playing <- TRUE
  for (throw in throws) {
    if (still_playing) {
      candidate <- remaining - throw_value(throw)
      if (candidate == 1 || candidate < 0) {
        still_playing <- FALSE
      } else {
        remaining <- candidate
        valid <- valid + 1
      }
    }
  }
  list(remaining = remaining, valid_throws = valid)
}

format_report <- function(throws, result) {
  header <- sprintf("%d throws submitted", length(throws))
  body <- sprintf("remaining score: %d, valid throws: %d",
                  result$remaining, result$valid_throws)
  paste(header, body, sep = "\n")
}

game <- c("treble twenty", "treble twenty", "treble twenty",
          "double ten", "outer bull", "inner bull", "nineteen")
result <- score(game)
cat(format_report(game, result), "\n")

checkout <- c("treble twenty", "treble twenty", "double ten")
cat(format_report(checkout, score(checkout)), "\n")

