pKa_basic <- c(K = 10.54, R = 12.48, H = 6.04)
pKa_acidic <- c(D = 3.90, E = 4.07)
default_pH <- 7.4
standard_residues <- strsplit("ACDEFGHIKLMNPQRSTVWY", "", fixed = TRUE)[[1]]

split_residues <- function(aa_sequence) {
  cleaned <- toupper(gsub("[[:space:]]", "", aa_sequence))
  residues <- strsplit(cleaned, "", fixed = TRUE)[[1]]
  valid <- residues %in% standard_residues
  if (any(!valid)) {
    bad <- paste(unique(residues[!valid]), collapse = ", ")
    stop(paste("sequence contains non-amino-acid characters:", bad))
  }
  residues
}

count_group <- function(residues, pKa_table) {
  vapply(names(pKa_table), function(letter) sum(residues == letter), numeric(1))
}

basic_fraction <- function(pKa, pH) {
  1 / (1 + 10^(pH - pKa))
}

acidic_fraction <- function(pKa, pH) {
  -1 / (1 + 10^(pKa - pH))
}

group_charges <- function(residues, pH = default_pH) {
  basic_counts <- count_group(residues, pKa_basic)
  acidic_counts <- count_group(residues, pKa_acidic)
  positive <- basic_counts * basic_fraction(pKa_basic, pH)
  negative <- acidic_counts * acidic_fraction(pKa_acidic, pH)
