price_changes <- function(prices) {
  n <- length(prices)
  prices[2:n] - prices[1:(n - 1)]
}

split_changes <- function(changes) {
  gains <- ifelse(changes > 0, changes, 0)
  losses <- ifelse(changes < 0, -changes, 0)
  list(gains = gains, losses = losses)
}

smoothed_averages <- function(gains, losses, period) {
  n <- length(gains)
  avg_gain <- rep(NA_real_, n)
  avg_loss <- rep(NA_real_, n)
  avg_gain[period] <- mean(gains[1:period])
  avg_loss[period] <- mean(losses[1:period])
  if (n > period) {
    for (i in (period + 1):n) {
      prev_gain <- avg_gain[i - 1]
      prev_loss <- avg_loss[i - 1]
      avg_gain[i] <- (prev_gain * (period - 1) + gains[i]) / period
      avg_loss[i] <- (prev_loss * (period - 1) + losses[i]) / period
    }
  }
  list(avg_gain = avg_gain, avg_loss = avg_loss)
}

index_values <- function(avg_gain, avg_loss) {
  rsi <- rep(NA_real_, length(avg_gain))
  for (i in seq_along(avg_gain)) {
    if (is.na(avg_gain[i])) next
    if (avg_loss[i] == 0) {
      rsi[i] <- 100
    } else {
      rs <- avg_gain[i] / avg_loss[i]
      rsi[i] <- 100 - 100 / (1 + rs)
    }
  }
  rsi
}

calculate <- function(prices) {
  period <- 14
  if (!is.numeric(prices)) stop("prices must be a numeric vector")
  if (anyNA(prices)) stop("prices must not contain missing values")
  if (length(prices) < period + 1) {
    return(rep(NA_real_, length(prices)))
  }
  changes <- price_changes(prices)
  parts <- split_changes(changes)
  averages <- smoothed_averages(parts$gains, parts$losses, period)
  rsi_changes <- index_values(averages$avg_gain, averages$avg_loss)
  c(NA_real_, rsi_changes)
}

format_report <- function(prices, rsi) {
  reported <- which(!is.na(rsi))
  rows <- sprintf("day %3d  close %8.2f  RSI %6.2f",
                  reported, prices[reported], rsi[reported])
  paste(rows, collapse = "\n")
}

main <- function() {
  closes <- c(44.34, 44.09, 44.15, 43.61, 44.33, 44.83, 45.10, 45.42,
              45.84, 46.08, 45.89, 46.03, 45.61, 46.28, 46.28, 46.00,
              46.03, 46.41, 46.22, 45.64, 46.21, 46.25, 45.71, 46.45,
              45.78, 45.35, 44.03, 44.18, 44.22, 44.57, 43.42, 42.66,
              43.13)
  rsi <- calculate(closes)
  cat(format_report(closes, rsi), "\n", sep = "")
  latest <- tail(rsi[!is.na(rsi)], 1)
  cat(sprintf("latest index value: %.4f\n", latest))
}

main()

