has_all_digits <- function(values) {
  if (length(values) != 9) {
    return(FALSE)
  }
  sorted <- sort(values)
  identical(as.numeric(sorted), as.numeric(1:9))
}

check_entries <- function(grid) {
  if (!is.matrix(grid) || !is.numeric(grid)) {
    return(FALSE)
  }
  dims <- dim(grid)
  if (dims[1] != 9 || dims[2] != 9) {
    return(FALSE)
  }
  flat <- as.numeric(grid)
  if (any(is.na(flat))) {
    return(FALSE)
  }
  whole <- all(flat == trunc(flat))
  in_range <- all(flat >= 1 & flat <= 9)
  whole && in_range
}

check_rows <- function(grid) {
  status <- TRUE
  for (i in 1:9) {
    row_values <- grid[i, ]
    if (!has_all_digits(row_values)) {
      status <- FALSE
    }
  }
  status
}

check_columns <- function(grid) {
  status <- TRUE
  for (j in 1:9) {
    col_values <- grid[, j]
    if (!has_all_digits(col_values)) {
      status <- FALSE
    }
  }
  status
}

check_blocks <- function(grid) {
  status <- TRUE
  starts <- c(1, 4, 7)
  for (r in starts) {
    for (c in starts) {
      block <- grid[r:(r + 2), c:(c + 2)]
      if (!has_all_digits(as.numeric(block))) {
        status <- FALSE
      }
    }
  }
  status
}

validate <- function(grid) {
  if (!check_entries(grid)) {
    return(FALSE)
  }
  rows_ok <- check_rows(grid)
  cols_ok <- check_columns(grid)
  blocks_ok <- check_blocks(grid)
  rows_ok && cols_ok && blocks_ok
}

report <- function(label, grid) {
  verdict <- if (validate(grid)) "valid" else "invalid"
  cat(sprintf("%s: %s\n", label, verdict))
}

solved_rows <- c(
  5, 3, 4, 6, 7, 8, 9, 1, 2,
  6, 7, 2, 1, 9, 5, 3, 4, 8,
  1, 9, 8, 3, 4, 2, 5, 6, 7,
  8, 5, 9, 7, 6, 1, 4, 2, 3,
  4, 2, 6, 8, 5, 3, 7, 9, 1,
  7, 1, 3, 9, 2, 4, 8, 5, 6,
  9, 6, 1, 5, 3, 7, 2, 8, 4,
  2, 8, 7, 4, 1, 9, 6, 3, 5,
  3, 4, 5, 2, 8, 6, 1, 7, 9
)
solved <- matrix(solved_rows, nrow = 9, byrow = TRUE)
broken <- solved
broken[1, 1] <- 3
broken[1, 2] <- 5

report("solved puzzle", solved)
report("swapped pair", broken)

