BASE_TEMPERATURE <- 20
NOMINAL_LENGTH <- 1000
EXPANSION_COEFFICIENT <- 1.2e-5

validate_temperatures <- function(temperatures) {
  if (!is.numeric(temperatures) || length(temperatures) == 0) {
    stop("temperatures must be a non-empty numeric vector")
  }
  bad <- which(!is.finite(temperatures))
  if (length(bad) > 0) {
    stop(paste("non-finite temperature at index", paste(bad, collapse = ", ")))
  }
  invisible(TRUE)
}

delta_temperature <- function(temperature) {
  temperature - BASE_TEMPERATURE
}

linear_expansion <- function(temperature) {
  dt <- delta_temperature(temperature)
  EXPANSION_COEFFICIENT * NOMINAL_LENGTH * dt
}

expand <- function(temperatures) {
  validate_temperatures(temperatures)
  current_length <- NOMINAL_LENGTH
  max_length <- NOMINAL_LENGTH
  max_change <- 0
  for (temperature in temperatures) {
    change <- linear_expansion(temperature)
    previous_length <- current_length
    current_length <- NOMINAL_LENGTH + change
    daily_change <- abs(current_length - previous_length)
    if (current_length > max_length) {
      max_length <- current_length
    }
    if (daily_change > max_change) {
      max_change <- daily_change
    }
  }
  list(max_length = max_length, max_change = max_change)
}

daily_lengths <- function(temperatures) {
  validate_temperatures(temperatures)
  NOMINAL_LENGTH + vapply(temperatures, linear_expansion, numeric(1))
}

format_report <- function(temperatures) {
  result <- expand(temperatures)
  lengths <- daily_lengths(temperatures)
  shortest <- min(lengths)
  lines <- c(
    sprintf("Days measured: %d", length(temperatures)),
    sprintf("Temperature range: %.1f C to %.1f C", min(temperatures), max(temperatures)),
    sprintf("Maximum length: %.4f m", result$max_length),
    sprintf("Minimum length: %.4f m", shortest),
    sprintf("Largest single-day change: %.6f m", result$max_change)
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  readings <- c(12.5, 18.0, 20.0, 27.3, 33.1, 29.8, 21.4, 5.2, -8.7, 14.0)
  report <- format_report(readings)
  cat(report, "\n", sep = "")
  summary_values <- expand(readings)
  cat(sprintf("Total span of movement: %.6f m\n",
              summary_values$max_length - min(daily_lengths(readings))))
}

main()

