SEA_LEVEL_TEMPERATURE_C <- 15
SEA_LEVEL_PRESSURE_MB <- 1010

deg_to_rad <- function(degrees) {
  degrees * pi / 180
}

correction_factor <- function(temperature_c = SEA_LEVEL_TEMPERATURE_C,
                              pressure_mb = SEA_LEVEL_PRESSURE_MB) {
  pressure_term <- pressure_mb / 1010
  temperature_term <- 283 / (273 + temperature_c)
  pressure_term * temperature_term
}

refraction_arcmin <- function(angle_deg, correction) {
  inner_deg <- angle_deg + 10.3 / (angle_deg + 5.11)
  inner_rad <- deg_to_rad(inner_deg)
  tangent <- tan(inner_rad)
  correction * 1.02 / tangent
}

refract <- function(angles) {
  if (!is.numeric(angles)) {
    stop("angles must be a numeric vector of degrees")
  }
  correction <- correction_factor()
  true_angles <- numeric(length(angles))
  for (i in seq_along(angles)) {
    apparent <- angles[i]
    if (is.na(apparent)) {
      true_angles[i] <- NA_real_
      next
    }
    adjustment_arcmin <- refraction_arcmin(apparent, correction)
    adjustment_deg <- adjustment_arcmin / 60
    true_angles[i] <- apparent - adjustment_deg
  }
  true_angles
}

format_arcmin <- function(angle_deg) {
  whole_degrees <- trunc(angle_deg)
  minutes <- abs(angle_deg - whole_degrees) * 60
  sprintf("%3d deg %05.2f min", as.integer(whole_degrees), minutes)
}

refraction_report <- function(angles) {
  corrected <- refract(angles)
  deltas <- (angles - corrected) * 60
  data.frame(
    apparent = vapply(angles, format_arcmin, character(1)),
    true = vapply(corrected, format_arcmin, character(1)),
    refraction_arcmin = round(deltas, 3),
    stringsAsFactors = FALSE
  )
}

main <- function() {
  observations <- c(90, 60, 45, 30, 20, 10, 5, 2, 1, 0.5)
  report <- refraction_report(observations)
  cat("Atmospheric refraction at", SEA_LEVEL_TEMPERATURE_C, "C and",
      SEA_LEVEL_PRESSURE_MB, "mb\n\n")
  print(report, row.names = FALSE)
  horizon_shift <- report$refraction_arcmin[length(observations)]
  cat("\nRefraction near the horizon:", horizon_shift, "arcminutes\n")
  invisible(report)
}

main()

