estimate <- function(grid) {
  validate_grid(grid)
  sizes <- block_sizes(ncol(grid))
  counts <- vapply(sizes, function(s) count_boxes(grid, s), numeric(1))
  log_sizes <- log(sizes)
  log_counts <- log(counts)
  model <- lm(log_counts ~ log_sizes)
  unname(coef(model)[["log_sizes"]])
}

validate_grid <- function(grid) {
  if (!is.matrix(grid) || !is.numeric(grid)) {
    stop("grid must be a numeric matrix")
  }
  values <- unique(as.vector(grid))
  if (!all(values %in% c(0, 1))) {
    stop("grid must contain only zeros and ones")
  }
  if (!any(grid > 0)) {
    stop("grid must contain at least one positive value")
  }
  invisible(TRUE)
}

block_sizes <- function(width) {
  sizes <- integer(0)
  size <- width
  while (size >= 1) {
    sizes <- c(sizes, size)
    size <- size %/% 2
  }
  sizes
}

count_boxes <- function(grid, size) {
  rows <- nrow(grid)
  cols <- ncol(grid)
  row_starts <- seq(1, rows, by = size)
  col_starts <- seq(1, cols, by = size)
  filled <- 0
  for (r in row_starts) {
    r_end <- min(r + size - 1, rows)
    for (c in col_starts) {
      c_end <- min(c + size - 1, cols)
      block <- grid[r:r_end, c:c_end, drop = FALSE]
      if (any(block > 0)) {
        filled <- filled + 1
      }
    }
  }
  filled
}

sierpinski_carpet <- function(depth) {
  grid <- matrix(1, nrow = 1, ncol = 1)
  for (step in seq_len(depth)) {
    size <- nrow(grid)
    bigger <- matrix(0, nrow = 3 * size, ncol = 3 * size)
    for (br in 0:2) {
      for (bc in 0:2) {
        if (br == 1 && bc == 1) next
        bigger[(br * size + 1):(br * size + size), (bc * size + 1):(bc * size + size)] <- grid
      }
    }
    grid <- bigger
  }
  grid
}

report <- function(label, grid) {
  slope <- estimate(grid)
  cat(sprintf("%-18s %3d x %3d   slope = %8.4f   dimension = %7.4f\n",
              label, nrow(grid), ncol(grid), slope, -slope))
  invisible(slope)
}

