char_counts <- function(text) {
  chars <- strsplit(text, "", fixed = TRUE)[[1]]
  if (length(chars) == 0) {
    return(list())
  }
  tally <- table(chars)
  counts <- as.integer(tally)
  names(counts) <- names(tally)
  as.list(counts)
}

make_node <- function(symbol, freq) {
  list(symbol = symbol, freq = freq)
}

initial_nodes <- function(counts) {
  nodes <- vector("list", length(counts))
  labels <- names(counts)
  for (i in seq_along(counts)) {
    nodes[[i]] <- make_node(labels[i], counts[[i]])
  }
  nodes
}

lowest_index <- function(nodes) {
  best <- 1L
  for (i in seq_along(nodes)) {
    if (nodes[[i]]$freq < nodes[[best]]$freq) {
      best <- i
    }
  }
  best
}

combine_nodes <- function(left, right) {
  merged <- paste0(left$symbol, right$symbol)
  make_node(merged, left$freq + right$freq)
}

build <- function(text) {
  counts <- char_counts(text)
  nodes <- initial_nodes(counts)
  if (length(nodes) == 0) {
    return(0L)
  }
  while (length(nodes) > 1) {
    i <- lowest_index(nodes)
    first <- nodes[[i]]
    nodes[[i]] <- NULL
    j <- lowest_index(nodes)
    second <- nodes[[j]]
    nodes[[j]] <- NULL
    nodes[[length(nodes) + 1]] <- combine_nodes(first, second)
  }
  nodes[[1]]$freq
}

report <- function(text) {
  root <- build(text)
  distinct <- length(char_counts(text))
  sprintf("%-28s distinct=%2d root frequency=%3d",
          paste0("\"", text, "\""), distinct, root)
}

main <- function() {
  texts <- c("this is an example for huffman encoding",
             "mississippi river",
             "aaaa",
             "")
  for (text in texts) {
    cat(report(text), "\n")
  }
}

main()

