column_means <- function(data) {
  apply(data, 2, mean)
}

center_columns <- function(data) {
  means <- column_means(data)
  sweep(data, 2, means, FUN = "-")
}

covariance_matrix <- function(centered) {
  n <- nrow(centered)
  crossprod(centered) / n
}

validate_data <- function(data) {
  if (!is.matrix(data) || !is.numeric(data)) {
    stop("data must be a numeric matrix")
  }
  if (nrow(data) < 2L || ncol(data) < 1L) {
    stop("data must have at least two rows and one column")
  }
  if (any(!is.finite(data))) {
    stop("data must contain only finite values")
  }
  invisible(TRUE)
}

mahalanobis <- function(data) {
  validate_data(data)
  centered <- center_columns(data)
  covariance <- covariance_matrix(centered)
  inverse <- solve(covariance)
  distances <- numeric(nrow(centered))
  for (i in seq_len(nrow(centered))) {
    row_vector <- matrix(centered[i, ], nrow = 1L)
    distances[i] <- as.numeric(row_vector %*% inverse %*% t(row_vector))
  }
  distances
}

format_report <- function(data, distances) {
  labels <- rownames(data)
  if (is.null(labels)) {
    labels <- paste0("sample_", seq_len(nrow(data)))
  }
  coordinates <- apply(data, 1, function(row) paste(format(row, trim = TRUE), collapse = ", "))
  paste0(labels, " (", coordinates, "): ", format(round(distances, 6), trim = TRUE))
}

main <- function() {
  observations <- matrix(
    c(4, 2, 1,
      2, 4, 3,
      2, 3, 5,
      3, 6, 4,
      4, 4, 2),
    nrow = 5L, byrow = TRUE
  )
  colnames(observations) <- c("height", "width", "depth")
  distances <- mahalanobis(observations)
  report <- format_report(observations, distances)
  cat("Squared Mahalanobis distances from the centroid:\n")
  cat(report, sep = "\n")
  cat("\n")
  average <- mean(distances)
  cat("Mean distance:", format(round(average, 6), trim = TRUE), "\n")
  extreme <- which.max(distances)
  cat("Most distant sample:", extreme, "\n")
}

main()

