merge_lists <- function(a, b) {
  if (is.list(a) || is.list(b)) {
    left <- as.list(a)
    right <- as.list(b)
    return(c(left, right))
  }
  c(a, b)
}

merge_all <- function(...) {
  parts <- list(...)
  if (length(parts) == 0) {
    return(c())
  }
  acc <- parts[[1]]
  for (i in seq_along(parts)[-1]) {
    acc <- merge_lists(acc, parts[[i]])
  }
  acc
}

describe_element <- function(x) {
  if (is.null(x)) {
    return("NULL")
  }
  if (is.character(x)) {
    return(paste0("'", x, "'"))
  }
  if (is.numeric(x) && x == round(x)) {
    return(format(x, trim = TRUE))
  }
  format(x)
}

format_merged <- function(x) {
  pieces <- vapply(as.list(x), describe_element, character(1))
  inner <- paste(pieces, collapse = ", ")
  wrapper <- if (is.list(x)) "list" else "c"
  paste0(wrapper, "(", inner, ")")
}

report_merge <- function(a, b) {
  merged <- merge_lists(a, b)
  line <- paste(format_merged(a), "+", format_merged(b), "->", format_merged(merged))
  cat(line, "\n")
  invisible(merged)
}

main <- function() {
  numeric_left <- c(1, 2)
  numeric_right <- c(3, 4)
  report_merge(numeric_left, numeric_right)

  letters_left <- list("a", "b")
  letters_right <- list("c")
  report_merge(letters_left, letters_right)

  mixed <- merge_lists(c(10, 20), list("x"))
  cat("mixed:", format_merged(mixed), "\n")

  chained <- merge_all(c(1), c(2, 3), c(4, 5, 6))
  cat("chained:", format_merged(chained), "\n")

  empty_side <- merge_lists(character(0), c("only"))
  cat("empty side:", format_merged(empty_side), "\n")
}

main()

