simple_interest <- function(principal, rate, time) {
  if (!is.numeric(principal) || !is.numeric(rate) || !is.numeric(time)) {
    stop("principal, rate and time must be numeric")
  }
  if (principal < 0 || rate < 0 || time < 0) {
    stop("principal, rate and time must be non-negative")
  }
  principal * rate * time
}

total_amount <- function(principal, rate, time) {
  interest <- simple_interest(principal, rate, time)
  principal + interest
}

growth_schedule <- function(principal, rate, years) {
  periods <- seq_len(years)
  interest <- vapply(periods, function(t) simple_interest(principal, rate, t), numeric(1))
  balance <- principal + interest
  data.frame(year = periods, interest = interest, balance = balance)
}

format_money <- function(amount) {
  rounded <- round(amount, 2)
  paste0("$", formatC(rounded, format = "f", digits = 2, big.mark = ","))
}

describe_loan <- function(principal, rate, time) {
  interest <- simple_interest(principal, rate, time)
  final <- total_amount(principal, rate, time)
  percent <- rate * 100
  sprintf("%s at %.2f%% for %g year(s): interest %s, total %s",
          format_money(principal), percent, time,
          format_money(interest), format_money(final))
}

report <- function(loans) {
  lines <- character(0)
  for (loan in loans) {
    lines <- c(lines, describe_loan(loan$principal, loan$rate, loan$time))
  }
  lines
}

main <- function() {
  loans <- list(
    list(principal = 1000, rate = 0.05, time = 2),
    list(principal = 5000, rate = 0.03, time = 1),
    list(principal = 2500, rate = 0.075, time = 4)
  )
  for (line in report(loans)) {
    cat(line, "\n")
  }

  schedule <- growth_schedule(1000, 0.05, 5)
  cat("\nYear-by-year growth on", format_money(1000), "at 5%:\n")
  for (i in seq_len(nrow(schedule))) {
    row <- schedule[i, ]
    cat(sprintf("  year %d: interest %s, balance %s\n",
                row$year, format_money(row$interest), format_money(row$balance)))
  }

  quick <- simple_interest(1000, 0.05, 2)
  cat("\nsimple_interest(1000, 0.05, 2) =", quick, "\n")
  cat("simple_interest(5000, 0.03, 1) =", simple_interest(5000, 0.03, 1), "\n")
}

main()

