common_elements <- function(x, y) {
  if (!is.vector(x) || !is.vector(y)) {
    stop("common_elements() requires two vectors")
  }
  if (length(x) == 0 || length(y) == 0) {
    return(x[0])
  }
  keep <- x %in% y
  result <- unique(x[keep])
  result
}

common_count <- function(x, y) {
  shared <- common_elements(x, y)
  length(shared)
}

jaccard_index <- function(x, y) {
  pool <- unique(c(x, y))
  if (length(pool) == 0) {
    return(NA_real_)
  }
  shared <- common_count(x, y)
  shared / length(pool)
}

format_vector <- function(v) {
  if (length(v) == 0) {
    empty <- paste0(class(v)[1], "(0)")
    return(empty)
  }
