filter_vector <- function(v, threshold) {
  if (!is.numeric(v) && length(v) > 0) {
    stop("filter_vector: 'v' must be a numeric vector")
  }
  if (!is.numeric(threshold) || length(threshold) != 1L || is.na(threshold)) {
    stop("filter_vector: 'threshold' must be a single non-missing number")
  }
  keep <- !is.na(v) & v > threshold
  as.numeric(v[keep])
}

summarise_filter <- function(v, threshold) {
  kept <- filter_vector(v, threshold)
  dropped <- length(v) - length(kept)
  total <- if (length(kept) > 0L) sum(kept) else 0
  list(
    threshold = threshold,
    n_in = length(v),
    n_kept = length(kept),
    n_dropped = dropped,
    kept = kept,
    total = total
  )
}

format_vector <- function(v) {
  if (length(v) == 0L) {
    return("numeric(0)")
  }
  parts <- format(v, trim = TRUE)
  paste0("c(", paste(parts, collapse = ", "), ")")
}

format_summary <- function(s) {
  header <- sprintf("threshold = %s", format(s$threshold, trim = TRUE))
  counts <- sprintf("kept %d of %d (dropped %d)", s$n_kept, s$n_in, s$n_dropped)
  values <- sprintf("values %s, sum %s",
                    format_vector(s$kept),
                    format(s$total, trim = TRUE))
  paste(header, counts, values, sep = " | ")
}

report_cases <- function(cases) {
  lines <- character(length(cases))
  for (i in seq_along(cases)) {
    case <- cases[[i]]
    s <- summarise_filter(case$v, case$threshold)
    lines[i] <- paste0(case$label, ": ", format_summary(s))
  }
  lines
}

