  cases <- list(
    list(label = "mixed", v = c(10, 5, 20, 8), threshold = 10),
    list(label = "all below", v = c(1, 2, 3), threshold = 5),
    list(label = "negatives", v = c(-4, -1, 0, 3.5), threshold = -2),
    list(label = "with NA", v = c(7, NA, 12), threshold = 6),
    list(label = "empty", v = numeric(0), threshold = 0)
  )
  report <- report_cases(cases)
  cat(report, sep = "\n")
  cat("\n")
  invisible(report)
}

