get_current_date <- function() {
  today <- Sys.Date()
  format(today, "%Y-%m-%d")
}

parse_iso_date <- function(text) {
  cleaned <- trimws(text)
  parsed <- as.Date(cleaned, format = "%Y-%m-%d")
  if (is.na(parsed)) {
    stop(sprintf("not a valid YYYY-MM-DD date: '%s'", text))
  }
  parsed
}

describe_date <- function(iso_text) {
  d <- parse_iso_date(iso_text)
  weekday <- format(d, "%A")
  month_name <- format(d, "%B")
  day_number <- as.integer(format(d, "%d"))
  year <- format(d, "%Y")
  sprintf("%s, %d %s %s", weekday, day_number, month_name, year)
}

day_of_year <- function(iso_text) {
  d <- parse_iso_date(iso_text)
  as.integer(format(d, "%j"))
}

is_leap_year <- function(iso_text) {
  year <- as.integer(format(parse_iso_date(iso_text), "%Y"))
  divisible_by_4 <- year %% 4 == 0
  century <- year %% 100 == 0
  divisible_by_400 <- year %% 400 == 0
  divisible_by_4 && (!century || divisible_by_400)
}

days_between <- function(from_text, to_text) {
  from_date <- parse_iso_date(from_text)
  to_date <- parse_iso_date(to_text)
  as.integer(to_date - from_date)
}

end_of_year <- function(iso_text) {
  year <- format(parse_iso_date(iso_text), "%Y")
  paste0(year, "-12-31")
}

date_report <- function(iso_text) {
  total_days <- if (is_leap_year(iso_text)) 366L else 365L
  elapsed <- day_of_year(iso_text)
  remaining <- days_between(iso_text, end_of_year(iso_text))
  percent <- round(100 * elapsed / total_days, 1)
  report_rows <- c(
    paste("ISO date      :", iso_text),
    paste("Long form     :", describe_date(iso_text)),
    paste("Day of year   :", elapsed, "of", total_days),
    paste("Days remaining:", remaining),
    paste0("Year progress : ", percent, "%")
  )
  paste(report_rows, collapse = "\n")
}

main <- function() {
  today <- get_current_date()
  cat(today, "\n", sep = "")
  cat(date_report(today), "\n", sep = "")
}

if (!interactive()) {
  main()
}

