file_exists_check <- function(path) {
  if (!is.character(path) || length(path) != 1L || is.na(path)) {
    stop("file_exists_check() expects a single non-missing character path")
  }
  trimmed <- trimws(path)
  if (!nzchar(trimmed)) {
    return(FALSE)
  }
  info <- file.info(path.expand(trimmed))
  if (is.na(info$isdir)) {
    return(FALSE)
  }
  !isTRUE(info$isdir)
}

describe_path <- function(path) {
  expanded <- path.expand(path)
  info <- file.info(expanded)
  if (is.na(info$isdir)) {
    kind <- "missing"
    size <- NA_real_
  } else if (isTRUE(info$isdir)) {
    kind <- "directory"
    size <- NA_real_
  } else {
    kind <- "file"
    size <- info$size
  }
  list(path = path, kind = kind, size = size, exists = file_exists_check(path))
}

format_entry <- function(entry) {
  flag <- if (entry$exists) "TRUE " else "FALSE"
  detail <- if (is.na(entry$size)) entry$kind else sprintf("%s, %d bytes", entry$kind, entry$size)
  sprintf("%-28s %s  (%s)", entry$path, flag, detail)
}

report_paths <- function(paths) {
  entries <- lapply(paths, describe_path)
  rendered <- vapply(entries, format_entry, character(1))
  cat(rendered, sep = "\n")
  cat("\n")
  invisible(entries)
}

main <- function() {
  workdir <- tempfile("existence-demo")
  dir.create(workdir, recursive = TRUE)
  on.exit(unlink(workdir, recursive = TRUE), add = TRUE)

  temp_file <- file.path(workdir, "temp.txt")
  writeLines(c("first line", "second line"), temp_file)

  ghost <- file.path(workdir, "nonexistent.txt")
  candidates <- c(temp_file, ghost, workdir, "   ")

  entries <- report_paths(candidates)
  found <- vapply(entries, function(e) e$exists, logical(1))
  cat(sprintf("%d of %d candidates are regular existing files\n", sum(found), length(found)))
  invisible(found)
}

if (identical(environment(), globalenv())) {
  main()
}

