simple_search <- function(lines, query) {
  if (!is.character(lines)) {
    stop("`lines` must be a character vector")
  }
  if (!is.character(query) || length(query) != 1L || is.na(query)) {
    stop("`query` must be a single non-missing string")
  }
  haystack <- tolower(lines)
  needle <- tolower(query)
  present <- !is.na(haystack)
  if (nzchar(needle)) {
    hits <- present & grepl(needle, haystack, fixed = TRUE)
  } else {
    hits <- present
  }
  hits
}

matching_lines <- function(lines, query) {
  mask <- simple_search(lines, query)
  lines[mask]
}

search_report <- function(lines, query) {
  mask <- simple_search(lines, query)
  idx <- which(mask)
  header <- sprintf("query '%s': %d of %d line(s) matched", query,
                    length(idx), length(lines))
  if (length(idx) == 0L) {
    return(header)
  }
  body <- sprintf("  %4d | %s", idx, lines[idx])
  c(header, body)
}

read_lines_safely <- function(path) {
  if (!file.exists(path)) {
    stop(sprintf("no such file: %s", path))
  }
  con <- file(path, open = "r")
  on.exit(close(con))
  readLines(con, warn = FALSE)
}

main <- function(args = commandArgs(trailingOnly = TRUE)) {
  corpus <- c("apple", "Banana", "Orange", "hello", "world")
  queries <- c("a", "xyz")
  if (length(args) >= 2L) {
    corpus <- read_lines_safely(args[1L])
    queries <- args[-1L]
  }
  for (q in queries) {
    cat(search_report(corpus, q), sep = "\n")
    cat("\n")
  }
  found <- unique(unlist(lapply(queries, function(q) matching_lines(corpus, q))))
  cat(sprintf("%d distinct line(s) matched at least one query\n", length(found)))
  invisible(NULL)
}

if (!interactive()) {
  main()
}

