roll_dice <- function() {
  sample.int(6, size = 1)
}

roll_many <- function(n) {
  if (!is.numeric(n) || length(n) != 1 || n < 1 || n != as.integer(n)) {
    stop("n must be a single positive whole number")
  }
  rolls <- integer(n)
  for (i in seq_len(n)) {
    rolls[i] <- roll_dice()
  }
  rolls
}

tally_rolls <- function(rolls) {
  counts <- integer(6)
  names(counts) <- as.character(1:6)
  for (face in rolls) {
    counts[[face]] <- counts[[face]] + 1L
  }
  counts
}

face_proportions <- function(counts) {
  total <- sum(counts)
  counts / total
}

fairness_statistic <- function(counts) {
  expected <- sum(counts) / length(counts)
  sum((counts - expected)^2 / expected)
}

format_report <- function(counts) {
  props <- face_proportions(counts)
  lines <- character(length(counts))
  for (i in seq_along(counts)) {
    bar <- paste(rep("#", counts[[i]]), collapse = "")
    lines[i] <- sprintf("face %d: %5d  %6.2f%%  %s",
                        i, counts[[i]], 100 * props[[i]], bar)
  }
  header <- sprintf("Rolled %d dice", sum(counts))
  footer <- sprintf("chi-square statistic: %.3f (5 degrees of freedom)",
                    fairness_statistic(counts))
  paste(c(header, lines, footer), collapse = "\n")
}

simulate <- function(n) {
  rolls <- roll_many(n)
  counts <- tally_rolls(rolls)
  list(rolls = rolls, counts = counts, report = format_report(counts))
}

main <- function() {
  first <- roll_dice()
  second <- roll_dice()
  cat(sprintf("Two single rolls: %d and %d\n\n", first, second))

  small <- simulate(30)
  cat("First thirty rolls:", paste(small$rolls, collapse = " "), "\n")
  cat(small$report, "\n\n", sep = "")

  large <- simulate(60000)
  cat(large$report, "\n", sep = "")

  worst <- which.max(abs(face_proportions(large$counts) - 1 / 6))
  cat(sprintf("Face furthest from the expected 1/6: %d\n", worst))
}

main()

