parse_time <- function(time) {
  parts <- strsplit(time, ":", fixed = TRUE)[[1]]
  if (length(parts) != 2) {
    stop("time must be in 'HH:MM' format")
  }
  if (!all(grepl("^[0-9]+$", parts))) {
    stop("time must contain only digits around the colon")
  }
  hour <- as.integer(parts[1])
  minute <- as.integer(parts[2])
  if (hour > 23 || minute > 59) {
    stop("time must be a valid 24-hour clock value")
  }
  list(hour = hour, minute = minute)
}

format_time <- function(clock) {
  sprintf("%02d:%02d", clock$hour, clock$minute)
}

check_task_name <- function(task_name) {
  trimmed <- trimws(task_name)
  if (!nzchar(trimmed)) {
    stop("task_name must not be empty")
  }
  trimmed
}

schedule_task <- function(task_name, time) {
  name <- check_task_name(task_name)
  clock <- parse_time(time)
  stamp <- format_time(clock)
  message_text <- sprintf("Task '%s' scheduled for %s.", name, stamp)
  cat(message_text, "\n", sep = "")
  invisible(list(task = name, time = stamp, minutes = clock$hour * 60 + clock$minute))
}

schedule_agenda <- function(entries) {
  scheduled <- lapply(entries, function(entry) schedule_task(entry[[1]], entry[[2]]))
  order_index <- order(vapply(scheduled, function(s) s$minutes, numeric(1)))
  scheduled[order_index]
}

print_agenda <- function(scheduled) {
  header <- "--- Agenda (earliest first) ---"
  cat(header, "\n", sep = "")
  for (item in scheduled) {
    line <- sprintf("%s  %s", item$time, item$task)
    cat(line, "\n", sep = "")
  }
}

main <- function() {
  schedule_task("Meeting", "10:30")
  schedule_task("Lunch", "12:00")
  entries <- list(
    list("Standup", "09:15"),
    list("Code review", "16:45"),
    list("Gym", "18:00")
  )
  agenda <- schedule_agenda(entries)
  print_agenda(agenda)
  failure <- tryCatch(schedule_task("Broken", "25:61"), error = function(e) conditionMessage(e))
  cat("Rejected entry: ", failure, "\n", sep = "")
}

main()

