all_unique = function(x) {
  if (length(x) == 0) {
    return(TRUE)
  }
  seen = unique(x)
  length(seen) == length(x)
}

duplicated_values = function(x) {
  repeats = x[duplicated(x)]
  unique(repeats)
}

describe_vector = function(x, label) {
  unique_flag = all_unique(x)
  contents = paste(format(x, trim = TRUE), collapse = ", ")
  header = sprintf("%s: [%s]", label, contents)
  if (unique_flag) {
    verdict = "all elements unique"
  } else {
    dups = duplicated_values(x)
    verdict = sprintf("repeated: %s", paste(dups, collapse = ", "))
  }
  sprintf("%s -> %s (%s)", header, unique_flag, verdict)
}

first_duplicate_position = function(x) {
  flags = duplicated(x)
  if (any(flags)) {
