filter_dataframe <- function(df, column_name, value) {
  if (!is.data.frame(df)) {
    stop("df must be a data frame")
  }
  if (!is.character(column_name) || length(column_name) != 1L) {
    stop("column_name must be a single string")
  }
  if (!column_name %in% names(df)) {
    stop(sprintf("column '%s' not found in data frame", column_name))
  }
  column <- df[[column_name]]
  if (is.factor(column)) {
    column <- as.character(column)
  }
  matches <- !is.na(column) & column == value
  result <- df[matches, , drop = FALSE]
  rownames(result) <- NULL
  result
}

count_matches <- function(df, column_name, value) {
  nrow(filter_dataframe(df, column_name, value))
}

summarise_filter <- function(df, column_name, value) {
  subset_df <- filter_dataframe(df, column_name, value)
  numeric_cols <- names(subset_df)[vapply(subset_df, is.numeric, logical(1))]
  stats <- lapply(numeric_cols, function(nm) {
    values <- subset_df[[nm]]
    data.frame(column = nm, total = sum(values), mean = mean(values))
  })
  if (length(stats) == 0L) {
    return(data.frame(column = character(0), total = numeric(0), mean = numeric(0)))
  }
  do.call(rbind, stats)
}

format_report <- function(df, column_name, value) {
  hits <- count_matches(df, column_name, value)
  header <- sprintf("%s == %s: %d of %d rows", column_name,
                    format(value), hits, nrow(df))
  stats <- summarise_filter(df, column_name, value)
  if (nrow(stats) == 0L) {
    return(header)
  }
  detail <- sprintf("  %s: total=%s mean=%s", stats$column,
                    format(stats$total), format(round(stats$mean, 2)))
  paste(c(header, detail), collapse = "\n")
}

main <- function() {
  df <- data.frame(name = c("A", "B", "C"), score = c(10, 20, 10),
                   stringsAsFactors = FALSE)
  tens <- filter_dataframe(df, "score", 10)
  print(tens)

  cat(format_report(df, "score", 10), "\n")
  cat(format_report(df, "name", "B"), "\n")

  empty <- filter_dataframe(df, "score", 99)
  cat("no matches ->", nrow(empty), "rows\n")
}

main()

