validate_dimension <- function(value, name) {
  if (!is.numeric(value) || length(value) != 1L) {
    stop(sprintf("%s must be a single numeric value", name))
  }
  if (is.na(value) || !is.finite(value)) {
    stop(sprintf("%s must be a finite number", name))
  }
  if (value <= 0) {
    stop(sprintf("%s must be positive, got %s", name, value))
  }
  invisible(value)
}

rectangle_perimeter <- function(length, width) {
  validate_dimension(length, "length")
  validate_dimension(width, "width")
  semi <- length + width
  2 * semi
}

rectangle_area <- function(length, width) {
  validate_dimension(length, "length")
  validate_dimension(width, "width")
  length * width
}

format_number <- function(x) {
  rounded <- round(x, 4)
  if (isTRUE(all.equal(rounded, round(rounded)))) {
    formatted <- format(as.integer(round(rounded)))
  } else {
    formatted <- format(rounded, trim = TRUE)
  }
  formatted
}

describe_rectangle <- function(length, width) {
  perimeter <- rectangle_perimeter(length, width)
  area <- rectangle_area(length, width)
  shape <- if (isTRUE(all.equal(length, width))) "square" else "rectangle"
  sprintf(
    "%s x %s %s: perimeter = %s, area = %s",
    format_number(length),
    format_number(width),
    shape,
    format_number(perimeter),
    format_number(area)
  )
}

report_table <- function(dimensions) {
  rows <- vapply(
    dimensions,
    function(pair) describe_rectangle(pair[1L], pair[2L]),
    character(1L)
  )
  paste(rows, collapse = "\n")
}

main <- function() {
  samples <- list(c(4, 5), c(2.5, 3), c(7, 7), c(10, 0.5))
  report <- report_table(samples)
  cat(report, "\n", sep = "")

  bad <- try(rectangle_perimeter(-1, 3), silent = TRUE)
  if (inherits(bad, "try-error")) {
    reason <- conditionMessage(attr(bad, "condition"))
    cat("rejected: ", reason, "\n", sep = "")
  }
}

main()

