concatenate_vectors <- function(vec1, vec2) {
  type1 <- vector_type(vec1)
  type2 <- vector_type(vec2)
  if (type1 != type2) {
    stop(sprintf("cannot concatenate a %s vector with a %s vector", type1, type2))
  }
  result <- vector(mode = type1, length = length(vec1) + length(vec2))
  if (length(vec1) > 0) {
    result[seq_along(vec1)] <- vec1
  }
  if (length(vec2) > 0) {
    result[length(vec1) + seq_along(vec2)] <- vec2
  }
  result
}

vector_type <- function(vec) {
  if (!is.atomic(vec) && !is.list(vec)) {
    stop("concatenate_vectors expects atomic vectors or lists")
  }
  mode(vec)
}

concatenate_all <- function(vecs) {
  if (length(vecs) == 0) {
    stop("nothing to concatenate")
  }
  acc <- vecs[[1]]
  for (i in seq_along(vecs)[-1]) {
    acc <- concatenate_vectors(acc, vecs[[i]])
  }
  acc
}

format_vector <- function(vec) {
  if (length(vec) == 0) {
    return(sprintf("%s(0)", vector_type(vec)))
  }
  pieces <- if (is.character(vec)) shQuote(vec, type = "cmd") else format(vec, trim = TRUE)
  paste0("c(", paste(pieces, collapse = ", "), ")")
}

report_concatenation <- function(vec1, vec2) {
  joined <- concatenate_vectors(vec1, vec2)
  line <- sprintf("%s + %s -> %s",
                  format_vector(vec1),
                  format_vector(vec2),
                  format_vector(joined))
  cat(line, "\n", sep = "")
  invisible(joined)
}

main <- function() {
  numbers <- report_concatenation(c(1, 2), c(3, 4))
  letters_out <- report_concatenation(c("a", "b"), c("c"))
  flags <- report_concatenation(c(TRUE, FALSE), logical(0))

  grown <- concatenate_all(list(numbers, c(5, 6), c(7)))
  cat("chained numeric:", format_vector(grown), "\n")
  cat("letters length:", length(letters_out), "\n")
  cat("flags preserved:", format_vector(flags), "\n")

  mismatch <- tryCatch(concatenate_vectors(c(1, 2), c("a")),
                       error = function(e) conditionMessage(e))
  cat("mismatch:", mismatch, "\n")
}

main()

