compound_interest <- function(principal, rate, time, n) {
  validate_inputs(principal, rate, time, n)
  growth <- 1 + rate / n
  periods <- n * time
  principal * growth^periods
}

validate_inputs <- function(principal, rate, time, n) {
  values <- list(principal = principal, rate = rate, time = time, n = n)
  for (name in names(values)) {
    value <- values[[name]]
    if (!is.numeric(value) || length(value) != 1 || !is.finite(value)) {
      stop(sprintf("'%s' must be a single finite numeric value", name))
    }
  }
  if (principal < 0) stop("'principal' must not be negative")
  if (time < 0) stop("'time' must not be negative")
  if (n <= 0) stop("'n' must be positive")
  invisible(TRUE)
}

interest_earned <- function(principal, rate, time, n) {
  final <- compound_interest(principal, rate, time, n)
  final - principal
}

effective_annual_rate <- function(rate, n) {
  validate_inputs(1, rate, 1, n)
  (1 + rate / n)^n - 1
}

schedule <- function(principal, rate, time, n) {
  years <- seq(0, time)
  amounts <- vapply(years, function(y) compound_interest(principal, rate, y, n), numeric(1))
  data.frame(year = years, amount = amounts, earned = amounts - principal)
}

format_money <- function(amount) {
  rounded <- round(amount, 2)
  formatC(rounded, format = "f", digits = 2, big.mark = ",")
}

report <- function(principal, rate, time, n) {
  rows <- schedule(principal, rate, time, n)
  header <- sprintf("Principal %s at %.2f%% compounded %d time(s)/year",
                    format_money(principal), rate * 100, n)
  cat(header, "\n")
  effective <- effective_annual_rate(rate, n)
  cat(sprintf("Effective annual rate: %.4f%%\n", effective * 100))
  for (i in seq_len(nrow(rows))) {
    line <- sprintf("  year %2d: %12s (interest %s)",
                    rows$year[i],
                    format_money(rows$amount[i]),
                    format_money(rows$earned[i]))
    cat(line, "\n")
  }
  invisible(rows)
}

main <- function() {
  simple <- compound_interest(1000, 0.05, 1, 1)
  quarterly <- compound_interest(1000, 0.04, 2, 4)
  cat(sprintf("compound_interest(1000, 0.05, 1, 1) = %s\n", format(simple)))
  cat(sprintf("compound_interest(1000, 0.04, 2, 4) = %.4f\n", quarterly))
  gain <- interest_earned(1000, 0.04, 2, 4)
  cat(sprintf("interest earned = %.4f\n", gain))
  report(2500, 0.06, 5, 12)
}

main()

