remove_element <- function(vec, element) {
  if (length(element) != 1L) {
    stop("element must be a single value")
  }
  if (length(vec) == 0L) {
    return(vec)
  }
  keep <- if (is.na(element)) !is.na(vec) else is.na(vec) | vec != element
  vec[keep]
}

count_occurrences <- function(vec, element) {
  removed <- length(vec) - length(remove_element(vec, element))
  removed
}

remove_several <- function(vec, elements) {
  result <- vec
  for (el in elements) {
    result <- remove_element(result, el)
  }
  result
}

format_vector <- function(vec) {
  if (length(vec) == 0L) {
    return("<empty>")
  }
  parts <- if (is.character(vec)) sprintf('"%s"', vec) else format(vec, trim = TRUE)
  paste0("c(", paste(parts, collapse = ", "), ")")
}

describe_removal <- function(vec, element) {
  result <- remove_element(vec, element)
  gone <- count_occurrences(vec, element)
  label <- if (is.character(element)) sprintf('"%s"', element) else format(element)
  sprintf(
    "%s minus %s -> %s (%d removed)",
    format_vector(vec), label, format_vector(result), gone
  )
}

main <- function() {
  numbers <- c(1, 2, 3, 2)
  fruit <- c("apple", "banana", "cherry")
  with_na <- c(4, NA, 5, NA)

  cases <- list(
    list(vec = numbers, element = 2),
    list(vec = fruit, element = "banana"),
    list(vec = with_na, element = NA),
    list(vec = numbers, element = 99)
  )

  for (case in cases) {
    line <- describe_removal(case$vec, case$element)
    cat(line, "\n", sep = "")
  }

  letters_vec <- c("a", "b", "c", "b", "d", "a")
  trimmed <- remove_several(letters_vec, c("a", "b"))
  cat("multi-removal: ", format_vector(trimmed), "\n", sep = "")

  invisible(NULL)
}

main()

