get_named_vector_values <- function(nv) {
  if (!is.vector(nv) || is.list(nv)) {
    stop("get_named_vector_values() expects an atomic vector")
  }
  values <- unname(nv)
  attributes(values) <- NULL
  values
}

get_named_vector_tags <- function(nv) {
  tags <- names(nv)
  if (is.null(tags)) {
    tags <- rep("", length(nv))
  }
  tags
}

describe_named_vector <- function(nv) {
  values <- get_named_vector_values(nv)
  tags <- get_named_vector_tags(nv)
  unnamed_count <- sum(!nzchar(tags))
  list(
    type = typeof(values),
    length = length(values),
    unnamed = unnamed_count,
    values = values,
    tags = tags
  )
}

format_pairs <- function(nv) {
  values <- get_named_vector_values(nv)
  tags <- get_named_vector_tags(nv)
  shown <- ifelse(nzchar(tags), tags, "<unnamed>")
  paste0(shown, " = ", format(values, trim = TRUE))
}

summarise_named_vector <- function(nv, title) {
  info <- describe_named_vector(nv)
  header <- sprintf("%s: %s vector of length %d", title, info$type, info$length)
  body <- paste("   ", format_pairs(nv))
  stripped <- paste("    values ->", paste(info$values, collapse = ", "))
  lines <- c(header, body, stripped)
  if (info$unnamed > 0L) {
    note <- sprintf("    (%d element(s) had no name)", info$unnamed)
    lines <- c(lines, note)
  }
  paste(lines, collapse = "\n")
}

main <- function() {
  samples <- list(
    numbers = c(a = 10, b = 20),
    strings = c(fruit = "apple", color = "red"),
    partial = c(first = 1L, 2L, third = 3L)
  )
  titles <- names(samples)
  for (i in seq_along(samples)) {
    cat(summarise_named_vector(samples[[i]], titles[i]), "\n", sep = "")
  }
  invisible(NULL)
}

main()

