parse_date <- function(date_str) {
  if (!is.character(date_str) || length(date_str) != 1L) {
    stop("date_str must be a single character string")
  }
  pattern <- "^[0-9]{4}-[0-9]{2}-[0-9]{2}$"
  if (!grepl(pattern, date_str)) {
    stop(sprintf("invalid date format: '%s' (expected YYYY-MM-DD)", date_str))
  }
  parsed <- as.Date(date_str, format = "%Y-%m-%d")
  if (is.na(parsed)) {
    stop(sprintf("not a real calendar date: '%s'", date_str))
  }
  parsed
}

day_name <- function(date_str) {
  parsed <- parse_date(date_str)
  day_labels <- c("Sunday", "Monday", "Tuesday", "Wednesday",
                  "Thursday", "Friday", "Saturday")
  index <- as.integer(format(parsed, "%w")) + 1L
  day_labels[index]
}

is_weekend <- function(date_str) {
  name <- day_name(date_str)
  name %in% c("Saturday", "Sunday")
}

describe_date <- function(date_str) {
  name <- day_name(date_str)
  kind <- if (is_weekend(date_str)) "weekend" else "weekday"
  sprintf("%s is a %s (%s)", date_str, name, kind)
}

weekend_days <- function(date_strs) {
  keep <- vapply(date_strs, is_weekend, logical(1), USE.NAMES = FALSE)
  date_strs[keep]
}

summarise_dates <- function(date_strs) {
  descriptions <- vapply(date_strs, describe_date, character(1), USE.NAMES = FALSE)
  weekends <- weekend_days(date_strs)
  total <- length(date_strs)
  report <- c(descriptions,
              sprintf("%d of %d dates fall on a weekend", length(weekends), total))
  if (length(weekends) > 0L) {
    report <- c(report, paste("Weekend dates:", paste(weekends, collapse = ", ")))
  }
  report
}

main <- function() {
  samples <- c("2023-10-27", "2023-10-28", "2023-10-29",
               "2023-10-30", "2024-02-29", "2000-01-01")
  output <- summarise_dates(samples)
  cat(output, sep = "\n")
  cat("\n")
  outcome <- tryCatch(is_weekend("2023-02-30"),
                      error = function(e) conditionMessage(e))
  cat("Rejected input:", outcome, "\n")
}

if (identical(environment(), globalenv())) {
  main()
}

