parse_csv_numbers <- function(csv_str) {
  if (!is.character(csv_str) || length(csv_str) != 1L) {
    stop("parse_csv_numbers expects a single character string")
  }
  fields <- strsplit(csv_str, ",", fixed = TRUE)[[1]]
  trimmed <- trimws(fields)
  if (length(trimmed) == 0L || any(nchar(trimmed) == 0L)) {
    stop("csv_str contains an empty field")
  }
  values <- suppressWarnings(as.numeric(trimmed))
  bad <- trimmed[is.na(values)]
  if (length(bad) > 0L) {
    stop(sprintf("not a number: %s", paste(bad, collapse = ", ")))
  }
  values
}

summarise_numbers <- function(values) {
  n <- length(values)
  total <- sum(values)
  stats <- list(
    count = n,
    total = total,
    mean = total / n,
    min = min(values),
    max = max(values)
  )
  stats
}

format_summary <- function(stats) {
  labels <- c("count", "total", "mean", "min", "max")
  numbers <- vapply(labels, function(key) stats[[key]], numeric(1))
  pieces <- sprintf("%s=%s", labels, formatC(numbers, format = "g", digits = 6))
  paste(pieces, collapse = "  ")
}

report_line <- function(csv_str) {
  parsed <- try(parse_csv_numbers(csv_str), silent = TRUE)
  if (inherits(parsed, "try-error")) {
    reason <- conditionMessage(attr(parsed, "condition"))
    return(sprintf("%-20s -> error: %s", csv_str, reason))
  }
  shown <- paste(parsed, collapse = ", ")
  summary_text <- format_summary(summarise_numbers(parsed))
  sprintf("%-20s -> c(%s)  [%s]", csv_str, shown, summary_text)
}

main <- function() {
  inputs <- c("1,2,3.5", "100", " 4 , -5e2 , 0.25 ", "1,,2", "7,abc")
  lines <- vapply(inputs, report_line, character(1))
  cat(lines, sep = "\n")
  cat("\n")
  first <- parse_csv_numbers(inputs[1])
  stopifnot(identical(first, c(1, 2, 3.5)))
  single <- parse_csv_numbers(inputs[2])
  stopifnot(identical(single, c(100)))
  invisible(NULL)
}

main()

