generate_alphanumeric_string <- function(length) {
  n <- length
  if (!is.numeric(n) || base::length(n) != 1L || is.na(n)) {
    stop("length must be a single non-missing numeric value")
  }
  n <- as.integer(n)
  if (n < 0L) {
    stop("length must be non-negative")
  }
  alphabet <- c(LETTERS, 0:9)
  if (n == 0L) {
    return("")
  }
  picks <- sample(alphabet, size = n, replace = TRUE)
  paste(picks, collapse = "")
}

generate_batch <- function(count, width) {
  sizes <- rep.int(width, count)
  vapply(sizes, generate_alphanumeric_string, character(1))
}

character_profile <- function(s) {
  chars <- strsplit(s, "", fixed = TRUE)[[1]]
  digits <- sum(grepl("^[0-9]$", chars))
  list(length = length(chars), digits = digits, letters = length(chars) - digits)
}

format_profile <- function(s) {
  profile <- character_profile(s)
  sprintf(
    "%-16s len=%2d letters=%2d digits=%2d",
    s, profile$length, profile$letters, profile$digits
  )
}

summarise_batch <- function(strings) {
  profiles <- lapply(strings, character_profile)
  total_letters <- sum(vapply(profiles, function(p) p$letters, numeric(1)))
  total_digits <- sum(vapply(profiles, function(p) p$digits, numeric(1)))
  total <- total_letters + total_digits
  share <- if (total > 0) total_digits / total else 0
  sprintf(
    "%d strings, %d letters, %d digits (%.1f%% digits)",
    length(strings), total_letters, total_digits, 100 * share
  )
}

main <- function() {
  set.seed(42)
  demo_lengths <- c(5L, 10L, 16L)
  for (len in demo_lengths) {
    sample_string <- generate_alphanumeric_string(len)
    cat(format_profile(sample_string), "\n")
  }
  batch <- generate_batch(count = 6L, width = 8L)
  cat("\nBatch of width 8:\n")
  cat(paste0("  ", batch, collapse = "\n"), "\n")
  report <- summarise_batch(batch)
  cat("\n", report, "\n", sep = "")
  empty <- generate_alphanumeric_string(0L)
  cat("zero length yields an empty string: ", sQuote(empty), "\n", sep = "")
}

main()

