build_deck <- function() {
  ranks <- c("2", "3", "4", "5", "6", "7", "8", "9", "T", "J", "Q", "K", "A")
  suits <- c("H", "D", "C", "S")
  grid <- expand.grid(rank = ranks, suit = suits, stringsAsFactors = FALSE)
  paste0(grid$rank, grid$suit)
}

simulate_card_draw <- function(deck, num_cards) {
  if (!is.character(deck)) {
    stop("deck must be a character vector of card codes")
  }
  size <- length(deck)
  if (size == 0L) {
    stop("deck must contain at least one card")
  }
  if (length(num_cards) != 1L || is.na(num_cards) || num_cards < 0) {
    stop("num_cards must be a single non-negative number")
  }
  wanted <- as.integer(num_cards)
  if (wanted > size) {
    stop("cannot draw more cards than the deck holds")
  }
  shuffled <- deck[sample.int(size)]
  shuffled[seq_len(wanted)]
}

card_rank <- function(cards) {
  substr(cards, 1L, nchar(cards) - 1L)
}

card_suit <- function(cards) {
  substr(cards, nchar(cards), nchar(cards))
}

describe_hand <- function(cards) {
  if (length(cards) == 0L) {
    return("empty hand")
  }
  suit_names <- c(H = "hearts", D = "diamonds", C = "clubs", S = "spades")
  counts <- table(factor(card_suit(cards), levels = names(suit_names)))
  present <- counts[counts > 0L]
  parts <- paste0(present, " ", suit_names[names(present)])
  paste(parts, collapse = ", ")
}

deal_hands <- function(deck, num_players, cards_each) {
  drawn <- simulate_card_draw(deck, num_players * cards_each)
  splitter <- rep(seq_len(num_players), each = cards_each)
  hands <- split(drawn, splitter)
  names(hands) <- paste("Player", seq_len(num_players))
  hands
}

main <- function() {
  set.seed(42)
  deck <- build_deck()
  hand <- simulate_card_draw(deck, 5)
  cat("Five-card draw:", paste(hand, collapse = " "), "\n")
  cat("Composition:", describe_hand(hand), "\n")
  cat("Ranks held:", paste(sort(card_rank(hand)), collapse = " "), "\n\n")

  table_hands <- deal_hands(deck, 3, 4)
  for (player in names(table_hands)) {
    cards <- table_hands[[player]]
    cat(sprintf("%-9s %s  (%s)\n", player,
                paste(cards, collapse = " "), describe_hand(cards)))
  }

  single <- simulate_card_draw(c("A", "B", "C"), 1)
  cat("\nSingle draw from a tiny deck:", single, "\n")
}

main()

