filter_df_multi_cond <- function(df, col1_name, col1_val, col2_name, col2_val) {
  validate_columns(df, c(col1_name, col2_name))
  mask1 <- df[[col1_name]] == col1_val
  mask2 <- df[[col2_name]] == col2_val
  keep <- !is.na(mask1) & !is.na(mask2) & mask1 & mask2
  df[keep, , drop = FALSE]
}

validate_columns <- function(df, required) {
  if (!is.data.frame(df)) {
    stop("df must be a data frame")
  }
  absent <- setdiff(required, colnames(df))
  if (length(absent) > 0) {
    stop(paste("unknown column(s):", paste(absent, collapse = ", ")))
  }
  invisible(TRUE)
}

describe_filter <- function(col1_name, col1_val, col2_name, col2_val) {
  left <- paste0(col1_name, " == ", format_value(col1_val))
  right <- paste0(col2_name, " == ", format_value(col2_val))
  paste(left, "&", right)
}

format_value <- function(value) {
  if (is.character(value) || is.factor(value)) {
    paste0("\"", as.character(value), "\"")
  } else {
    format(value)
  }
}

report_filter <- function(df, col1_name, col1_val, col2_name, col2_val) {
  subset_df <- filter_df_multi_cond(df, col1_name, col1_val, col2_name, col2_val)
  header <- describe_filter(col1_name, col1_val, col2_name, col2_val)
  summary_line <- paste0(nrow(subset_df), " of ", nrow(df), " rows matched")
  cat(header, "\n", sep = "")
  cat(summary_line, "\n", sep = "")
  if (nrow(subset_df) > 0) {
    print(subset_df)
  } else {
    cat("(no matching rows)\n")
  }
  cat("\n")
  invisible(subset_df)
}

main <- function() {
  df <- data.frame(
    id = 1:6,
    type = c("A", "B", "A", "C", "A", "B"),
    value = c(10, 20, 10, 30, 15, 20),
    stringsAsFactors = FALSE
  )
  report_filter(df, "type", "A", "value", 10)
  report_filter(df, "type", "B", "value", 20)
  report_filter(df, "type", "C", "value", 10)
  attempt <- try(filter_df_multi_cond(df, "type", "A", "weight", 1), silent = TRUE)
  if (inherits(attempt, "try-error")) {
    reason <- conditionMessage(attr(attempt, "condition"))
    cat("error: ", reason, "\n", sep = "")
  }
  invisible(NULL)
}

main()

