summarize_vector <- function(vec) {
  if (!is.numeric(vec)) {
    stop("summarize_vector() requires a numeric vector")
  }
  clean <- vec[!is.na(vec)]
  if (length(clean) == 0) {
    stop("summarize_vector() requires at least one non-missing value")
  }
  stats <- c(min(clean), max(clean), mean(clean), median(clean))
  names(stats) <- c("min", "max", "mean", "median")
  stats
}

stats_range <- function(stats) {
  stats[["max"]] - stats[["min"]]
}

stats_skew_hint <- function(stats) {
  gap <- stats[["mean"]] - stats[["median"]]
  tolerance <- 1e-8
  if (abs(gap) <= tolerance) {
    "symmetric"
  } else if (gap > 0) {
    "right-tailed"
  } else {
    "left-tailed"
  }
}

format_stats <- function(stats, digits = 4) {
  values <- format(round(stats, digits), trim = TRUE)
  paste(paste0(names(stats), "=", values), collapse = ", ")
}

summarize_table <- function(datasets) {
  tags <- names(datasets)
  if (is.null(tags)) {
    tags <- paste0("series", seq_along(datasets))
  }
  rows <- lapply(datasets, summarize_vector)
  matrix_form <- do.call(rbind, rows)
  rownames(matrix_form) <- tags
  matrix_form
}

report <- function(datasets) {
  summaries <- summarize_table(datasets)
  out <- character(nrow(summaries))
  for (i in seq_len(nrow(summaries))) {
    stats <- summaries[i, ]
    spread <- stats_range(stats)
    shape <- stats_skew_hint(stats)
    out[i] <- sprintf("%-10s %s | range=%s | %s",
                      rownames(summaries)[i],
                      format_stats(stats),
                      format(round(spread, 4), trim = TRUE),
                      shape)
  }
  out
}

main <- function() {
  datasets <- list(
    ascending = c(1, 2, 3, 4, 5),
    mixed = c(10, 20, 0, 5),
    withgaps = c(4, NA, 8, 100)
  )
  for (entry in report(datasets)) {
    cat(entry, "\n", sep = "")
  }
  single <- summarize_vector(c(7))
  cat("single value: ", format_stats(single), "\n", sep = "")
}

main()

