decimal_to_binary <- function(n) {
  if (!is.numeric(n) || length(n) != 1 || is.na(n)) {
    stop("decimal_to_binary expects a single numeric value")
  }
  if (n != floor(n) || n < 0) {
    stop("decimal_to_binary expects a non-negative integer")
  }
  if (n == 0) {
    return("0")
  }
  digits <- character(0)
  value <- n
  while (value > 0) {
    remainder <- value %% 2
    digits <- c(as.character(remainder), digits)
    value <- value %/% 2
  }
  paste(digits, collapse = "")
}

binary_to_decimal <- function(bits) {
  chars <- strsplit(bits, "", fixed = TRUE)[[1]]
  if (!all(chars %in% c("0", "1"))) {
    stop("binary_to_decimal expects a string of 0s and 1s")
  }
  total <- 0
  for (ch in chars) {
    total <- total * 2 + as.numeric(ch)
  }
  total
}

pad_left <- function(bits, width) {
  gap <- width - nchar(bits)
  if (gap <= 0) {
    return(bits)
  }
  filler <- paste(rep("0", gap), collapse = "")
  paste0(filler, bits)
}

conversion_table <- function(values, width = 0) {
  rendered <- vapply(values, decimal_to_binary, character(1))
  padded <- vapply(rendered, pad_left, character(1), width = width)
  data.frame(
    decimal = values,
    binary = padded,
    roundtrip = vapply(padded, binary_to_decimal, numeric(1)),
    stringsAsFactors = FALSE,
    row.names = NULL
  )
}

format_row <- function(decimal, binary, roundtrip) {
  status <- if (decimal == roundtrip) "ok" else "MISMATCH"
  sprintf("%6d -> %-12s [%s]", decimal, binary, status)
}

main <- function() {
  samples <- c(0, 1, 2, 5, 13, 64, 255, 1024)
  conversions <- conversion_table(samples, width = 8)
  report <- mapply(
    format_row,
    conversions$decimal,
    conversions$binary,
    conversions$roundtrip
  )
  cat(report, sep = "\n")
  cat("\n")
}

main()

