simple_moving_average <- function(x, window) {
  if (!is.numeric(x)) {
    stop("x must be a numeric vector")
  }
  if (length(window) != 1L || !is.numeric(window) || window < 1 || window != as.integer(window)) {
    stop("window must be a single positive integer")
  }
  window <- as.integer(window)
  n <- length(x)
  result <- rep(NA_real_, n)
  if (window > n) {
    return(result)
  }
  running <- cumsum(x)
  padded <- c(0, running)
  for (i in window:n) {
    total <- padded[i + 1L] - padded[i + 1L - window]
    result[i] <- total / window
  }
  result
}

moving_average_table <- function(x, windows) {
  columns <- lapply(windows, function(w) simple_moving_average(x, w))
  names(columns) <- paste0("sma_", windows)
  frame <- data.frame(period = seq_along(x), value = x)
  cbind(frame, as.data.frame(columns))
}

format_average <- function(value, digits = 2L) {
  if (is.na(value)) {
    return("     -")
  }
  formatC(round(value, digits), format = "f", digits = digits, width = 6)
}

report_moving_averages <- function(x, windows) {
  table <- moving_average_table(x, windows)
  header <- c("period", "value", paste0("sma", windows))
  lines <- paste(formatC(header, width = 8), collapse = " ")
  for (i in seq_len(nrow(table))) {
    cells <- c(
      formatC(table$period[i], width = 8),
      formatC(format_average(table$value[i]), width = 8)
    )
    for (w in windows) {
      column <- paste0("sma_", w)
      cells <- c(cells, formatC(format_average(table[[column]][i]), width = 8))
    }
    lines <- c(lines, paste(cells, collapse = " "))
  }
  lines
}

main <- function() {
  first <- simple_moving_average(c(10, 12, 14, 16, 18), 3)
  second <- simple_moving_average(c(1, 2, 3, 4), 2)
  cat("Example 1:", paste(ifelse(is.na(first), "NA", first), collapse = " "), "\n")
  cat("Example 2:", paste(ifelse(is.na(second), "NA", second), collapse = " "), "\n\n")

  prices <- c(21.4, 22.1, 20.8, 23.5, 24.9, 23.1, 25.6, 26.4)
  windows <- c(2L, 3L, 5L)
  report <- report_moving_averages(prices, windows)
  cat(report, sep = "\n")
  cat("\n")
}

main()

