AGE_LEVELS <- c("Child", "Teen", "Adult", "Senior")
AGE_BREAKS <- c(0, 13, 20, 65, Inf)

validate_ages <- function(ages) {
  if (!is.numeric(ages)) {
    stop("`ages` must be a numeric vector")
  }
  known_ages <- ages[!is.na(ages)]
  negative <- known_ages[known_ages < 0]
  if (length(negative) > 0) {
    stop(sprintf("negative ages are not allowed: %s",
                 paste(negative, collapse = ", ")))
  }
  invisible(TRUE)
}

categorize_ages <- function(ages) {
  validate_ages(ages)
  binned <- cut(ages,
                breaks = AGE_BREAKS,
                labels = AGE_LEVELS,
                right = FALSE,
                include.lowest = TRUE)
  factor(as.character(binned), levels = AGE_LEVELS)
}

age_group_counts <- function(ages) {
  groups <- categorize_ages(ages)
  table(groups)
}

group_summary <- function(ages) {
  groups <- categorize_ages(ages)
  known <- !is.na(groups)
  means <- tapply(ages[known], droplevels(groups[known]), mean)
  counts <- age_group_counts(ages)
  frame <- data.frame(
    group = names(counts),
    count = as.integer(counts),
    mean_age = NA_real_,
    stringsAsFactors = FALSE
  )
  matched <- match(names(means), frame$group)
  frame$mean_age[matched] <- as.numeric(means)
  frame
}

format_summary <- function(summary_frame) {
  text <- character(nrow(summary_frame))
  for (i in seq_len(nrow(summary_frame))) {
    mean_age <- summary_frame$mean_age[i]
    mean_text <- if (is.na(mean_age)) "-" else sprintf("%.1f", mean_age)
    text[i] <- sprintf("%-7s n=%2d  mean=%s",
                       summary_frame$group[i], summary_frame$count[i], mean_text)
  }
  paste(text, collapse = "\n")
}

main <- function() {
  sample_one <- c(7, 15, 30, 70)
  sample_two <- c(19, 65)
  cohort <- c(3, 11, 13, 17, 22, 41, 64, 65, 88)

  cat("Example 1:", paste(as.character(categorize_ages(sample_one)), collapse = ", "), "\n")
  cat("Example 2:", paste(as.character(categorize_ages(sample_two)), collapse = ", "), "\n\n")

  report <- format_summary(group_summary(cohort))
  cat("Cohort summary\n")
  cat(report, "\n")
}

if (identical(environment(), globalenv())) {
  main()
}

