unique_elements_in_order <- function(x) {
  if (is.null(x)) {
    return(x)
  }
  if (!is.vector(x)) {
    stop("unique_elements_in_order expects a vector")
  }
  seen <- character(0)
  keep <- logical(length(x))
  keys <- as.character(x)
  for (i in seq_along(x)) {
    key <- keys[i]
    if (is.na(key)) {
      key <- "\u0001NA"
    }
    if (!(key %in% seen)) {
      seen <- c(seen, key)
      keep[i] <- TRUE
    }
  }
  x[keep]
}

duplicate_counts <- function(x) {
  uniques <- unique_elements_in_order(x)
  labels <- as.character(uniques)
  counts <- integer(length(uniques))
  all_keys <- as.character(x)
  for (i in seq_along(uniques)) {
    counts[i] <- sum(all_keys == labels[i] | (is.na(all_keys) & is.na(labels[i])))
  }
  names(counts) <- labels
  counts
}

format_report <- function(x, label) {
  uniques <- unique_elements_in_order(x)
  counts <- duplicate_counts(x)
  removed <- length(x) - length(uniques)
  values <- paste(format(uniques, trim = TRUE), collapse = ", ")
  detail <- paste(sprintf("%s x%d", names(counts), counts), collapse = "  ")
  lines <- c(
    sprintf("%s (%d elements, type %s)", label, length(x), class(x)[1]),
    sprintf("  unique in order: %s", values),
    sprintf("  duplicates removed: %d", removed),
    sprintf("  frequencies: %s", detail)
  )
  paste(lines, collapse = "\n")
}

main <- function() {
  numbers <- c(1, 2, 2, 3, 1, 4)
  letters_in <- c('a', 'b', 'c', 'a', 'b')
  flags <- c(TRUE, FALSE, TRUE, NA, FALSE, NA)
  samples <- list(numbers = numbers, letters = letters_in, flags = flags)
  for (name in names(samples)) {
    cat(format_report(samples[[name]], name), "\n\n", sep = "")
  }
  checks <- c(
    identical(unique_elements_in_order(numbers), c(1, 2, 3, 4)),
    identical(unique_elements_in_order(letters_in), c('a', 'b', 'c')),
    identical(unique_elements_in_order(integer(0)), integer(0))
  )
  verdict <- if (all(checks)) "all expectations met" else "mismatch detected"
  cat(verdict, "\n", sep = "")
}

main()

