validate_points <- function(a, b) {
  if (!is.numeric(a) || !is.numeric(b)) {
    stop("both points must be numeric vectors")
  }
  if (length(a) != length(b)) {
    msg <- sprintf("dimension mismatch: %d vs %d", length(a), length(b))
    stop(msg)
  }
  if (length(a) == 0L) {
    stop("points must have at least one coordinate")
  }
  if (anyNA(a) || anyNA(b)) {
    stop("points must not contain missing values")
  }
  invisible(TRUE)
}

euclidean_distance_nd <- function(a, b) {
  validate_points(a, b)
  diffs <- a - b
  sqrt(sum(diffs * diffs))
}

distance_matrix <- function(points) {
  n <- length(points)
  out <- matrix(0, nrow = n, ncol = n, dimnames = list(names(points), names(points)))
  for (i in seq_len(n)) {
    for (j in seq_len(n)) {
      if (j > i) {
        d <- euclidean_distance_nd(points[[i]], points[[j]])
        out[i, j] <- d
        out[j, i] <- d
      }
    }
  }
  out
}

nearest_neighbour <- function(points, target) {
  distances <- vapply(points, euclidean_distance_nd, numeric(1), b = target)
  winner <- which.min(distances)
  list(name = names(points)[winner], distance = distances[[winner]])
}

format_point <- function(p) {
  paste0("(", paste(formatC(p, format = "g"), collapse = ", "), ")")
}

report_pair <- function(a, b) {
  distance <- euclidean_distance_nd(a, b)
  sprintf("%s -> %s : %.6f", format_point(a), format_point(b), distance)
}

main <- function() {
  cat(report_pair(c(1, 1), c(4, 5)), "\n")
  cat(report_pair(c(0, 0, 0), c(1, 1, 1)), "\n")

  cloud <- list(
    origin = c(0, 0, 0, 0),
    unit = c(1, 0, 0, 0),
    corner = c(1, 1, 1, 1),
    far = c(3, -2, 4, 1)
  )
  cat("\nPairwise distances:\n")
  print(round(distance_matrix(cloud), 4))

  probe <- c(0.9, 0.9, 0.9, 0.9)
  hit <- nearest_neighbour(cloud, probe)
  cat(sprintf("\nNearest to %s is '%s' at %.6f\n",
              format_point(probe), hit$name, hit$distance))

  failure <- tryCatch(euclidean_distance_nd(c(1, 2), c(1, 2, 3)),
                      error = function(e) conditionMessage(e))
  cat("Rejected input:", failure, "\n")
}

main()

