mean_named_vector_values <- function(v) {
  validate_named_vector(v)
  values <- unname(v)
  total <- sum(values)
  count <- length(values)
  total / count
}

validate_named_vector <- function(v) {
  if (!is.numeric(v)) {
    stop("input must be a numeric vector")
  }
  if (length(v) == 0L) {
    stop("input must contain at least one value")
  }
  labels <- names(v)
  if (is.null(labels) || any(!nzchar(labels))) {
    stop("every element of the input must be named")
  }
  if (anyDuplicated(labels) > 0L) {
    stop("element names must be unique")
  }
  invisible(TRUE)
}

deviations_from_mean <- function(v) {
  centre <- mean_named_vector_values(v)
  v - centre
}

format_named_vector <- function(v, digits = 3) {
  rounded <- round(unname(v), digits)
  pieces <- paste0(names(v), "=", rounded)
  paste(pieces, collapse = ", ")
}

report_mean <- function(v, label) {
  average <- mean_named_vector_values(v)
  shifted <- deviations_from_mean(v)
  header <- sprintf("%s: mean of (%s) is %s", label,
                    format_named_vector(v), format(average))
  detail <- sprintf("  deviations: %s", format_named_vector(shifted))
  cat(header, detail, sep = "\n")
  cat("\n")
  invisible(average)
}

main <- function() {
  first <- c(a = 10, b = 20, c = 30)
  second <- c(x = 5)
  third <- c(low = -2.5, mid = 0, high = 7.25)
  report_mean(first, "Example 1")
  report_mean(second, "Example 2")
  report_mean(third, "Mixed signs")

  combined <- c(first, third)
  grand <- mean_named_vector_values(combined)
  cat(sprintf("Grand mean over %d named values: %s\n",
              length(combined), format(grand)))
}

main()

