sublist_key <- function(vec) {
  parts <- format(vec, trim = TRUE, digits = 15)
  paste0(length(vec), ":", paste(parts, collapse = "|"))
}

validate_sublists <- function(sublists) {
  if (!is.list(sublists)) {
    stop("'sublists' must be a list of numeric vectors")
  }
  offenders <- which(!vapply(sublists, is.numeric, logical(1)))
  if (length(offenders) > 0) {
    positions <- paste(offenders, collapse = ", ")
    stop(paste0("non-numeric sublists at position(s): ", positions))
  }
  invisible(TRUE)
}

remove_duplicate_sublists <- function(sublists) {
  validate_sublists(sublists)
  seen <- new.env(hash = TRUE, parent = emptyenv())
  unique_lists <- vector("list", length(sublists))
  kept <- 0L
  for (vec in sublists) {
    key <- sublist_key(vec)
    if (!exists(key, envir = seen, inherits = FALSE)) {
      assign(key, TRUE, envir = seen)
      kept <- kept + 1L
      unique_lists[[kept]] <- vec
    }
  }
  length(unique_lists) <- kept
  unique_lists
}

duplicate_counts <- function(sublists) {
  validate_sublists(sublists)
  keys <- vapply(sublists, sublist_key, character(1))
  tallies <- table(keys)
  repeated <- tallies[tallies > 1L]
  repeated[order(names(repeated))]
}

format_sublists <- function(sublists) {
  rendered <- vapply(sublists, function(vec) {
    paste0("(", paste(format(vec, trim = TRUE), collapse = ", "), ")")
  }, character(1))
  paste(rendered, collapse = " ")
}

report <- function(label, sublists) {
  deduped <- remove_duplicate_sublists(sublists)
  removed <- length(sublists) - length(deduped)
  cat(label, "\n")
  cat("  input  :", format_sublists(sublists), "\n")
  cat("  unique :", format_sublists(deduped), "\n")
  cat("  removed:", removed, "\n")
  counts <- duplicate_counts(sublists)
  if (length(counts) > 0) {
    tally_text <- paste0("    ", names(counts), " x", as.integer(counts))
    cat("  repeats:\n", paste(tally_text, collapse = "\n"), "\n", sep = "")
  }
  invisible(deduped)
}

main <- function() {
  example1 <- list(c(1, 2), c(3, 4), c(1, 2))
  example2 <- list(c(1), c(2), c(1))
  mixed <- list(c(5, 6, 7), c(5, 6), c(5, 6, 7), numeric(0), c(5, 6), numeric(0))
  report("Example 1:", example1)
  report("Example 2:", example2)
  report("Mixed lengths:", mixed)
}

main()

