matrix_dimensions <- function(rows) {
  n_rows <- length(rows)
  n_cols <- if (n_rows == 0) 0L else length(rows[[1]])
  c(rows = n_rows, cols = n_cols)
}

report_transpose <- function(rows, label) {
  transposed <- simple_matrix_transpose(rows)
  before <- matrix_dimensions(rows)
  after <- matrix_dimensions(transposed)
