simple_matrix_transpose = function(rows) {
  if (!is.list(rows)) {
    stop("input must be a list of numeric vectors")
  }
  if (length(rows) == 0) {
    return(list())
  }
  widths = vapply(rows, length, integer(1))
  n_cols = widths[1]
  if (any(widths != n_cols)) {
    stop("all rows must have the same length")
  }
  result = vector("list", n_cols)
  for (j in seq_len(n_cols)) {
    column = vapply(rows, function(row) as.numeric(row[j]), numeric(1))
    result[[j]] = column
  }
  result
}

