intersect_three_vectors <- function(x, y, z) {
  validate_numeric_vector(x, "x")
  validate_numeric_vector(y, "y")
  validate_numeric_vector(z, "z")
  pair <- intersect_pair(x, y)
  common <- intersect_pair(pair, z)
  sort(common)
}

validate_numeric_vector <- function(v, name) {
  if (!is.numeric(v)) {
    stop(sprintf("argument '%s' must be a numeric vector", name))
  }
  if (anyNA(v)) {
    stop(sprintf("argument '%s' must not contain NA values", name))
  }
  invisible(TRUE)
}

intersect_pair <- function(x, y) {
  keep <- unique(x)
  keep[keep %in% y]
}

format_vector <- function(values) {
  if (length(values) == 0) {
    return("numeric(0)")
  }
  paste0("c(", paste(values, collapse = ", "), ")")
}

report_intersection <- function(x, y, z) {
  result <- intersect_three_vectors(x, y, z)
  inputs <- c(format_vector(x), format_vector(y), format_vector(z))
  line <- paste(inputs, collapse = " & ")
  cat(line, "->", format_vector(result), "\n")
  invisible(result)
}

summarise_overlap <- function(x, y, z) {
  result <- intersect_three_vectors(x, y, z)
  total <- length(unique(c(x, y, z)))
  share <- if (total == 0) 0 else length(result) / total
  list(common = result, universe = total, fraction = round(share, 3))
}

main <- function() {
  cases <- list(
    list(c(1, 2, 3, 4), c(3, 4, 5, 6), c(4, 5, 7)),
    list(c(1, 2), c(3, 4), c(5, 6)),
    list(c(5, 5, 1, 9, 2), c(9, 2, 2, 5), c(2, 9, 5, 5, 11))
  )
  for (case in cases) {
    report_intersection(case[[1]], case[[2]], case[[3]])
  }
  last <- cases[[length(cases)]]
  stats <- summarise_overlap(last[[1]], last[[2]], last[[3]])
  cat("last case: ", length(stats$common), " of ", stats$universe,
      " distinct values (", stats$fraction, ")\n", sep = "")
  bad <- try(intersect_three_vectors(c(1, 2), "a", c(3)), silent = TRUE)
  if (inherits(bad, "try-error")) {
    reason <- attr(bad, "condition")$message
    cat("rejected:", reason, "\n")
  }
  invisible(NULL)
}

main()

