is_column_numeric <- function(df, column) {
  if (!is.data.frame(df)) {
    stop("`df` must be a data frame")
  }
  if (!is.character(column) || length(column) != 1L) {
    stop("`column` must be a single column name")
  }
  if (!(column %in% names(df))) {
    stop(sprintf("column '%s' not found in data frame", column))
  }

  values <- df[[column]]
  if (is.list(values)) {
    flags <- vapply(values, function(x) is.numeric(x) && length(x) == 1L, logical(1))
    return(all(flags))
  }
  is.numeric(values)
}

column_kind <- function(df, column) {
  values <- df[[column]]
  if (is_column_numeric(df, column)) {
    kind <- if (is.integer(values)) "integer" else "numeric"
  } else if (is.factor(values)) {
    kind <- "factor"
  } else if (is.logical(values)) {
    kind <- "logical"
  } else {
    kind <- class(values)[1L]
  }
  kind
}

numeric_columns <- function(df) {
  names(df)[vapply(names(df), function(nm) is_column_numeric(df, nm), logical(1))]
}

describe_columns <- function(df) {
  cols <- names(df)
  info <- data.frame(
    column = cols,
    kind = vapply(cols, function(nm) column_kind(df, nm), character(1)),
    numeric = vapply(cols, function(nm) is_column_numeric(df, nm), logical(1)),
    stringsAsFactors = FALSE
  )
  rownames(info) <- NULL
  info
}

format_report <- function(info) {
  lines <- sprintf("%-10s %-10s %s", info$column, info$kind,
                   ifelse(info$numeric, "TRUE", "FALSE"))
  header <- sprintf("%-10s %-10s %s", "column", "kind", "numeric")
  c(header, lines)
}

main <- function() {
  df <- data.frame(
    A = c(1, 2),
    B = c("x", "y"),
    C = c(3L, 4L),
    D = factor(c("lo", "hi")),
    stringsAsFactors = FALSE
  )

  cat(is_column_numeric(df, "A"), "\n")
  cat(is_column_numeric(df, "B"), "\n")

  info <- describe_columns(df)
  writeLines(format_report(info))

  numeric_names <- numeric_columns(df)
  cat("numeric columns:", paste(numeric_names, collapse = ", "), "\n")

  mixed <- data.frame(id = 1:2)
  mixed$payload <- list(10, "ten")
  cat("payload numeric:", is_column_numeric(mixed, "payload"), "\n")
}

main()

