is_alphanumeric <- function(x) {
  if (!is.character(x)) {
    stop("is_alphanumeric() expects a character vector")
  }
  pattern <- "^[A-Za-z0-9]+$"
  result <- grepl(pattern, x)
  result[is.na(x)] <- NA
  result
}

classify_string <- function(x) {
  if (is.na(x)) {
    return("missing")
  }
  if (nchar(x) == 0L) {
    return("empty")
  }
  if (is_alphanumeric(x)) {
    letters_only <- grepl("^[A-Za-z]+$", x)
    digits_only <- grepl("^[0-9]+$", x)
    if (letters_only) {
      return("letters only")
    }
    if (digits_only) {
      return("digits only")
    }
    return("letters and digits")
  }
  "contains non-alphanumeric characters"
}

offending_characters <- function(x) {
  if (is.na(x) || nchar(x) == 0L) {
    return(character(0))
  }
  chars <- strsplit(x, "", fixed = TRUE)[[1]]
  bad <- chars[!grepl("[A-Za-z0-9]", chars)]
  unique(bad)
}

format_row <- function(x) {
  label <- if (is.na(x)) "<NA>" else paste0("\"", x, "\"")
  verdict <- is_alphanumeric(x)
  flag <- if (is.na(verdict)) "NA" else toupper(as.character(verdict))
  kind <- classify_string(x)
  bad <- offending_characters(x)
  detail <- if (length(bad) > 0) {
    paste0(" [bad: ", paste(bad, collapse = " "), "]")
  } else {
    ""
  }
  sprintf("%-22s %-5s %s%s", label, flag, kind, detail)
}

report <- function(samples) {
  header <- sprintf("%-22s %-5s %s", "input", "ok", "classification")
  lines <- vapply(samples, format_row, character(1), USE.NAMES = FALSE)
  c(header, strrep("-", nchar(header)), lines)
}

