  samples <- c("Rprogramming123", "R programming!", "12345", "alpha",
               "tab\tseparated", "", NA_character_)
  output <- report(samples)
  cat(output, sep = "\n")
  cat("\n")
  passing <- sum(is_alphanumeric(samples), na.rm = TRUE)
  cat(sprintf("%d of %d inputs are alphanumeric\n", passing, length(samples)))
}

