parse_csv_line <- function(line) {
  if (!is.character(line) || length(line) != 1L) {
    stop("parse_csv_line expects a single character string")
  }
  if (is.na(line)) {
    stop("parse_csv_line expects a non-missing string")
  }
  chars <- strsplit(line, "", fixed = TRUE)[[1]]
  fields <- character(0)
  current <- ""
  for (ch in chars) {
    if (ch == ",") {
      fields <- c(fields, current)
      current <- ""
    } else {
      current <- paste0(current, ch)
    }
  }
  c(fields, current)
}

trim_field <- function(field) {
  stripped <- sub("^[[:space:]]+", "", field)
  sub("[[:space:]]+$", "", stripped)
}

parse_csv_table <- function(text_lines, trim = TRUE) {
  parsed <- lapply(text_lines, parse_csv_line)
  if (trim) {
    parsed <- lapply(parsed, function(fields) {
      vapply(fields, trim_field, character(1), USE.NAMES = FALSE)
    })
  }
  parsed
}

column_widths <- function(rows) {
  ncols <- max(vapply(rows, length, integer(1)))
  widths <- integer(ncols)
  for (fields in rows) {
    for (i in seq_along(fields)) {
      widths[i] <- max(widths[i], nchar(fields[i]))
    }
  }
  widths
}

format_table <- function(rows) {
  widths <- column_widths(rows)
  vapply(rows, function(fields) {
    padded <- character(length(fields))
    for (i in seq_along(fields)) {
      padded[i] <- formatC(fields[i], width = widths[i], flag = "-")
    }
    trim_field(paste(padded, collapse = " | "))
  }, character(1))
}

main <- function() {
  simple <- parse_csv_line("apple,banana,cherry")
  numbers <- parse_csv_line("1,2,3")
  cat("fields:", paste(simple, collapse = "/"), "\n")
  cat("numbers:", paste(numbers, collapse = "/"), "\n")

  source_text <- c("name, quantity, price",
                   "apple, 12, 0.50",
                   "banana, 5, 0.25",
                   "cherry, 130, 0.05")
  parsed <- parse_csv_table(source_text)
  report <- format_table(parsed)
  cat(report, sep = "\n")
  cat("\n")
  invisible(parsed)
}

main()

