simulate_random_walk_1d <- function(n_steps, start = 0) {
  if (!is.numeric(n_steps) || length(n_steps) != 1 || is.na(n_steps)) {
    stop("n_steps must be a single non-missing number")
  }
  if (n_steps < 0 || n_steps != as.integer(n_steps)) {
    stop("n_steps must be a non-negative whole number")
  }
  if (!is.numeric(start) || length(start) != 1 || is.na(start)) {
    stop("start must be a single non-missing number")
  }
  n <- as.integer(n_steps)
  if (n == 0L) {
    return(start)
  }
  steps <- sample(c(-1L, 1L), size = n, replace = TRUE)
  positions <- start + c(0L, cumsum(steps))
  positions
}

walk_summary <- function(positions) {
  n_steps <- length(positions) - 1L
  displacement <- positions[length(positions)] - positions[1]
  returns <- sum(positions[-1] == positions[1])
  list(
    steps = n_steps,
    start = positions[1],
    final = positions[length(positions)],
    displacement = displacement,
    min = min(positions),
    max = max(positions),
    returns_to_start = returns
  )
}

format_walk <- function(positions, max_shown = 12L) {
  shown <- positions
  suffix <- ""
  if (length(positions) > max_shown) {
    shown <- positions[seq_len(max_shown)]
    suffix <- paste0(" ... (", length(positions) - max_shown, " more)")
  }
  paste0("[", paste(shown, collapse = ", "), "]", suffix)
}

report_walk <- function(positions) {
  info <- walk_summary(positions)
  header <- sprintf("walk of %d steps from %g", info$steps, info$start)
  body <- sprintf(
    "  path:         %s\n  final:        %g\n  displacement: %g\n  range:        [%g, %g]\n  returns:      %d",
    format_walk(positions), info$final, info$displacement,
    info$min, info$max, info$returns_to_start
  )
  paste(header, body, sep = "\n")
}

mean_abs_displacement <- function(n_walks, n_steps, start = 0) {
  displacements <- vapply(
    seq_len(n_walks),
    function(i) {
      walk <- simulate_random_walk_1d(n_steps, start)
      abs(walk[length(walk)] - start)
    },
    numeric(1)
  )
  mean(displacements)
}

main <- function() {
  set.seed(42)
  short <- simulate_random_walk_1d(3, 0)
  offset <- simulate_random_walk_1d(2, 5)
  cat(report_walk(short), "\n\n", sep = "")
  cat(report_walk(offset), "\n\n", sep = "")
  long <- simulate_random_walk_1d(50, 0)
  cat(report_walk(long), "\n\n", sep = "")
  avg <- mean_abs_displacement(2000, 100)
  cat(sprintf("mean |displacement| over 2000 walks of 100 steps: %.3f\n", avg))
  cat(sprintf("theoretical sqrt(2n/pi):                          %.3f\n",
              sqrt(2 * 100 / pi)))
}

main()

