count_substring_occurrences <- function(text, pattern) {
  if (!is.character(text) || length(text) != 1L || is.na(text)) {
    stop("'text' must be a single non-missing character string")
  }
  if (!is.character(pattern) || length(pattern) != 1L || is.na(pattern)) {
    stop("'pattern' must be a single non-missing character string")
  }
  n <- nchar(text)
  m <- nchar(pattern)
  if (m == 0L || m > n) {
    return(0L)
  }
  starts <- seq_len(n - m + 1L)
  slices <- substring(text, starts, starts + m - 1L)
  sum(slices == pattern)
}

occurrence_positions <- function(text, pattern) {
  m <- nchar(pattern)
  if (m == 0L || m > nchar(text)) {
    return(integer(0))
  }
  starts <- seq_len(nchar(text) - m + 1L)
  hits <- substring(text, starts, starts + m - 1L) == pattern
  starts[hits]
}

count_non_overlapping <- function(text, pattern) {
  positions <- occurrence_positions(text, pattern)
  m <- nchar(pattern)
  kept <- 0L
  next_allowed <- 1L
  for (p in positions) {
    if (p >= next_allowed) {
      kept <- kept + 1L
      next_allowed <- p + m
    }
  }
  kept
}

format_report <- function(text, pattern) {
  total <- count_substring_occurrences(text, pattern)
  disjoint <- count_non_overlapping(text, pattern)
  positions <- occurrence_positions(text, pattern)
  where <- if (length(positions) == 0L) "none" else paste(positions, collapse = ", ")
  sprintf("%-14s in %-14s -> %d (non-overlapping: %d) at [%s]",
          sQuote(pattern), sQuote(text), total, disjoint, where)
}

main <- function() {
  cases <- list(
    c("banana", "ana"),
    c("Mississippi", "ss"),
    c("Mississippi", "SS"),
    c("aaaa", "aa"),
    c("abc", "")
  )
  report <- vapply(cases, function(case) format_report(case[1L], case[2L]),
                   character(1))
  cat(report, sep = "\n")
  cat("\n")
  grand_total <- sum(vapply(cases,
                            function(case) {
                              count_substring_occurrences(case[1L], case[2L])
                            },
                            numeric(1)))
  cat(sprintf("total matches across %d cases: %d\n",
              length(cases), as.integer(grand_total)))
}

main()

