validate_input <- function(vec, n) {
  if (!is.numeric(vec)) {
    stop("vec must be a numeric vector")
  }
  cleaned <- vec[!is.na(vec)]
  if (length(cleaned) == 0L) {
    stop("vec must contain at least one non-missing value")
  }
  count <- as.integer(n)
  if (is.na(count) || count < 1L || count > length(cleaned)) {
    stop("n must be an integer between 1 and the number of usable elements")
  }
  list(values = cleaned, n = count)
}

partition_desc <- function(values, left, right, pivot_index) {
  pivot <- values[pivot_index]
  values[pivot_index] <- values[right]
  values[right] <- pivot
  store <- left
  for (i in seq.int(left, right - 1L)) {
    if (values[i] > pivot) {
      swap <- values[store]
      values[store] <- values[i]
      values[i] <- swap
      store <- store + 1L
    }
  }
  values[right] <- values[store]
  values[store] <- pivot
  list(values = values, index = store)
}

quickselect_desc <- function(values, k) {
  left <- 1L
  right <- length(values)
  repeat {
    if (left == right) {
      return(values[left])
    }
    pivot_index <- left + (right - left) %/% 2L
    step <- partition_desc(values, left, right, pivot_index)
    values <- step$values
    position <- step$index
    if (position == k) {
      return(values[position])
    } else if (k < position) {
      right <- position - 1L
    } else {
      left <- position + 1L
    }
  }
}

find_nth_largest <- function(vec, n) {
  checked <- validate_input(vec, n)
  quickselect_desc(checked$values, checked$n)
}

describe_rank <- function(vec, n) {
  result <- find_nth_largest(vec, n)
  label <- switch(as.character(n), "1" = "1st", "2" = "2nd", "3" = "3rd", paste0(n, "th"))
  sprintf("%s largest of [%s] is %s", label, paste(vec, collapse = ", "), format(result))
}

main <- function() {
  cases <- list(
    list(vec = c(3, 1, 4, 1, 5, 9, 2, 6), n = 2),
    list(vec = c(10, 20, 30), n = 1),
    list(vec = c(-7.5, 0, 12.25, 4), n = 3)
  )
  for (case in cases) {
    cat(describe_rank(case$vec, case$n), "\n")
  }
}

main()

