main = function() {
  numbers = c(1, NA, 2, NA, 3)
  letters_in = c('a', NA, 'b')
  flags = c(TRUE, NA, FALSE, NA)
  all_missing = c(NA, NA)
  samples = list(numbers = numbers, letters = letters_in,
                  flags = flags, empty = all_missing)
  report(samples)

  frame = data.frame(score = c(10, NA, 30), grade = c('A', 'B', NA),
                      stringsAsFactors = FALSE)
  tidy = clean_columns(frame)
  cat("data frame columns after cleaning:\n")
  for (nm in names(tidy)) {
    cat(" ", nm, "->", format_vector(tidy[[nm]]), "\n")
  }
}

main()
